window.__BOOK__={"meta": {"title_ru": "Маленький принц", "title_zh": "小王子", "author_ru": "Антуан де Сент-Экзюпери", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "ru-RU-SvetlanaNeural (edge-tts)", "ipa_note": "宽式音位转写：标注辅音腭化/清浊同化/词末清化，不标重音、不做非重读元音弱化", "n_chapters": 28, "n_paras": 110, "n_sents": 1581}, "chapters": [{"id": "ch00", "title_ru": "Посвящение", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"ru": "Леону Верту", "zh": "列翁·维尔特", "t": [100, 1226]}]}, {"id": "ch00p01", "audio": true, "sents": [{"ru": "Я прошу прощения у детей за то, что посвятил эту книжку взрослому человеку.", "zh": "请孩子们原谅我把这本书献给了这位大人。", "t": [100, 5738]}, {"ru": "Однако у меня есть веское оправдание.", "zh": "然而，我有充分的理由。", "t": [5738, 9288]}, {"ru": "Этот взрослый — мой лучший друг на свете.", "zh": "这位大人——我世间最挚友。", "t": [9288, 12800]}, {"ru": "Есть и другое оправдание — он все понимает, даже книжки, написанные для детей.", "zh": "他懂得一切，即便是对孩子写的书。", "t": [12800, 18800]}, {"ru": "У меня есть и третье оправдание — этот взрослый живет во Франции, где голодает и мерзнет.", "zh": "这位大人身处法国，忍饥受寒。", "t": [18800, 25038]}, {"ru": "Конечно же, его надо утешить.", "zh": "当然，他需要安慰。", "t": [25038, 28075]}, {"ru": "А если этих оправданий недостаточно, я охотно посвящу эту книжку ребенку, которым этот взрослый когда-то был.", "zh": "若这些理由尚不足够，我乐意将此书献给那位曾经是孩子的他。", "t": [28075, 35275]}, {"ru": "Ведь все взрослые когда-то были детьми, хотя мало кто из них помнит об этом.", "zh": "大人们曾经都是孩子，尽管很少有人记得这一点。", "t": [35275, 40388]}, {"ru": "Поэтому я исправляю это посвящение: Леону Верту, когда он был маленьким мальчиком", "zh": "因此，我将此献词修正：献给我的小男孩列翁·维尔特。", "t": [40388, 45613]}]}]}, {"id": "ch01", "title_ru": "Глава 1", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"ru": "Когда мне было шесть лет, я увидел однажды в книжке про тропические леса удивительный рисунок.", "zh": "六岁时，我在一本关于热带森林的书里瞥见了一幅奇异的插画。", "t": [100, 6475]}, {"ru": "Книжка называлась «Житейские истории».", "zh": "那本书名叫《人生故事》。", "t": [6475, 10250]}, {"ru": "На рисунке был изображен удав, который глотал какого-то зверька.", "zh": "图上画着一条蟒蛇正在吞食一只小动物。", "t": [10250, 15000]}, {"ru": "Вот как это примерно выглядело.", "zh": "这大概就是它的样子。", "t": [15000, 16887]}]}, {"id": "ch01p01", "audio": true, "sents": [{"ru": "В книге говорилось, что удавы глотают свою добычу целиком, не разжевывая.", "zh": "书中说，蟒蛇将猎物整个吞下，未曾咀嚼。", "t": [100, 5825]}, {"ru": "А потом они не могут больше ползать и спят в течение шести месяцев, пока все не переварят.", "zh": "然后它们便无法再爬行，要睡上六个月才能消化完毕。", "t": [5825, 10874]}]}, {"id": "ch01p02", "audio": true, "sents": [{"ru": "В то время я часто мечтал о приключениях в джунглях, и поэтому тоже нарисовал цветным карандашом рисунок.", "zh": "那时，我常梦想着丛林探险，因此也用彩色铅笔画了一幅画。", "t": [100, 7012]}, {"ru": "Это был мой первый рисунок.", "zh": "这是我第一幅画。", "t": [7012, 9700]}, {"ru": "Он был примерно таким.", "zh": "它大概就是这副模样。", "t": [9700, 11200]}]}, {"id": "ch01p03", "audio": true, "sents": [{"ru": "Я показал мой шедевр взрослым и спросил у них, не страшно ли им.", "zh": "我把我的杰作展示给大人看，问他们是否感到害怕。", "t": [100, 5062]}, {"ru": "И они мне ответили — что может быть страшного в шляпе?", "zh": "他们回答说——一顶帽子有什么可怕的？", "t": [5062, 9038]}, {"ru": "Однако на моем рисунке была изображена не шляпа.", "zh": "然而，我的画上并非是一顶帽子。", "t": [9038, 12850]}, {"ru": "Это был удав, который переваривал слона.", "zh": "这是一条蟒蛇正在消化大象。", "t": [12850, 16450]}, {"ru": "Тогда для ясности я нарисовал, что было у удава внутри, чтобы взрослые могли это понять.", "zh": "于是，为了让他们明白，我画出了蟒蛇体内的景象。", "t": [16450, 22575]}, {"ru": "Им ведь всегда приходится все растолковывать.", "zh": "他们总是得一一解释清楚。", "t": [22575, 26050]}, {"ru": "Мой второй рисунок был таким.", "zh": "我的第二幅画便是如此。", "t": [26050, 27950]}]}, {"id": "ch01p04", "audio": true, "sents": [{"ru": "Но взрослые мне посоветовали не рисовать удавов, ни снаружи, ни изнутри, а заняться лучше географией, историей, арифметикой и правописанием.", "zh": "大人们建议我别画蟒蛇，无论是外表还是内部，最好还是去学习地理、历史、算术和语法。", "t": [100, 9738]}, {"ru": "Вот почему в шесть лет я перестал мечтать стать знаменитым художником.", "zh": "六岁时，我不再梦想成为一名著名画家。", "t": [9738, 14650]}, {"ru": "Я был разочарован полным провалом моих рисунков: первого и второго.", "zh": "我的两幅画均以彻底失败告终，我感到失望至极。", "t": [14650, 19912]}, {"ru": "Взрослые ведь сами ничего не понимают, а детям трудно снова и снова все им растолковывать.", "zh": "大人们自己都不懂，而向他们一遍又一遍解释孩子们又何其艰难。", "t": [19912, 26062]}, {"ru": "Поэтому мне пришлось избрать другую профессию.", "zh": "因此，我不得不选择另一门职业。", "t": [26062, 29875]}, {"ru": "Я научился летать на самолетах.", "zh": "我学会了驾驶飞机。", "t": [29875, 32912]}, {"ru": "И я облетел почти весь мир.", "zh": "我飞越了几乎整个世界。", "t": [32912, 35800]}, {"ru": "Так что знание географии мне помогло.", "zh": "地理知识对我大有裨益。", "t": [35800, 38975]}, {"ru": "Я научился с первого взгляда отличать Китай от Аризоны.", "zh": "我一眼便能辨出中国与亚利桑那。", "t": [38975, 43362]}, {"ru": "А это полезно, когда заплутаешь в ночи.", "zh": "夜航迷路时，这便派上了用场。", "t": [43362, 46888]}, {"ru": "В течение жизни у меня была целая куча встреч с кучей серьезных людей.", "zh": "我一生中遇见了许多严肃的人。", "t": [46888, 51900]}, {"ru": "Я часто жил среди взрослых.", "zh": "我常与成人为伍。", "t": [51900, 54700]}, {"ru": "Я их нередко разглядывал вблизи, хотя это и не улучшило моего мнения о них.", "zh": "我常近距离观察他们，但这并未改善我对他们的看法。", "t": [54700, 60238]}, {"ru": "Когда я встречал взрослого, который казался мне более понятливым, я проделывал над ним опыт.", "zh": "当我遇到一个看似更通情达理的大人时，我便对他进行试验。", "t": [60238, 66250]}, {"ru": "Я показывал ему свой первый рисунок, который всегда хранил при себе.", "zh": "我向他展示了我始终珍藏的第一幅画。", "t": [66250, 71138]}, {"ru": "Мне хотелось узнать, насколько этот взрослый понятлив.", "zh": "我想知道这位大人是否真的明理。", "t": [71138, 75438]}, {"ru": "Однако он мне всегда отвечал, что это шляпа.", "zh": "然而他总是回答我说，这是一顶帽子。", "t": [75438, 79150]}, {"ru": "И поэтому я не рассказывал ему ни об удавах, ни о тропических лесах, ни о звездах.", "zh": "因此，我便没向他提及过蟒蛇、热带森林和星星。", "t": [79150, 84938]}, {"ru": "Я к нему приноравливался.", "zh": "我逐渐适应了他。", "t": [84938, 87538]}, {"ru": "Я говорил с ним о бридже, о гольфе, о политике и о галстуках.", "zh": "我与他谈论桥牌、高尔夫、政治和领带。", "t": [87538, 92688]}, {"ru": "И этот взрослый был вполне доволен знакомству с таким здравомыслящим человеком, как я.", "zh": "这位大人对我的通情达理颇感满意。", "t": [92688, 97476]}]}]}, {"id": "ch02", "title_ru": "Глава 2", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"ru": "Потом я жил один, и мне не с кем было поговорить по-настоящему.", "zh": "此后，我独守孤寂，无人可倾心交谈。", "t": [100, 4675]}, {"ru": "Так продолжалось до тех пор, пока шесть лет назад я не попал в аварию над пустыней Сахарой.", "zh": "如此持续，直至六年前，我在撒哈拉沙漠上空遭遇了事故。", "t": [4675, 10550]}, {"ru": "Что-то сломалось в моторе моего самолета.", "zh": "我的飞机引擎出了故障。", "t": [10550, 13925]}, {"ru": "И поскольку со мной не было ни механика, ни пассажиров, я решил самостоятельно справиться с этой трудной поломкой.", "zh": "既然身边既无机械师，亦无乘客，我便决定亲自应对这棘手的故障。", "t": [13925, 20912]}, {"ru": "Воды у меня было немного — всего на восемь дней.", "zh": "我的水仅够维持八日。", "t": [20912, 24750]}, {"ru": "Вечером первого дня я заснул на песке в тысяче миль от человеческого жилья.", "zh": "夜幕降临，我在千里之外的人烟稀少之地，沉睡于沙丘之上。", "t": [24750, 29838]}, {"ru": "Я был более одинок, чем потерпевший кораблекрушение человек на плоту посреди океана.", "zh": "我比那在汪洋中孤舟失事的漂泊者还要孤独。", "t": [29838, 36025]}, {"ru": "Поэтому вы можете представить мое удивление, когда на рассвете меня разбудил чей-то тоненький голосок.", "zh": "因此，当黎明的第一缕曙光唤醒我时，我惊讶得无法言喻。", "t": [36025, 42638]}, {"ru": "Он сказал: — Пожалуйста… нарисуй мне барашка!", "zh": "他请求道：“请……给我画一只羊吧！”", "t": [42638, 46512]}, {"ru": "— Что?", "zh": "你说什么？", "t": [46512, 47975]}, {"ru": "— Нарисуй мне барашка!", "zh": "画一只羊吧！", "t": [47975, 50325]}, {"ru": "Я вскочил на ноги, как будто рядом сверкнула молния.", "zh": "我猛地站起身，仿佛身旁闪过一道闪电。", "t": [50325, 54712]}, {"ru": "Я изо всех сил протер глаза и осмотрелся вокруг.", "zh": "我用力擦了擦眼睛，环顾四周。", "t": [54712, 58788]}, {"ru": "И я увидел совершенно необыкновенного малыша, который с серьезным видом меня разглядывал.", "zh": "我瞥见了一个模样奇特的小家伙，他正一本正经地打量着我。", "t": [58788, 64750]}, {"ru": "Вот самое лучшее его изображение, которое мне удалось сделать позже.", "zh": "这就是后来我为他画的最成功的肖像画。", "t": [64750, 69975]}, {"ru": "Хотя на моем рисунке он не так хорош, как на самом деле.", "zh": "尽管画中的他不如真人那般出色。", "t": [69975, 74588]}, {"ru": "Но это не моя вина.", "zh": "这不是我的错。", "t": [74588, 76900]}, {"ru": "Ведь когда мне было шесть лет, взрослые отбили у меня охоту стать художником, и я не научился рисовать ничего кроме удавов снаружи и изнутри.", "zh": "六岁那年，大人们夺走了我成为画家的愿望，我只学会了画蟒蛇的内外轮廓。", "t": [76900, 84813]}]}, {"id": "ch02p01", "audio": true, "sents": [{"ru": "Итак, я таращился во все глаза на это удивительное явление.", "zh": "我瞪大了眼睛，凝视这奇异的景象。", "t": [100, 4962]}, {"ru": "Не забывайте — ведь я находился в тысяче миль от любого жилья.", "zh": "别忘了——我身处千里之外，无人烟之地。", "t": [4962, 9362]}, {"ru": "А малыш не казался мне ни заблудившимся, ни испуганным, ни умирающим от голода или жажды.", "zh": "他看上去既不迷路，也不害怕，也不像是饿死或渴死的。", "t": [9362, 15412]}, {"ru": "Он был совершенно не похож на ребенка, потерявшегося посреди пустыни за сотни миль от человеческого жилья.", "zh": "他看上去绝非是在千里之外荒漠中迷失的孩子。", "t": [15412, 22000]}, {"ru": "Когда я снова обрел дар речи, я спросил его: — Но… что ты тут делаешь?", "zh": "当我恢复说话的能力，我问他：“但……你在这里做什么？”", "t": [22000, 27275]}, {"ru": "А он в ответ тихо и серьезно повторил: — Пожалуйста… нарисуй мне барашка!", "zh": "他轻声而认真地说：“请……给我画一只羊吧。”", "t": [27275, 32600]}, {"ru": "Поскольку все случившееся казалось мне неразрешимой и впечатляющей тайной, я не осмелился отказать.", "zh": "鉴于这一切在我看来如同一个无法破解且令人震撼的谜团，我不敢拒绝。", "t": [32600, 39288]}, {"ru": "И как бы ни казалось мне это неуместным в тысяче миль от человеческого жилья, на границе жизни и смерти, я вынул из кармана листок бумаги и авторучку.", "zh": "即便在这千里之外，远离人烟，生死攸关之际，我还是从口袋里掏出了一张纸和一支钢笔。", "t": [39288, 48200]}, {"ru": "Однако я вспомнил, что в основном изучал географию, историю, арифметику и правописание.", "zh": "然而，我记起自己主要研习的是地理、历史、算术和语法。", "t": [48200, 54925]}, {"ru": "Поэтому с несколько расстроенным видом я сказал малышу, что не умею рисовать.", "zh": "因此，我带着几分沮丧对那孩子说，我不会画画。", "t": [54925, 60125]}, {"ru": "Но он мне ответил: — Неважно.", "zh": "没关系。", "t": [60125, 63050]}, {"ru": "Нарисуй барашка.", "zh": "画一只羊吧。", "t": [63050, 65262]}, {"ru": "Поскольку я никогда не изображал барашков, я повторил для него одну из двух картинок, которые умел рисовать, — удава снаружи.", "zh": "于是，我便画了一只我唯一会画的蛇。", "t": [65262, 73162]}, {"ru": "И был чрезвычайно удивлен, когда малыш мне ответил: — Нет, нет!", "zh": "他惊讶地回答：“不，不！”", "t": [73162, 78200]}, {"ru": "Мне не нужен слон в удаве.", "zh": "我不要蛇肚子里的象。", "t": [78200, 80825]}, {"ru": "Удав слишком опасен, а слон слишком велик.", "zh": "蟒蛇太可怕，象又太大。", "t": [80825, 84688]}, {"ru": "А у меня дома все очень маленькое.", "zh": "在我家地方很小。", "t": [84688, 87925]}, {"ru": "Мне нужен барашек.", "zh": "我需要一只羊。", "t": [87925, 90262]}, {"ru": "Нарисуй мне барашка.", "zh": "画一只羊吧。", "t": [90262, 92625]}, {"ru": "Тогда я нарисовал его.", "zh": "于是，我便画出了他。", "t": [92625, 94188]}]}, {"id": "ch02p02", "audio": true, "sents": [{"ru": "Он посмотрел на него внимательно и сказал: — Нет.", "zh": "他仔细端详了画，然后说：“不。”", "t": [100, 3875]}, {"ru": "Этот слишком хилый.", "zh": "这羊太瘦弱了。", "t": [3875, 6275]}, {"ru": "Нарисуй другого.", "zh": "画另一只。", "t": [6275, 8400]}, {"ru": "И я нарисовал второго барашка.", "zh": "我又画了一只小羊。", "t": [8400, 10450]}]}, {"id": "ch02p03", "audio": true, "sents": [{"ru": "Мой новый знакомый снисходительно улыбнулся.", "zh": "他宽容地微笑着。", "t": [100, 3738]}, {"ru": "— Не видишь разве?", "zh": "你难道没看见吗？", "t": [3738, 5788]}, {"ru": "— Это не барашек, а баран.", "zh": "这不是小羊，是公羊。", "t": [5788, 8375]}, {"ru": "У него же рога…", "zh": "它长着角呢。", "t": [8375, 9376]}]}, {"id": "ch02p04", "audio": true, "sents": [{"ru": "Тогда я снова переделал свой рисунок.", "zh": "于是，我又重新画了一次。", "t": [100, 2462]}]}, {"id": "ch02p05", "audio": true, "sents": [{"ru": "Но он отказался и от него, как и от предыдущих: — Этот барашек слишком старый.", "zh": "这只羊也太老了。", "t": [100, 5700]}, {"ru": "А мне нужен барашек, который будет жить долго.", "zh": "我需要一只能活很久的羊。", "t": [5700, 9412]}, {"ru": "Тогда я потерял терпение, ведь мне нужно было спешить с починкой моего мотора.", "zh": "那时我失去了耐心，因为必须尽快修理我的发动机。", "t": [9412, 14600]}, {"ru": "Я нацарапал такой рисунок и небрежно заметил:", "zh": "我草草地画了一幅画，漫不经心地说：", "t": [14600, 17438]}]}, {"id": "ch02p06", "audio": true, "sents": [{"ru": "— Вот тебе ящик.", "zh": "这便是一只箱子。", "t": [100, 2425]}, {"ru": "Барашек, который тебе нужен, сидит внутри.", "zh": "那你要的绵羊就坐在箱子里面。", "t": [2425, 6288]}, {"ru": "Однако я был очень удивлен, когда увидел, как просияло лицо моего юного критика: — Это именно то, что я хотел!", "zh": "然而，当我看到我的小评判家脸上露出了灿烂的笑容时，我十分惊讶——这正是我所想要的！", "t": [6288, 13950]}, {"ru": "Как ты думаешь — этому барашку надо много травы?", "zh": "你觉得这绵羊需要很多草吗？", "t": [13950, 17750]}, {"ru": "— А что?", "zh": "那又如何？", "t": [17750, 19362]}, {"ru": "— Потому, что у меня все очень маленькое…", "zh": "因为我的家地方很小……", "t": [19362, 21862]}, {"ru": "— Уверен, ему хватит.", "zh": "我确信，这足够了。", "t": [21862, 24238]}, {"ru": "Ведь он совсем маленький.", "zh": "它实在太小了。", "t": [24238, 26912]}, {"ru": "Он склонился к рисунку.", "zh": "他俯身细看画。", "t": [26912, 29450]}, {"ru": "— Не такой уж и маленький.", "zh": "倒也并非很小。", "t": [29450, 32138]}, {"ru": "Смотри-ка!", "zh": "瞧瞧！", "t": [32138, 33950]}, {"ru": "Он заснул.", "zh": "他睡着了。", "t": [33950, 35788]}, {"ru": "Так я познакомился с маленьким принцем.", "zh": "就这样，我遇见了小王子。", "t": [35788, 38150]}]}]}, {"id": "ch03", "title_ru": "Глава 3", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"ru": "Я не сразу понял, откуда он появился.", "zh": "我并未立刻明白他来自何方。", "t": [100, 3462]}, {"ru": "Маленький принц задавал мне много вопросов и, казалось, совсем не слушал, что спрашиваю его я.", "zh": "小王子向我提问连连，仿佛对我的询问全然不闻不问。", "t": [3462, 9950]}, {"ru": "Однако, вслушиваясь в его случайно оброненные слова, я постепенно понял, в чем дело.", "zh": "然而，细听他无意间说出的只言片语，我渐渐弄懂了其中的原委。", "t": [9950, 16225]}, {"ru": "Когда он впервые заметил мой самолет (я не буду его рисовать — такая картинка для меня слишком сложная), то спросил у меня: — Что это за штука?", "zh": "他初次见到我的飞机（我不打算画它——对我来说这太复杂了），便问我：“这是什么玩意儿？”", "t": [16225, 24875]}, {"ru": "— Это не штука.", "zh": "这不是玩意儿。", "t": [24875, 26862]}, {"ru": "Это самолет.", "zh": "这是飞机。", "t": [26862, 28900]}, {"ru": "Он летает.", "zh": "它会飞。", "t": [28900, 30825]}, {"ru": "Это мой самолет.", "zh": "这是我的飞机。", "t": [30825, 32988]}, {"ru": "И я с гордостью рассказал ему, что я летал на нем.", "zh": "我自豪地告诉他，我曾驾驶它翱翔天际。", "t": [32988, 36900]}, {"ru": "— Вот как?", "zh": "这就奇了。", "t": [36900, 38662]}, {"ru": "Значит, ты упал с неба?", "zh": "那你是从天上掉下来的？", "t": [38662, 41575]}, {"ru": "— Да, — скромно ответил я.", "zh": "是的，我谦逊地回答。", "t": [41575, 43562]}, {"ru": "— А…", "zh": "啊…", "t": [43562, 44688]}, {"ru": "Это забавно…", "zh": "这真有趣…", "t": [44688, 46575]}, {"ru": "Маленький принц звонко рассмеялся, и это меня задело.", "zh": "小王子清脆地笑了，这笑声刺痛了我。", "t": [46575, 50838]}, {"ru": "Мне казалось, что к моему бедственному положению стоило отнестись серьезно.", "zh": "这不幸的境遇，理当认真对待。", "t": [50838, 56200]}, {"ru": "Потом он добавил: — Значит, ты тоже с неба.", "zh": "那么，你也是从天上来的。", "t": [56200, 59938]}, {"ru": "А с какой планеты?", "zh": "你是从哪个星球来的？", "t": [59938, 62088]}, {"ru": "Тут я начал догадываться о тайне его появления и спросил его напрямик: — Так ты с другой планеты?", "zh": "我开始猜疑他出现的秘密，便直接问他：“你是从另一个星球来的？”", "t": [62088, 68238]}, {"ru": "Однако он мне не ответил.", "zh": "他却并未回答。", "t": [68238, 70838]}, {"ru": "Он лишь покачал головой, глядя на мой самолет: — Пожалуй, на этой штуке ты не мог прилететь совсем издалека…", "zh": "他只是看着我的飞机轻轻摇头：“或许，你不可能乘坐这东西从很远处飞来……”", "t": [70838, 77675]}, {"ru": "Он замолчал и размышлял довольно долго.", "zh": "他沉默了，沉思良久。", "t": [77675, 80100]}]}, {"id": "ch03p01", "audio": true, "sents": [{"ru": "Потом он вытащил из кармана мой рисунок с барашком и стал рассматривать этот бесценный подарок.", "zh": "他随后从口袋里掏出我画的绵羊，细细端详这份无价之礼。", "t": [100, 6012]}, {"ru": "Можете себе представить, насколько я был удивлен этими его словами о других планетах.", "zh": "我惊讶得无法想象。", "t": [6012, 12038]}, {"ru": "Поэтому я постарался узнать об этом побольше.", "zh": "因此，我尽力了解更多详情。", "t": [12038, 15588]}, {"ru": "— Откуда же ты прибыл, мой маленький дружок?", "zh": "你这个小家伙，是从哪里来的呢？", "t": [15588, 18888]}, {"ru": "Где это там «у тебя»?", "zh": "这究竟在哪儿“你”那儿？", "t": [18888, 21662]}, {"ru": "Куда ты хочешь забрать моего барашка?", "zh": "你打算把我的小羊带到哪里去？", "t": [21662, 23850]}]}, {"id": "ch03p02", "audio": true, "sents": [{"ru": "Он помолчал и ответил задумчиво: — Хорошо, что ты нарисовал его в ящичке.", "zh": "他沉默片刻，若有所思地回答道：“谢谢你，你把它画在箱子里了。”", "t": [100, 5412]}, {"ru": "По ночам он будет в нем спать.", "zh": "夜晚，它将在此安眠。", "t": [5412, 8162]}, {"ru": "— Ну, конечно.", "zh": "当然啦。", "t": [8162, 10338]}, {"ru": "И если ты будешь умницей, я нарисую тебе веревку, чтобы привязывать его днем.", "zh": "若你乖乖的，我还会为你画一根绳子，白天用来拴住它。", "t": [10338, 15688]}, {"ru": "И колышек.", "zh": "一根桩。", "t": [15688, 17562]}, {"ru": "Однако это мое предложение, казалось, раздосадовало маленького принца.", "zh": "然而，我的提议似乎让小王子感到不悦。", "t": [17562, 23012]}, {"ru": "— Привязывать?", "zh": "拴住它？", "t": [23012, 24712]}, {"ru": "Какая странная мысль!", "zh": "这想法真古怪！", "t": [24712, 27188]}, {"ru": "— Но если ты его не привяжешь, он может куда-нибудь забрести и потеряться…", "zh": "但若你不拴住它，它可能会随意游荡，迷失了方向。", "t": [27188, 32175]}, {"ru": "Тут мой дружок снова звонко рассмеялся: — Куда же, ты думаешь, он может уйти?", "zh": "他再次清脆地笑了：“你以为它会跑到哪里去呢？”", "t": [32175, 37588]}, {"ru": "— Неважно, куда…", "zh": "无关紧要，去向何方…", "t": [37588, 39788]}, {"ru": "Куда-нибудь.", "zh": "随便哪里。", "t": [39788, 41575]}, {"ru": "Тогда маленький принц сказал вполне серьезно: — Не беда, ведь у меня там так мало места…", "zh": "小王子认真地说：“没关系，我的地方毕竟很小……”", "t": [41575, 47150]}, {"ru": "Потом он немного грустно добавил: — Даже если идти все время прямо, там невозможно забрести далеко.", "zh": "即使一直朝前走，那里也不可能走得太远。", "t": [47150, 52237]}]}]}, {"id": "ch04", "title_ru": "Глава 4", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"ru": "Так я узнал вторую важную вещь.", "zh": "我得知了第二件重要的事。", "t": [100, 3075]}, {"ru": "Его родная планета была едва ли больше обычного дома!", "zh": "他的星球比寻常住宅大不了多少。", "t": [3075, 7162]}, {"ru": "Впрочем, это меня не очень-то удивило.", "zh": "这倒也不足为奇。", "t": [7162, 10525]}, {"ru": "Я хорошо знал, что за такими большими планетами, как Земля, Юпитер, Марс и Венера, есть сотни других.", "zh": "我深知，除了那些如地球、木星、火星和金星这样的大星球，还有成百上千的其他星球。", "t": [10525, 18262]}, {"ru": "Некоторые из них такие маленькие, что их трудно разглядеть в телескоп.", "zh": "这些星球小得连望远镜都难以辨认。", "t": [18262, 23450]}, {"ru": "Когда астроном открывает такую планетку,", "zh": "当天文学家发现这样的小行星，", "t": [23450, 25988]}]}, {"id": "ch04p01", "audio": true, "sents": [{"ru": "он дает ей вместо названия лишь номер.", "zh": "他只给她一个编号。", "t": [100, 3362]}, {"ru": "Он ее называет, к примеру, «астероид 3251».", "zh": "他称它为“小行星3251号”。", "t": [3362, 6050]}, {"ru": "У меня были серьезные основания думать, что планета, с которой прилетел маленький принц, была астероидом Б 612.", "zh": "我有充分的理由相信，小王子来自的星球是B612号小行星。", "t": [6050, 15075]}, {"ru": "Этот астероид впервые был замечен в телескоп в 1909 году каким-то турецким астрономом.", "zh": "这颗小行星首次被一位土耳其天文学家用望远镜观察到是在1909年。", "t": [15075, 23475]}, {"ru": "Он сделал об этом своем открытии большой доклад на Международном астрономическом конгрессе.", "zh": "他在国际天文会议上对这一发现做了详尽的报告。", "t": [23475, 29262]}, {"ru": "Но никто ему тогда не поверил, потому что он был странно одет.", "zh": "但那时无人相信他，因为他衣着古怪。", "t": [29262, 33738]}, {"ru": "Такие вот люди, эти взрослые.", "zh": "这类人，大人们。", "t": [33738, 36975]}]}, {"id": "ch04p02", "audio": true, "sents": [{"ru": "К счастью для астероида Б 612, турецкий правитель приказал своим подданным под страхом смерти одеваться по-европейски.", "zh": "幸而，土耳其统治者下令其臣民在欧洲式样服装下，否则将面临死刑。", "t": [100, 2512]}, {"ru": "Астроном повторил свой доклад в 1920 году.", "zh": "天文学家在1920年再次重复了他的报告。", "t": [2512, 6912]}, {"ru": "На этот раз он был одет весьма элегантно, и все с ним согласились.", "zh": "这次他衣着颇为优雅，所有人都表示赞同。", "t": [6912, 11925]}, {"ru": "А если я вам так подробно рассказал об этом астероиде и даже сообщил его номер — Б 612, так это из-за взрослых.", "zh": "我之所以如此详尽地讲述这颗小行星，甚至告诉你们它的编号——B612，全是因为那些大人的缘故。", "t": [11925, 19575]}, {"ru": "Взрослые любят цифры.", "zh": "大人们偏爱数字。", "t": [19575, 22188]}, {"ru": "Когда вы им рассказываете о своем новом друге, они никогда не спрашивают вас о самом главном.", "zh": "当你们向他们提起你们的新朋友时，他们从不询问你们最要紧的事。", "t": [22188, 28250]}, {"ru": "Они не спрашивают о его голосе или во что он играет.", "zh": "他们不问他的嗓音如何，也不问他的游戏。", "t": [28250, 32125]}, {"ru": "Они не интересуются, что ему нравится и собирает ли он бабочек.", "zh": "他们不关心他喜欢什么，是否收集蝴蝶。", "t": [32125, 36912]}, {"ru": "Они спрашивают — сколько ему лет?", "zh": "他们问：“他多大年纪了？”", "t": [36912, 40062]}, {"ru": "Сколько у него братьев?", "zh": "他有多少个兄弟？", "t": [40062, 42538]}, {"ru": "Сколько он весит?", "zh": "他体重多少？", "t": [42538, 44788]}, {"ru": "Сколько зарабатывает его отец?", "zh": "他父亲挣多少钱？", "t": [44788, 47625]}, {"ru": "Только тогда им кажется, что они его узнали.", "zh": "这才觉得他们认识了他。", "t": [47625, 51275]}]}, {"id": "ch04p03", "audio": true, "sents": [{"ru": "Если вы скажете взрослым, что видели красивый дом из красного кирпича с геранью на подоконниках и с голубями на крыше, они не смогут себе его представить.", "zh": "若你向大人提起，你见过一幢红砖砌成的美丽房屋，窗台上摆放着天竺葵，屋顶栖息着鸽子，他们便无法想象那是什么样的房子。", "t": [100, 3488]}, {"ru": "Им нужно сказать, что ты видел дом, который стоит сто тысяч франков.", "zh": "你须得告诉他们，你看见了一座价值十万法郎的房子。", "t": [3488, 8788]}, {"ru": "Тогда они воскликнут: «Какая красота!».", "zh": "他们便会惊叹：“多美的房子啊！”", "t": [8788, 12238]}, {"ru": "Поэтому, если вы им говорите, что маленький принц существует, потому что он удивительный, потому что он смеялся и хотел, чтобы ему нарисовали барашка (ведь желание иметь барашка доказывает, что ты существуешь), они лишь пожмут плечами и посмотрят на вас, как на ребенка.", "zh": "因此，如果你对他们说：“小王子确实存在，因为他与众不同，因为他曾笑过，因为他想要一只羊（因为想要一只羊的愿望证明你存在）”，他们只会耸耸肩，像看孩子一样看着你。", "t": [12238, 27712]}, {"ru": "Но если вы им скажете, что он прилетел с астероида Б 612, это их убедит, они от вас отстанут и не будут больше донимать своими вопросами.", "zh": "但若你们告诉他们，他来自B612号小行星，他们便会信服，不再打扰你们，也不再问东问西。", "t": [27712, 36788]}, {"ru": "Они такие.", "zh": "他们就是这样。", "t": [36788, 38862]}, {"ru": "И не стоит за это на них обижаться.", "zh": "不必为此对他们心生怨恨。", "t": [38862, 41888]}, {"ru": "Дети должны быть снисходительны ко взрослым.", "zh": "孩子们应当对大人宽容。", "t": [41888, 45375]}, {"ru": "Конечно, тех, кто понимает жизнь, не волнуют цифры.", "zh": "当然，懂得生活的人不会为数字所动。", "t": [45375, 49888]}, {"ru": "Я бы хотел начать эту историю, как волшебную сказку.", "zh": "我想把这个故事讲成一段魔幻的童话。", "t": [49888, 54300]}, {"ru": "Я бы сказал: «Жил-был однажды маленький принц.", "zh": "曾有一个小王子。", "t": [54300, 58062]}, {"ru": "И жил он на планете, которая была чуть больше его самого.", "zh": "他住在的星球比他自己大不了多少。", "t": [58062, 62425]}, {"ru": "Ему нужен был друг…»", "zh": "他需要一个朋友…", "t": [62425, 65050]}, {"ru": "Для тех, кто понимает жизнь, это было бы больше похоже на правду.", "zh": "对懂得生活的人来说，这更像真理。", "t": [65050, 69912]}, {"ru": "Мне совсем не хочется, чтобы мою книгу читали ради развлечения.", "zh": "我并不希望人们仅仅为了消遣而阅读我的书。", "t": [69912, 74925]}, {"ru": "Мне горько рассказывать о своих воспоминаниях.", "zh": "回忆往事，我心如刀割。", "t": [74925, 78525]}, {"ru": "Ведь прошло уже шесть лет, как мой друг покинул меня вместе со своим барашком.", "zh": "六年来，我的朋友带着他的羊离我远去。", "t": [78525, 83925]}, {"ru": "Я пытаюсь здесь его описать, просто чтобы не забыть о нем.", "zh": "我尽力在此描绘他，以免将他遗忘。", "t": [83925, 88112]}, {"ru": "Ведь это грустно — забыть о друге.", "zh": "遗忘朋友，实在令人悲伤。", "t": [88112, 91088]}, {"ru": "Не у всех в жизни был друг.", "zh": "并非每个人生命中都有朋友。", "t": [91088, 93800]}, {"ru": "Я ведь могу стать как взрослые, которых интересуют только цифры.", "zh": "我或许会变得和大人们一样，只对数字感兴趣。", "t": [93800, 98700]}, {"ru": "Для этого я и купил коробку с красками и карандаши.", "zh": "为此，我特意买了一盒颜料和几支铅笔。", "t": [98700, 102888]}, {"ru": "Трудно снова начинать рисовать в моем возрасте,", "zh": "在这个年纪重拾画笔实属不易。", "t": [102888, 105724]}]}, {"id": "ch04p04", "audio": true, "sents": [{"ru": "особенно если раньше, когда тебе было шесть, у тебя были всего две попытки — рисунки удава снаружи и изнутри!", "zh": "尤其若在六岁时，你仅有两次机会——画一条蟒蛇，一面是开膛的，一面是未开膛的！", "t": [100, 7400]}, {"ru": "Но я, конечно, постараюсь, чтобы вышло похоже.", "zh": "我定会尽力让它看起来相似。", "t": [7400, 11850]}, {"ru": "Хотя я совершенно не уверен, что у меня получится.", "zh": "尽管我不敢肯定能否成功。", "t": [11850, 16012]}, {"ru": "Один рисунок удается, а другой — выходит не очень…", "zh": "一幅画得还可以，另一幅却不太像。", "t": [16012, 20312]}, {"ru": "Я сомневаюсь также насчет роста.", "zh": "我怀疑他的身高。", "t": [20312, 23288]}, {"ru": "На одном маленький принц получается слишком большим, а на другом — слишком маленьким.", "zh": "那颗小王子的星球太大，而另一颗又太小。", "t": [23288, 29075]}, {"ru": "Я не уверен и в цвете его костюма.", "zh": "我不敢确定他衣服的颜色。", "t": [29075, 32325]}, {"ru": "Приходится действовать по наитию, наугад — и так и этак.", "zh": "凭直觉行事，随意而为。", "t": [32325, 36912]}, {"ru": "Наконец, я могу ошибаться и в некоторых важных деталях.", "zh": "或许，在某些重要细节上，我可能犯了错。", "t": [36912, 41350]}, {"ru": "Придется вам меня за это простить.", "zh": "您得原谅我这一回。", "t": [41350, 44250]}, {"ru": "Мой друг никогда мне ничего не объяснял.", "zh": "我的朋友从未向我解释过什么。", "t": [44250, 47500]}, {"ru": "Наверное, он думал, что я такой же, как и он сам.", "zh": "他大概以为我和他一样。", "t": [47500, 51862]}, {"ru": "Но я, к сожалению, не умею видеть барашков сквозь стенки ящичка.", "zh": "但我遗憾的是，我无法透过箱子壁看到羊。", "t": [51862, 57125]}, {"ru": "Возможно, я немного похож на взрослых.", "zh": "或许，我也有点像大人了。", "t": [57125, 60538]}, {"ru": "Наверное, я просто постарел.", "zh": "或许，我只是老了。", "t": [60538, 62575]}]}]}, {"id": "ch05", "title_ru": "Глава 5", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"ru": "Каждый день я узнавал кое-что новое о его планете и о начале его путешествия.", "zh": "每日，我都从他那里得知他星球上的新事，以及他旅行的起点。", "t": [100, 5650]}, {"ru": "Он рассказывал о ней понемногу, когда выдавался случай.", "zh": "他总是趁机会，零零星星地讲述着。", "t": [5650, 10000]}, {"ru": "Поэтому о трагедии с баобабами я узнал лишь на третий день.", "zh": "因此，关于猴面包树的悲剧，我是第三天才知道的。", "t": [10000, 14100]}, {"ru": "И это случилось именно благодаря барашку.", "zh": "这多亏了那只绵羊。", "t": [14100, 17500]}, {"ru": "Маленький принц после долгого раздумья вдруг спросил меня: — Правда ведь, что барашки едят кустарники?", "zh": "小王子经过一番沉思，突然问我：“真的，绵羊是吃灌木的吗？”", "t": [17500, 24012]}, {"ru": "— Да, правда.", "zh": "是的，是真的。", "t": [24012, 26025]}, {"ru": "— А… это хорошо…", "zh": "这倒不错…", "t": [26025, 28438]}, {"ru": "Я сразу не понял, почему для него было так важно, что овцы едят кусты.", "zh": "他立刻不明白，绵羊吃灌木对他来说为何如此重要。", "t": [28438, 33638]}, {"ru": "Однако маленький принц добавил: — Значит, и баобабы они тоже едят?", "zh": "小王子又补充道：“那么，它们也吃猴面包树吗？”", "t": [33638, 38712]}, {"ru": "Я заметил маленькому принцу, что баобабы — не кустарники, а деревья, высокие, как церкви, и если бы он даже прихватил на свою планету целое стадо слонов, оно не справилось бы и с одним-единственным баобабом.", "zh": "我向小王子指出，猴面包树并非灌木，而是高如教堂的巨树，即便他带上整群大象，也无法对付一棵猴面包树。", "t": [38712, 51912]}, {"ru": "Мысль о стаде слонов на его планете рассмешила маленького принца.", "zh": "一群大象在他星球上的景象逗笑了小王子。", "t": [51912, 56475]}, {"ru": "— Тогда нужно будет ставить одного слона на другого.", "zh": "那就得让一头大象站在另一头大象的背上。", "t": [56475, 60238]}, {"ru": "Однако он мудро заметил: — Но ведь баобабы, прежде чем вырасти, тоже бывают маленькими.", "zh": "然而他明智地指出：但猴面包树在长成之前，也曾是小小的。", "t": [60238, 66350]}, {"ru": "— Это точно!", "zh": "这没错！", "t": [66350, 68238]}, {"ru": "Но почему ты хочешь, чтобы твои барашки питались маленькими баобабами?", "zh": "你为何要让你的小绵羊吃那些小小的猴面包树苗呢？", "t": [68238, 72600]}]}, {"id": "ch05p01", "audio": true, "sents": [{"ru": "Он мне ответил, как будто речь шла о вещах очевидных: — Почему?", "zh": "这还用问吗？", "t": [100, 5125]}, {"ru": "Сам прикинь…", "zh": "这还用想吗…", "t": [5125, 7000]}, {"ru": "И мне потребовалось изрядно напрячь свои мозги, чтобы понять, в чем тут проблема.", "zh": "我颇费思量，才弄懂这其中的问题所在。", "t": [7000, 12800]}]}, {"id": "ch05p02", "audio": true, "sents": [{"ru": "В самом деле, наверняка на планете маленького принца, как и на прочих планетах, среди полезных растений росли и сорняки.", "zh": "确实，在小王子的星球上，如同其他星球一样，有益草也有杂草生长。", "t": [100, 2688]}, {"ru": "Следовательно, в земле были хорошие семена хороших растений и плохие семена плохих.", "zh": "因此，土壤中既有好植物的种子，也有坏植物的种子。", "t": [2688, 8525]}, {"ru": "Однако семена толком не разглядишь.", "zh": "然而种子细看不清。", "t": [8525, 11625]}, {"ru": "Они спят до поры, храня свой секрет в земле, пока кому-нибудь из них не взбредет в голову проснуться.", "zh": "它们沉睡于地底，保守着秘密，直至某颗种子突然萌生，想要醒来。", "t": [11625, 18050]}, {"ru": "Тогда семя дает росток.", "zh": "那颗种子便萌生发芽。", "t": [18050, 20775]}]}, {"id": "ch05p03", "audio": true, "sents": [{"ru": "Сначала он робко тянется к солнцу, такой восхитительный и безобидный.", "zh": "它怯生生地伸向太阳，既可爱又无害。", "t": [100, 2825]}, {"ru": "Это верно, если речь идет о ростке редиски или розы.", "zh": "这没错，若说的是萝卜或玫瑰的嫩芽。", "t": [2825, 6925]}, {"ru": "Тогда можно дать ему волю расти и дальше.", "zh": "任其自由生长。", "t": [6925, 10388]}, {"ru": "Однако, если речь о сорняке, его надо сразу же выполоть, как распознаешь.", "zh": "然而，一旦认出是杂草，就得立刻拔除。", "t": [10388, 15850]}, {"ru": "А на планете маленького принца такие ужасные семена как раз имелись.", "zh": "小王子的星球上，正有可怕的种子潜伏。", "t": [15850, 20625]}, {"ru": "Это были семена баобабов.", "zh": "这是猴面包树的种子。", "t": [20625, 23300]}, {"ru": "Вся почва планеты была ими заражена.", "zh": "整个星球的土壤都被它们侵染了。", "t": [23300, 26538]}, {"ru": "А если взяться даже за один баобаб слишком поздно, от него уже не избавишься.", "zh": "若及早不除，单是抓一个猴面包树也难根除。", "t": [26538, 31725]}, {"ru": "Он заполонит всю планету и прорастет в нее своими корнями.", "zh": "它将侵占整个星球，根须蔓延其中。", "t": [31725, 36288]}, {"ru": "И если планета очень маленькая, а баобабов слишком много, они ее просто разорвут на части.", "zh": "若星球过于狭小，而猴面包树又过多，它们便会将星球撕裂成碎片。", "t": [36288, 42900]}, {"ru": "Поэтому это важный пункт распорядка дня — говорил мне маленький принц позже.", "zh": "因此，这是日常安排中的一个重要环节——小王子后来对我说。", "t": [42900, 47938]}, {"ru": "Когда закончишь утром приводить себя в порядок, надо аккуратно привести в порядок свою планету.", "zh": "清晨整理好自己，别忘了精心打理你的星球。", "t": [47938, 54125]}]}, {"id": "ch05p04", "audio": true, "sents": [{"ru": "Надо приучить себя регулярно выдергивать молодые баобабы, как только сможешь их отличить от кустов роз, на которые они в молодости очень похожи.", "zh": "要养成习惯，一认出猴面包树苗就将其拔除，因为它们与玫瑰苗幼时极相似。", "t": [100, 8050]}, {"ru": "Эта работа довольно скучная, хотя и очень простая.", "zh": "这项工作虽单调，却简单易行。", "t": [8050, 12225]}, {"ru": "Однажды он мне посоветовал постараться нарисовать такую картинку, чтобы дети там, где я живу, хорошо это себе уяснили.", "zh": "他建议我尽力画一幅画，好让那里的孩子们牢记于心。", "t": [12225, 20238]}, {"ru": "«Если они когда-нибудь начнут путешествовать, — сказал он мне, — это может им помочь.", "zh": "若他们有朝一日踏上旅途，这或许能帮上他们。", "t": [20238, 25988]}, {"ru": "Иногда можно без проблем отложить свою работу.", "zh": "有时，可以毫不费力地推迟自己的工作。", "t": [25988, 29775]}, {"ru": "Но только не в случае с баобабами.", "zh": "但猴面包树除外。", "t": [29775, 32825]}, {"ru": "Иначе это кончится бедой.", "zh": "否则，这终将酿成大祸。", "t": [32825, 35588]}, {"ru": "Я знавал одну планету, на которой жил лентяй.", "zh": "我曾知晓一颗星球，上面住着一个懒汉。", "t": [35588, 39600]}, {"ru": "Он долго не обращал внимание на три кустика…»", "zh": "他久久地忽视了那三株幼苗……", "t": [39600, 43262]}, {"ru": "По просьбе маленького принца я нарисовал ту самую планету.", "zh": "应小王子的请求，我画下了那颗星球。", "t": [43262, 47462]}, {"ru": "Я не люблю никого поучать.", "zh": "我不喜欢教训他人。", "t": [47462, 50200]}, {"ru": "Однако угроза, исходящая от баобабов, столь мало известна, а опасность для тех, кто очутится на астероиде, столь серьезна, что в данном случае я, пожалуй, сделаю исключение.", "zh": "然而，猴面包树带来的威胁鲜为人知，而那些误入小行星的人所面临的危险又如此严重，在此情况下，我或许可以破例。", "t": [50200, 62075]}, {"ru": "Я говорю: «Дети!", "zh": "孩子们！", "t": [62075, 64425]}, {"ru": "Следите за баобабами!»", "zh": "孩子们，当心猴面包树！", "t": [64425, 67075]}, {"ru": "Так я хочу предупредить моих юных друзей об опасности, с которой они сталкиваются уже довольно давно.", "zh": "我要提醒我的年轻朋友们，他们早已面临的这种危险。", "t": [67075, 73388]}, {"ru": "Я и сам о ней не подозревал, пока не закончил этот рисунок.", "zh": "直到完成这幅画，我才意识到自己竟未曾察觉。", "t": [73388, 77862]}, {"ru": "Над ним стоило потрудиться как следует.", "zh": "值得下番苦功夫。", "t": [77862, 81150]}, {"ru": "Возможно, вы меня спросите — почему в этой книжке нет других таких же внушительных рисунков, как эта картинка с баобабами?", "zh": "你们或许会问，为何这本书里没有其他如此引人注目的插图，就像这张猴面包树的画一样？", "t": [81150, 89125]}, {"ru": "Ответ совсем прост.", "zh": "答案很简单。", "t": [89125, 91575]}, {"ru": "Я старался, но у меня ничего не получилось.", "zh": "我尽力了，但毫无成效。", "t": [91575, 95100]}, {"ru": "А когда я рисовал баобабы, меня вдохновляла сама необходимость и неотложность этой работы.", "zh": "画猴面包树时，我被这项工作的紧迫性和必要性所激励。", "t": [95100, 100376]}]}]}, {"id": "ch06", "title_ru": "Глава 6", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"ru": "Ах, маленький принц!", "zh": "啊，小王子！", "t": [100, 2712]}, {"ru": "Мало-помалу я понял, почему ты так печален.", "zh": "我渐渐明白，你为何如此忧伤。", "t": [2712, 6338]}, {"ru": "Долгое время ты развлекал себя только красотой нежных вечерних закатов.", "zh": "长久以来，你只以那温柔的晚霞之美自娱。", "t": [6338, 11225]}, {"ru": "Я узнал об", "zh": "我得知了", "t": [11225, 12276]}]}, {"id": "ch06p01", "audio": true, "sents": [{"ru": "этой новой подробности твоей жизни утром четвертого дня, когда ты мне сказал: — Я очень люблю закаты.", "zh": "第四天早晨，你告诉我：我非常喜爱落日。", "t": [100, 6538]}, {"ru": "Пойдем, посмотрим на закат…", "zh": "我们去看看落日吧…", "t": [6538, 8550]}, {"ru": "— Надо будет подождать…", "zh": "我们得等一等…", "t": [8550, 10050]}, {"ru": "— Подождать чего?", "zh": "等什么呀？", "t": [10050, 11862]}, {"ru": "— Подождать, пока солнце не начнет садиться.", "zh": "耐心等待，直到太阳开始下山。", "t": [11862, 15525]}, {"ru": "При этом ты сначала очень удивился, а потом рассмеялся сам над собой.", "zh": "你先是惊讶，接着对自己笑了。", "t": [15525, 20600]}, {"ru": "— Мне все время кажется, что я у себя дома.", "zh": "我总觉得我是在自己家里。", "t": [20600, 24238]}]}, {"id": "ch06p02", "audio": true, "sents": [{"ru": "В самом деле — когда в Америке полдень, все в мире знают, что во Франции солнце уже садится.", "zh": "当美国正值正午，全世界都知道，在法国，太阳已西下。", "t": [100, 5025]}, {"ru": "Если бы удалось за минуту попасть во Францию, можно было бы присутствовать при этом закате.", "zh": "若能瞬间抵达法国，便能目睹这日落美景。", "t": [5025, 10788]}, {"ru": "К несчастью, Франция слишком далеко.", "zh": "遗憾的是，法国太远了。", "t": [10788, 14175]}, {"ru": "Однако на твоей планетке тебе достаточно лишь передвинуть стул на несколько шагов.", "zh": "然而，在你的星球上，你只需将椅子挪动几步即可。", "t": [14175, 19400]}, {"ru": "И ты можешь наблюдать за сумерками сколько душа пожелает.", "zh": "你愿看多久，就能看多久。", "t": [19400, 23438]}, {"ru": "— Однажды я наблюдал закат сорок три раза!", "zh": "有一天，我目睹了四十三次日落。", "t": [23438, 26862]}, {"ru": "И немного погодя ты добавил: — Знаешь, когда грустно, хорошо смотреть на закаты…", "zh": "你知道，心绪沉重时，观赏落日也是一种慰藉…", "t": [26862, 31850]}, {"ru": "— Значит, когда ты смотрел на закат сорок три раза, тебе было очень грустно?", "zh": "那时，你目睹四十三次日落，心中满是忧伤。", "t": [31850, 36900]}, {"ru": "Но на это маленький принц ничего не ответил.", "zh": "小王子并未作答。", "t": [36900, 39463]}]}]}, {"id": "ch07", "title_ru": "Глава 7", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"ru": "Этот секрет жизни маленького принца мне открылся на пятый день, и опять благодаря барашку.", "zh": "第五天，小王子的生活秘密才得以揭晓，而这又多亏了那只绵羊。", "t": [100, 6000]}, {"ru": "Он меня внезапно спросил без всякого предисловия, словно давно размышлял над этой проблемой: — Ведь если барашек ест кустарники, значит и цветы тоже?", "zh": "他突然问我，仿佛早已深思熟虑这个问题：既然绵羊吃灌木，那它也会吃花吗？", "t": [6000, 15188]}, {"ru": "— Барашек ест все, что ему попадается.", "zh": "绵羊见什么吃什么。", "t": [15188, 18938]}, {"ru": "— Даже цветы с шипами?", "zh": "连带刺的花也吃吗？", "t": [18938, 21438]}, {"ru": "— Да, даже цветы с шипами.", "zh": "连带刺的花也吃。", "t": [21438, 24262]}, {"ru": "— А колючки?", "zh": "刺呢？", "t": [24262, 26088]}, {"ru": "Зачем они тогда нужны?", "zh": "那它们为何存在呢？", "t": [26088, 28588]}, {"ru": "Я этого не знал.", "zh": "我不知其所以然。", "t": [28588, 30750]}, {"ru": "К тому же я тогда был очень занят, пытаясь открутить тугой болт в моем моторе.", "zh": "那时我正忙于拧下发动机上那颗拧得太紧的螺栓。", "t": [30750, 36062]}, {"ru": "Я был очень озабочен, потому что поломка стала казаться мне очень серьезной.", "zh": "我忧心忡忡，因为故障似乎变得异常严重。", "t": [36062, 41175]}, {"ru": "Питьевая вода у меня заканчивалась, и это заставляло думать о худшем.", "zh": "饮水即将告罄，这让我担忧不已。", "t": [41175, 46062]}, {"ru": "— Колючки.", "zh": "刺儿", "t": [46062, 47812]}, {"ru": "Зачем они нужны?", "zh": "它们有何用？", "t": [47812, 50000]}, {"ru": "Стоило маленькому принцу задать вопрос, и он уже не отступал.", "zh": "小王子一问，便决不退缩。", "t": [50000, 54462]}, {"ru": "Тугой болт выводил меня из себя, и я ответил наобум: — Колючки?", "zh": "那刺儿？", "t": [54462, 59262]}, {"ru": "Ни для чего они не нужны.", "zh": "它们并无必要。", "t": [59262, 61875]}, {"ru": "Чистая вредность со стороны цветов.", "zh": "花的纯粹恶作剧。", "t": [61875, 65012]}, {"ru": "— Ох!", "zh": "哦！", "t": [65012, 66362]}, {"ru": "Однако после минутного молчания он буркнул мне в ответ: — Я тебе не верю!", "zh": "然而，沉默片刻后，他对我粗声粗气地说：“我不信你！”", "t": [66362, 71662]}, {"ru": "Цветы слабые.", "zh": "花儿柔弱。", "t": [71662, 73862]}, {"ru": "Они простодушные.", "zh": "他们纯真无邪。", "t": [73862, 76138]}, {"ru": "Они защищают себя, как могут.", "zh": "它们尽力保护自己。", "t": [76138, 79325]}, {"ru": "Им кажется, что они грозные со своими колючками…", "zh": "它们似乎因自己的刺儿而显得威严。", "t": [79325, 82487]}]}, {"id": "ch07p01", "audio": true, "sents": [{"ru": "Я ничего не ответил.", "zh": "我无言以对。", "t": [100, 2450]}, {"ru": "В ту минуту я говорил себе: «Если этот болт не поддастся, я выбью его ударом молотка».", "zh": "那时我心想：若这螺栓拧不下来，我便用锤子砸它。", "t": [2450, 8375]}, {"ru": "Но маленький принц снова отвлек меня вопросом: — И ты считаешь…", "zh": "小王子又用一个问题将我引开了：——你以为…", "t": [8375, 12888]}, {"ru": "Ты думаешь, что цветы…", "zh": "你以为，花儿…", "t": [12888, 14775]}, {"ru": "— Да нет же!", "zh": "哦，不！", "t": [14775, 16288]}, {"ru": "Нет!", "zh": "不！", "t": [16288, 17800]}, {"ru": "Ничего я не считаю.", "zh": "我什么都不认为。", "t": [17800, 20188]}, {"ru": "Неважно, что я сказал.", "zh": "那我说什么，都无关紧要。", "t": [20188, 22775]}, {"ru": "Я занят серьезными вещами!", "zh": "我正忙于正经事。", "t": [22775, 25712]}, {"ru": "Он взглянул на меня с удивлением.", "zh": "他惊讶地望着我。", "t": [25712, 28750]}, {"ru": "— Серьезными вещами?", "zh": "这可是正经事？", "t": [28750, 31262]}, {"ru": "Он смотрел на меня, а я стоял с молотком в руке и с пальцами, черными от смазки.", "zh": "他凝视着我，而我手持锤子，指节因油污而显得乌黑。", "t": [31262, 37075]}, {"ru": "Я склонялся над предметом, который казался ему уродливым.", "zh": "我俯身于他视为丑陋的物件。", "t": [37075, 41662]}, {"ru": "— Ты говоришь, как взрослые!", "zh": "你说话就像大人！", "t": [41662, 44700]}, {"ru": "Это меня смутило, а он добавил без всякой жалости: — Ты все путаешь…", "zh": "这让我感到困惑，而他毫不怜悯地补充道：“你全搞错了……”", "t": [44700, 49575]}, {"ru": "Ты ничего не понимаешь!", "zh": "你根本不懂！", "t": [49575, 51862]}, {"ru": "Он действительно был рассержен.", "zh": "他真的生气了。", "t": [51862, 54588]}]}, {"id": "ch07p02", "audio": true, "sents": [{"ru": "Он тряхнул на ветру своими золотистыми волосами: — Мне знакома одна планета, на которой живет господин с багровой физиономией.", "zh": "他金发在风中狂舞：——我认识一个星球，上面住着一位红脸先生。", "t": [100, 3462]}, {"ru": "Он никогда не нюхал цветы.", "zh": "他从未闻过花香。", "t": [3462, 6138]}, {"ru": "Он ни разу не взглянул на звезду.", "zh": "他从未仰望过星星。", "t": [6138, 8950]}, {"ru": "Он никогда никого не любил.", "zh": "他从未爱过任何人。", "t": [8950, 11600]}, {"ru": "Он лишь занимается подсчетами.", "zh": "他只从事计算。", "t": [11600, 14612]}, {"ru": "И целый день кряду он, как и ты, повторяет: «Я человек серьезный!", "zh": "他整天就像你一样，反复地唠叨：“我是个正经人！”", "t": [14612, 19975]}, {"ru": "Я человек серьезный!»", "zh": "我是个认真的人！", "t": [19975, 22600]}, {"ru": "И он раздувается от гордости.", "zh": "他骄傲得膨胀起来。", "t": [22600, 25562]}, {"ru": "Но это не человек, а какой-то гриб!", "zh": "但这不是人，而是一棵蘑菇！", "t": [25562, 28712]}, {"ru": "— Кто?", "zh": "是谁？", "t": [28712, 30088]}, {"ru": "— Гриб!", "zh": "是蘑菇！", "t": [30088, 31600]}, {"ru": "В эту минуту маленький принц был бледен от гнева.", "zh": "小王子气得脸色苍白。", "t": [31600, 35350]}, {"ru": "— Вот уже миллионы лет, как цветы отращивают шипы.", "zh": "数百万年来，花儿便长着刺儿。", "t": [35350, 39775]}, {"ru": "Несмотря на это вот уже миллионы лет, как овцы их едят.", "zh": "尽管如此，已有数百万年，羊群在吞噬它们。", "t": [39775, 44312]}, {"ru": "И это не серьезно — пытаться понять, почему они так стараются отращивать шипы, которые ни для чего не нужны?", "zh": "这岂不是荒谬——试图弄懂，它们为何如此努力地长出毫无用处的刺儿？", "t": [44312, 51162]}, {"ru": "И это не важно — постоянная война между овцами и цветами?", "zh": "这又何妨——羊群与花朵间的永恒之战？", "t": [51162, 55850]}, {"ru": "Это не так важно и серьезно, как подсчеты багрового господина?", "zh": "这比不上那位红脸先生的计算来得重要和严肃。", "t": [55850, 60675]}, {"ru": "И если я знаю, что единственный цветок в мире, который существует только на моей планете, в одно прекрасное утро может вот так запросто уничтожить барашек, который даже не понимает, что делает, — разве это не важно?", "zh": "若我知晓，在这世上，唯有我星球上的一朵花，却在某个清晨，被一头甚至不知自己行为的绵羊轻易摧毁——这难道不是至关重要吗？", "t": [60675, 72938]}, {"ru": "Он покраснел, а потом продолжил: — Если ты любишь цветок, существующий среди миллионов и миллионов звезд, этого достаточно, чтобы быть счастливым, когда смотришь на звезды.", "zh": "若你爱上一朵花，它在亿万星辰中，仅此一眼，便足以令你心满意足。", "t": [72938, 83462]}, {"ru": "Ты знаешь — мой цветок где-то там…", "zh": "你知道——我的花儿在那儿……", "t": [83462, 86600]}, {"ru": "Но если барашек съест этот цветок, покажется, что погасли все звезды!", "zh": "但若这朵花被羊吃掉，似乎所有的星星都熄灭了。", "t": [86600, 91912]}, {"ru": "И это не важно?!", "zh": "这又何妨？", "t": [91912, 94038]}, {"ru": "Он не смог больше ничего сказать и неожиданно разразился рыданиями.", "zh": "他无法再说下去，突然放声大哭。", "t": [94038, 97937]}]}, {"id": "ch07p03", "audio": true, "sents": [{"ru": "Настала ночь.", "zh": "夜幕降临。", "t": [100, 2050]}, {"ru": "Я отложил в сторону свои инструменты.", "zh": "我搁置了工具。", "t": [2050, 5475]}, {"ru": "Мне стали безразличны мой молоток, болт, жажда и даже сама смерть.", "zh": "我的锤子、螺栓、干渴乃至死亡，都已变得无关紧要。", "t": [5475, 10975]}, {"ru": "На звезде, на планете, на моей Земле плакал маленький принц, и его надо было утешить.", "zh": "小王子在我的星球——地球上哭泣，需要安慰。", "t": [10975, 17075]}, {"ru": "Я взял его на руки, баюкал и говорил: «Цветок, который ты так любишь, в безопасности.", "zh": "我把他抱在怀里，轻声哄着，说：“你那朵深爱的花，安然无恙。”", "t": [17075, 23438]}, {"ru": "Я нарисую твоему барашку намордник.", "zh": "我给小王子的绵羊画一个口罩。", "t": [23438, 26712]}, {"ru": "Я нарисую доспехи для твоего цветка…»", "zh": "我给你的花儿画一副铠甲……", "t": [26712, 29938]}, {"ru": "Я не знал точно, что надо говорить.", "zh": "我不知该说些什么才好。", "t": [29938, 33188]}, {"ru": "Я чувствовал себя таким глупым и неуклюжим.", "zh": "我感到自己如此笨拙而尴尬。", "t": [33188, 36825]}, {"ru": "Я не знал, как достучаться, как проникнуть в его душу…", "zh": "我不知如何触及，如何深入他的心灵…", "t": [36825, 41262]}, {"ru": "Ведь она такая непознанная и таинственная — эта страна слез…", "zh": "那片土地，泪水的国度，如此神秘莫测。", "t": [41262, 45213]}]}]}, {"id": "ch08", "title_ru": "Глава 8", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"ru": "Вскоре я узнал об этом цветке больше.", "zh": "不久，我对这朵花有了更多的了解。", "t": [100, 3288]}, {"ru": "На планете маленького принца было много простых цветов с обычным венчиком лепестков.", "zh": "小王子的星球上开满了朴素的花朵，花瓣排列平凡。", "t": [3288, 8938]}, {"ru": "Они не занимали много места и никому не мешали.", "zh": "它们不占太多地方，也不打扰任何人。", "t": [8938, 12712]}, {"ru": "По утрам они распускались среди травы, а к вечеру увядали.", "zh": "清晨绽放于草间，傍晚凋零。", "t": [12712, 17250]}, {"ru": "А тот цветок возник из семечка, занесенного невесть откуда, и маленький принц внимательно разглядывал необычный росток, который отличался от всех прочих.", "zh": "那朵花是从不知名的地方飘来的种子萌发而成，小王子仔细端详着这与众不同的嫩芽。", "t": [17250, 26975]}, {"ru": "Ведь он мог оказаться ростком новой разновидности баобаба.", "zh": "或许它是新种猴面包树的嫩芽。", "t": [26975, 31088]}, {"ru": "Но кустик вскоре перестал расти и был готов к цветению.", "zh": "嫩枝很快便停止了生长，准备绽放。", "t": [31088, 35450]}, {"ru": "Маленький принц видел, как зарождался огромный бутон, и предугадывал появление чуда, но цветок под зеленой защитой листьев медлил раскрыть свою красоту.", "zh": "小王子目睹硕大的花蕾孕育而生，预感着奇花的绽放，然而绿叶庇护下的花朵却缓缓展露芳华。", "t": [35450, 44850]}, {"ru": "Казалось, он все еще тщательно подбирает свои будущие оттенки.", "zh": "她仍在精心挑选未来的色彩。", "t": [44850, 49712]}, {"ru": "Он медленно прихорашивался, расправляя один лепесток за другим.", "zh": "她缓缓地整理，一片片地舒展花瓣。", "t": [49712, 54388]}, {"ru": "Он не желал появиться растрепанным, словно какой-нибудь мак.", "zh": "他不希望像虞美人那样蓬头垢面地出现。", "t": [54388, 58838]}, {"ru": "Он хотел возникнуть в полном великолепии своей красоты.", "zh": "他希望以自己美丽的全部光辉登场。", "t": [58838, 63062]}, {"ru": "И да!", "zh": "是的！", "t": [63062, 64500]}, {"ru": "Цветок был очень кокетлив.", "zh": "她极尽妩媚。", "t": [64500, 67262]}, {"ru": "Ведь его таинственные приготовления длились изо дня в день.", "zh": "她的神秘准备日复一日地持续着。", "t": [67262, 71425]}, {"ru": "Но однажды утром, как раз на восходе солнца, эта красавица появилась.", "zh": "就在一个清晨，太阳升起的那一刻，这位美人儿露面了。", "t": [71425, 76725]}, {"ru": "Хотя она трудилась над своим появлением долго и прилежно, зевнув, она сказала: — Ах!", "zh": "尽管她精心准备了好久，打着哈欠说：“唉！”", "t": [76725, 82812]}, {"ru": "Я еще не совсем проснулась…", "zh": "我尚未完全醒来…", "t": [82812, 85550]}, {"ru": "Прошу меня извинить…", "zh": "请您见谅……", "t": [85550, 87975]}, {"ru": "Я такая растрепанная…", "zh": "我如此凌乱……", "t": [87975, 89662]}]}, {"id": "ch08p01", "audio": true, "sents": [{"ru": "Однако маленький принц не смог сдержать своего восхищения и воскликнул: — Как вы прекрасны!", "zh": "小王子禁不住赞叹道：“您真美啊！”", "t": [100, 6112]}, {"ru": "— В самом деле?", "zh": "真的吗？", "t": [6112, 8075]}, {"ru": "— тихо проговорила она.", "zh": "她轻声细语。", "t": [8075, 10512]}, {"ru": "— Я ведь родилась вместе с солнцем…", "zh": "我与太阳同日而生…", "t": [10512, 13675]}, {"ru": "Маленький принц понял, что цветок слегка нескромен, но он был таким трогательным!", "zh": "小王子察觉到这朵花略显轻佻，却十分惹人怜爱。", "t": [13675, 19150]}, {"ru": "— Мне кажется, в это время пора завтракать, — тут же добавила красавица.", "zh": "这会儿，她优雅地补充道：“早餐时间到了。”", "t": [19150, 24250]}, {"ru": "— Вы же позаботитесь обо мне?", "zh": "您就放心吧。", "t": [24250, 25912]}]}, {"id": "ch08p02", "audio": true, "sents": [{"ru": "И маленький принц, взволнованный и смущенный, поискал лейку с водой и услужил цветку.", "zh": "小王子既激动又尴尬，找来水壶为花儿浇水。", "t": [100, 6412]}, {"ru": "А красавица вскоре стала испытывать терпение маленького принца своими страхами и капризами.", "zh": "她很快便让小王子因她的恐惧和任性而感到耐心尽失。", "t": [6412, 12250]}, {"ru": "Однажды, например, говоря о своих четырех шипах, она сказала ему: — Ведь сюда могут заявиться тигры со своими ужасными когтями!", "zh": "有一天，她提及自己那四根刺，说道：“谁知道呢，或许会突然出现带着可怕爪子的老虎！”", "t": [12250, 19738]}]}, {"id": "ch08p03", "audio": true, "sents": [{"ru": "— На моей планете нет тигров, — возразил маленький принц.", "zh": "小王子反驳道：“在我的星球上没有老虎。”", "t": [100, 4525]}, {"ru": "— И потом, тигры не едят траву.", "zh": "老虎不吃草。", "t": [4525, 7525]}, {"ru": "— Я не трава, — тихо ответила она.", "zh": "我不是草。", "t": [7525, 10675]}, {"ru": "— Извините меня…", "zh": "请原谅……", "t": [10675, 12038]}, {"ru": "— Меня вовсе не страшат тигры, но я ужасно боюсь сквозняков.", "zh": "我并不惧怕老虎，却极怕穿堂风。", "t": [12038, 16350]}, {"ru": "У вас найдется ширма?", "zh": "您有屏风吗？", "t": [16350, 18800]}, {"ru": "«Подумать только!", "zh": "真是难以置信！", "t": [18800, 20850]}, {"ru": "Боязнь сквозняков!", "zh": "惧怕穿堂风！", "t": [20850, 23275]}, {"ru": "Да, с этим цветком будет непросто», — решил про себя маленький принц.", "zh": "是的，这朵花会有些棘手，小王子暗自思忖。", "t": [23275, 27400]}]}, {"id": "ch08p04", "audio": true, "sents": [{"ru": "— По вечерам вы должны накрывать меня стеклянным колпаком.", "zh": "夜晚，你应当用玻璃罩子罩住我。", "t": [100, 4025]}, {"ru": "У вас тут так холодно и неуютно.", "zh": "这里如此寒冷又令人不适。", "t": [4025, 7200]}, {"ru": "Там, откуда я родом…", "zh": "那里，我故乡的…", "t": [7200, 8688]}]}, {"id": "ch08p05", "audio": true, "sents": [{"ru": "Но тут она замолкла.", "zh": "她突然缄默了。", "t": [100, 2550]}, {"ru": "Она ведь попала на планету в виде семечка и поэтому не знала ничего о других мирах.", "zh": "她原本只是一颗种子，对其他世界一无所知。", "t": [2550, 8088]}, {"ru": "Попав врасплох из-за попытки невинно соврать, она немного покашляла, чтобы заставить маленького принца почувствовать себя виноватым.", "zh": "她无意中撒了个谎，便轻咳了几声，想让小王子感到愧疚。", "t": [8088, 16225]}, {"ru": "— Так где же ширма?", "zh": "屏风在哪里？", "t": [16225, 18438]}, {"ru": "— Я хотел пойти за ней, но вы со мной говорили!", "zh": "我本想跟随她，可你一直和我说话！", "t": [18438, 22038]}, {"ru": "Тогда она закашлялась громче, чтобы маленькому принцу стало совестно.", "zh": "她更用力地咳嗽，让小王子感到羞愧。", "t": [22038, 26213]}]}, {"id": "ch08p06", "audio": true, "sents": [{"ru": "Несмотря на искреннюю любовь маленького принца к цветку, в его душе появились некоторые сомнения.", "zh": "尽管小王子对这朵花怀有真挚的爱，心中却生出了几分疑虑。", "t": [100, 6662]}, {"ru": "Он страдал, принимая пустые слова цветка всерьез.", "zh": "他认真对待了花朵的空话而感到痛苦。", "t": [6662, 10738]}, {"ru": "«Я не должен был слушать ее, — признался он мне позже.", "zh": "他后来向我承认，他不该听信她的话。", "t": [10738, 14975]}, {"ru": "— Не нужно слушать, что говорят цветы.", "zh": "无需听信花朵的话语。", "t": [14975, 18412]}, {"ru": "Ими нужно любоваться, вдыхать их аромат.", "zh": "需细细观赏，深深呼吸它们的芬芳。", "t": [18412, 21912]}, {"ru": "Моя красавица наполняла благоуханием всю планету, но я не умел этому радоваться.", "zh": "我的玫瑰让整个星球弥漫着芬芳，而我却未曾懂得珍惜这份美好。", "t": [21912, 27662]}, {"ru": "Эта история с тигриными когтями, которая меня так вывела из себя, должна была меня насторожить…»", "zh": "这关于老虎爪子的故事，本应让我心生警惕……", "t": [27662, 34050]}, {"ru": "И он признался еще кое в чем: «Я тогда ничего не понимал!", "zh": "那时我实在不懂！", "t": [34050, 38238]}, {"ru": "Я должен был судить по ее делам, а не по словам.", "zh": "应凭她的行为而非言语来判断。", "t": [38238, 42138]}, {"ru": "Она дарила мне свой аромат и озаряла мою жизнь.", "zh": "她赠我芬芳，照亮了我的生命。", "t": [42138, 45988]}, {"ru": "Я не должен был убегать!", "zh": "我不该逃跑！", "t": [45988, 48588]}, {"ru": "Мне надо было разглядеть за ее уловками нежность и хрупкость.", "zh": "我需洞察她狡黠背后的温柔与脆弱。", "t": [48588, 52900]}, {"ru": "Цветы так противоречивы!", "zh": "花朵如此矛盾。", "t": [52900, 55538]}, {"ru": "Но я был слишком неопытен, чтобы уметь ее любить».", "zh": "那时我实在不懂如何去爱她。", "t": [55538, 58812]}]}]}, {"id": "ch09", "title_ru": "Глава 9", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"ru": "Думаю, он воспользовался для своего побега перелетными птицами.", "zh": "他或许是在候鸟迁徙之际悄然离去的。", "t": [100, 4925]}, {"ru": "В последнее утро перед отлетом он тщательно привел свою планету в порядок.", "zh": "在离去的最后一天清晨，他仔细地整顿了他的星球。", "t": [4925, 9938]}, {"ru": "Он прочистил жерла действующих вулканов.", "zh": "他清理了活火山的火山口。", "t": [9938, 13475]}, {"ru": "У него на планете было два таких вулкана.", "zh": "他的星球上有两座活火山。", "t": [13475, 16812]}, {"ru": "С их помощью было так удобно по утрам разогревать завтраки.", "zh": "清晨用它们加热早餐颇为方便。", "t": [16812, 20988]}, {"ru": "Один вулкан на планете был потухшим, но маленький принц частенько говорил себе: «Никогда не знаешь, что может пригодиться».", "zh": "星球上有一座火山已熄灭，但小王子常常自言自语：“永远不知道什么会派上用场。”", "t": [20988, 28862]}, {"ru": "Поэтому он прочистил также и потухший вулкан.", "zh": "因此，他也清理了那座熄灭的火山。", "t": [28862, 32575]}, {"ru": "Ведь если вулканы хорошо прочищены, они работают тихо и равномерно, без извержений.", "zh": "火山若清理得当，便能安静均匀地运作，不会喷发。", "t": [32575, 38812]}, {"ru": "Вулканические извержения — они как искры из печной трубы.", "zh": "火山喷发，犹如炉管中飞溅的火星。", "t": [38812, 43875]}, {"ru": "К сожалению, на нашей Земле мы слишком малы, чтобы прочищать свои вулканы.", "zh": "遗憾的是，在我们地球上，我们太小了，无法清理自己的火山。", "t": [43875, 49412]}, {"ru": "Вот почему от них бывает так много неприятностей.", "zh": "因此，它们常常带来不少麻烦。", "t": [49412, 53425]}, {"ru": "Маленький принц с некоторым сожалением выполол также последние ростки баобабов.", "zh": "小王子带着几分遗憾，也拔除了最后几株猴面包树苗。", "t": [53425, 58750]}, {"ru": "Ведь он думал, что больше сюда не вернется.", "zh": "他心想，他不会再回到这里了。", "t": [58750, 62312]}, {"ru": "Тем утром эта привычная работа казалась ему необычайно приятной.", "zh": "那天早晨，这项日常劳作在他看来分外愉悦。", "t": [62312, 66800]}, {"ru": "И когда он полил в последний раз свой цветок и готов был уже поместить его под стеклянный колпак, он готов был расплакаться.", "zh": "最后一次给花儿浇水，准备给她盖上罩子，他几乎要哭出来了。", "t": [66800, 74438]}, {"ru": "— Прощай, — сказал он цветку.", "zh": "再见，他对花儿说。", "t": [74438, 77288]}, {"ru": "Но цветок ему ничего не ответил.", "zh": "花儿默默无言。", "t": [77288, 80212]}, {"ru": "— Прощай, — повторил он.", "zh": "再见，他又说。", "t": [80212, 82688]}, {"ru": "Красавица покашляла.", "zh": "她轻轻咳嗽。", "t": [82688, 85138]}, {"ru": "Хотя, конечно, дело было не в простуде.", "zh": "固然，并非因感冒。", "t": [85138, 87812]}]}, {"id": "ch09p01", "audio": true, "sents": [{"ru": "— Я была глупой, — сказала она наконец.", "zh": "她终于说：“我以前真傻。”", "t": [100, 3550]}, {"ru": "— Прости меня и постарайся быть счастливым.", "zh": "请原谅我，愿你幸福。", "t": [3550, 6900]}, {"ru": "Маленький принц был удивлен, не услыхав никаких укоров.", "zh": "小王子惊讶于她没有一句责备。", "t": [6900, 11362]}, {"ru": "Он был растерян и замер, все еще держа стеклянный колпак в руке.", "zh": "他愣在原地，手还紧紧握着那顶玻璃罩。", "t": [11362, 15875]}, {"ru": "Он не ожидал такой нежности.", "zh": "他未曾料到如此柔情。", "t": [15875, 17788]}]}, {"id": "ch09p02", "audio": true, "sents": [{"ru": "— Ну, конечно, я люблю тебя, — сказал ему цветок.", "zh": "当然，我爱你。", "t": [100, 4275]}, {"ru": "— Ты об этом не знал, и это моя ошибка.", "zh": "你并未察觉，这是我的过错。", "t": [4275, 7500]}, {"ru": "Но теперь это не важно.", "zh": "但这已无关紧要。", "t": [7500, 9812]}, {"ru": "Ты был таким же глупым, как и я.", "zh": "你也和我一样傻。", "t": [9812, 12662]}, {"ru": "Будь счастлив.", "zh": "愿你幸福。", "t": [12662, 14700]}, {"ru": "Оставь этот колпак в покое.", "zh": "别把这罩子放在心上。", "t": [14700, 17638]}, {"ru": "Он мне больше не нужен.", "zh": "他不再需要我了。", "t": [17638, 20012]}, {"ru": "— А сквозняки?", "zh": "可是风……", "t": [20012, 21925]}, {"ru": "— Не так уж я и простужена.", "zh": "我并未真的感冒。", "t": [21925, 24650]}, {"ru": "Ночной свежий воздух мне на пользу.", "zh": "夜晚的清新空气对我大有裨益。", "t": [24650, 27812]}, {"ru": "Я же цветок.", "zh": "我是一朵花。", "t": [27812, 29950]}, {"ru": "— А хищные звери?", "zh": "凶猛的野兽呢？", "t": [29950, 32088]}, {"ru": "— Было бы неплохо выдержать на себе двух или трех гусениц, если я хочу познакомиться с бабочками.", "zh": "若想结识蝴蝶，就得承受两三条毛虫的纠缠。", "t": [32088, 38438]}]}, {"id": "ch09p03", "audio": true, "sents": [{"ru": "Говорят, они прекрасны.", "zh": "它们说，它们很美。", "t": [100, 2750]}, {"ru": "Иначе кто будет меня навещать?", "zh": "否则，谁会来探望我呢？", "t": [2750, 5675]}, {"ru": "Ты ведь будешь далеко отсюда.", "zh": "你将远离此地。", "t": [5675, 8300]}, {"ru": "Что до хищных зверей, то я ничего не боюсь.", "zh": "至于凶猛的野兽，我毫不畏惧。", "t": [8300, 11750]}, {"ru": "У меня ведь есть свои когти.", "zh": "我自有我的利爪。", "t": [11750, 14538]}, {"ru": "При этом она наивно показала свои четыре шипа.", "zh": "她天真地露出了她的四根刺。", "t": [14538, 18188]}, {"ru": "Потом она добавила: — Ну, не тяни!", "zh": "别拖拖拉拉的！", "t": [18188, 21338]}, {"ru": "Это же невыносимо!", "zh": "这简直无法忍受！", "t": [21338, 23575]}, {"ru": "Раз ты решил уйти, так уходи!", "zh": "既然你已决定离去，那就走吧！", "t": [23575, 26512]}, {"ru": "Она не хотела, чтобы он увидел ее заплаканной.", "zh": "她不愿让他看到自己泪流满面。", "t": [26512, 30212]}, {"ru": "Ведь это был гордый цветок.", "zh": "原来这是一朵骄傲的花儿。", "t": [30212, 31988]}]}]}, {"id": "ch10", "title_ru": "Глава 10", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"ru": "Маленький принц очутился вблизи астероидов 325, 326, 327, 329 и 330.", "zh": "小王子发现自己置身于小行星325号、326号、327号、329号和330号的附近。", "t": [100, 7225]}, {"ru": "Он решил их посетить, чтобы занять себя и чему-нибудь научиться.", "zh": "他决定去拜访它们，以消磨时光并增长见识。", "t": [7225, 13975]}, {"ru": "На первом астероиде жил король.", "zh": "第一个小行星上住着一位国王。", "t": [13975, 16900]}, {"ru": "В пурпурной мантии, украшенной мехом горностаев, он восседал на простом и вместе с тем величественном троне.", "zh": "他身着紫红色长袍，缀以貂皮装饰，端坐在既简朴又威严的宝座上。", "t": [16900, 24075]}, {"ru": "— А!", "zh": "哈！", "t": [24075, 25338]}, {"ru": "Вот и подданный!", "zh": "又是一个臣民！", "t": [25338, 27638]}, {"ru": "— воскликнул король, заметив маленького принца.", "zh": "国王，一见小王子，便大声喊道。", "t": [27638, 31612]}, {"ru": "А маленький принц удивился: «Как он меня узнал?", "zh": "小王子惊讶地问：“他怎么认出我的？”", "t": [31612, 35250]}, {"ru": "Ведь он меня ни разу не видел!»", "zh": "他从未见过我！", "t": [35250, 38100]}, {"ru": "Маленький принц не знал, что для королей мир устроен довольно просто.", "zh": "小王子不知，国王们眼中的世界颇为简单。", "t": [38100, 42750]}, {"ru": "Ведь для них все люди — подданные.", "zh": "他们视所有人为臣民。", "t": [42750, 46062]}, {"ru": "— Подойди поближе, чтобы я мог тебя рассмотреть получше, — сказал ему король.", "zh": "靠近些，让我好好端详你。", "t": [46062, 51238]}, {"ru": "Он был необычайно горд, что наконец-то стал для кого-то повелителем.", "zh": "他自豪地宣称，终于有人臣服于他。", "t": [51238, 56200]}, {"ru": "Маленький принц поискал глазами, куда бы присесть, но вся планета была занята великолепной горностаевой мантией короля.", "zh": "小王子环顾四周，却见整个星球都被国王那华丽的貂皮披风占据了。", "t": [56200, 63788]}, {"ru": "И он остался стоять, а поскольку устал, то зевнул.", "zh": "他站立着，由于疲乏，便打了个哈欠。", "t": [63788, 67888]}, {"ru": "— Это совершенно против правил — зевать в присутствии короля, — сказал ему монарх.", "zh": "这违背了宫廷礼仪——在国王面前打哈欠，国王对他说。", "t": [67888, 73425]}, {"ru": "— Я тебе это запрещаю.", "zh": "我不许你这样。", "t": [73425, 76138]}, {"ru": "— Но я не могу удержаться от зевоты, — смущенно ответил маленький принц.", "zh": "小王子尴尬地回答：“但我忍不住要打哈欠。”", "t": [76138, 81050]}, {"ru": "— Я проделал такой долгий путь и давно не спал.", "zh": "我长途跋涉，久未安眠。", "t": [81050, 83813]}]}, {"id": "ch10p01", "audio": true, "sents": [{"ru": "— Тогда, — сказал король, — я приказываю тебе зевать.", "zh": "陛下说：“那么，我命令你打哈欠。”", "t": [100, 4250]}, {"ru": "Я не видел как зевают уже много лет.", "zh": "我已多年未见有人打哈欠。", "t": [4250, 7350]}, {"ru": "Зевающие люди меня забавляют.", "zh": "打哈欠的人令我发笑。", "t": [7350, 10388]}, {"ru": "Ну, давай!", "zh": "那就开始吧！", "t": [10388, 12462]}, {"ru": "Зевни еще разок.", "zh": "再打一个哈欠。", "t": [12462, 14788]}, {"ru": "Это приказ!", "zh": "这是命令！", "t": [14788, 16612]}, {"ru": "— У меня больше не получается, — смутился маленький принц и густо покраснел.", "zh": "小王子尴尬地涨红了脸，说道：“我再也打不了了。”", "t": [16612, 21688]}, {"ru": "— Вот как?", "zh": "这就对了？", "t": [21688, 23450]}, {"ru": "— ответил король.", "zh": "国王答道。", "t": [23450, 25500]}, {"ru": "— Тогда я…", "zh": "那时我便…", "t": [25500, 27212]}, {"ru": "Я приказываю тебе зевать, а то…", "zh": "我命令你打哈欠，否则…", "t": [27212, 30400]}, {"ru": "Он забормотал и казался сбитым с толку.", "zh": "他结结巴巴，显得有些慌乱。", "t": [30400, 32900]}]}, {"id": "ch10p02", "audio": true, "sents": [{"ru": "Для короля ведь было очень важно не потерять авторитет.", "zh": "对国王来说，维护权威至关重要。", "t": [100, 4062]}, {"ru": "Он не выносил непокорности.", "zh": "他无法忍受反抗。", "t": [4062, 6825]}, {"ru": "Это был абсолютный монарх.", "zh": "这真是一位绝对的君主。", "t": [6825, 9512]}, {"ru": "Но поскольку он был правителем добрым, то отдавал лишь разумные приказы.", "zh": "然而，既然他是一位仁慈的君主，便只发布合理的命令。", "t": [9512, 14412]}, {"ru": "«Если я прикажу, — говорил он частенько, — какому-нибудь генералу превратиться в морскую птицу, и он не подчинится, это будет вина не генерала.", "zh": "若我下令，将军变作海鸟，他不遵命，那错不在将军。", "t": [14412, 23075]}, {"ru": "Виноват буду я».", "zh": "我该受罚。", "t": [23075, 25338]}, {"ru": "— Могу я присесть?", "zh": "我可以坐下吗？", "t": [25338, 27512]}, {"ru": "— робко осведомился маленький принц.", "zh": "小王子怯怯地问道。", "t": [27512, 30612]}, {"ru": "— Я приказываю тебе сесть, — ответил ему король, подобрав полу своей горностаевой мантии.", "zh": "陛下，请坐，国王答道，抖了抖他的貂皮披风。", "t": [30612, 36875]}, {"ru": "Однако маленькому принцу стало любопытно, чем можно было править на такой маленькой планетке.", "zh": "然而，小王子好奇，在这颗小小的星球上，可以统治些什么。", "t": [36875, 42750]}, {"ru": "— Сир, — сказал он королю, — прошу меня простить, что спрашиваю…", "zh": "陛下，请原谅我向您提个问题……", "t": [42750, 46825]}, {"ru": "— Я приказываю тебе меня спрашивать!", "zh": "我命令你向我提问！", "t": [46825, 49588]}, {"ru": "— поспешно перебил король.", "zh": "国王急忙打断。", "t": [49588, 52012]}, {"ru": "— Сир… а над чем вы властвуете?", "zh": "陛下，您统治着什么？", "t": [52012, 55162]}, {"ru": "— Над всем!", "zh": "统治着一切！", "t": [55162, 56912]}, {"ru": "— простодушно ответил король.", "zh": "国王率真地回答。", "t": [56912, 59625]}, {"ru": "— Над всем?", "zh": "统治着一切？", "t": [59625, 61350]}, {"ru": "Король скромно указал на свою планетку и на другие планеты со звездами.", "zh": "国王谦逊地指向自己的星球和那些带有星星的其它行星。", "t": [61350, 66338]}, {"ru": "— Над всем этим?", "zh": "统治着这一切？", "t": [66338, 68338]}, {"ru": "— переспросил маленький принц.", "zh": "小王子又问。", "t": [68338, 71000]}, {"ru": "— Над всем этим, — гордо ответил король.", "zh": "统治着这一切，国王傲然回答。", "t": [71000, 74338]}, {"ru": "Ведь он был не только монархом абсолютным, но и вселенским.", "zh": "他不仅是绝对君主，还是宇宙之王。", "t": [74338, 78612]}, {"ru": "— И вам повинуются звезды?", "zh": "星星都服从您吗？", "t": [78612, 80237]}]}, {"id": "ch10p03", "audio": true, "sents": [{"ru": "— Разумеется, — сказал король.", "zh": "当然，国王说。", "t": [100, 3125]}, {"ru": "— По первому приказу.", "zh": "遵命即行。", "t": [3125, 5388]}, {"ru": "Я не терплю неповиновения!", "zh": "我无法容忍违抗！", "t": [5388, 8400]}, {"ru": "Такое могущество восхитило маленького принца.", "zh": "这股力量令小王子叹为观止。", "t": [8400, 12012]}, {"ru": "Если бы он обладал подобной властью, то мог бы присутствовать не только при сорока четырех, а при семидесяти двух или даже при сотне или при двух сотнях закатов солнца в течение одного дня, даже не передвигая свой стул!", "zh": "若拥有如此权力，他便能每日目睹七十二次，甚至一百次或两百次日落，而无需挪动座椅！", "t": [12012, 24412]}, {"ru": "А поскольку после расставания со своей планетой маленькому принцу было грустно, он осмелился попросить у короля милости.", "zh": "小王子因与自己的星球离别而感到忧伤，便大胆地向国王请求恩典。", "t": [24412, 31700]}, {"ru": "— Я хотел бы увидеть закат солнца…", "zh": "我想看看日落。", "t": [31700, 34725]}, {"ru": "Сделайте одолжение — прикажите солнцу зайти…", "zh": "请下令，让太阳落山吧……", "t": [34725, 37850]}, {"ru": "— Если бы я приказал какому-нибудь генералу перелетать с одного цветка на другой подобно бабочке, или написать великую трагедию, или превратиться в морскую птицу, и, если бы генерал не выполнил этот полученный приказ, кто был бы в этом виноват — он или я?", "zh": "若我命令一位将军像蝴蝶般穿梭于花间，或撰写一部悲剧，或化为海鸟，而将军不遵从这一命令，那么责任在谁？是他，还是我？", "t": [37850, 51950]}, {"ru": "— Конечно, вы, — уверенно ответил маленький принц.", "zh": "当然，你，小王子自信地回答。", "t": [51950, 56000]}, {"ru": "— Верно.", "zh": "是的。", "t": [56000, 57588]}, {"ru": "От каждого надо требовать лишь то, на что он способен, — продолжил король.", "zh": "每个臣民只需尽其所能——国王继续说道。", "t": [57588, 62625]}, {"ru": "— Власть держится прежде всего на разуме.", "zh": "权力首先建立在理智之上。", "t": [62625, 66088]}, {"ru": "Если прикажешь своему народу пойти и броситься в пропасть, он устроит революцию.", "zh": "若你命令你的子民跳入深渊，他们便会起义。", "t": [66088, 71850]}, {"ru": "А я могу требовать повиновения, ведь мои приказы разумны.", "zh": "我要求服从，因我的命令明智。", "t": [71850, 76212]}, {"ru": "— А как же заход солнца?", "zh": "那日落怎么办呢？", "t": [76212, 78712]}, {"ru": "— напомнил маленький принц, который никогда не отступал, если задавал вопрос.", "zh": "小王子提醒道，他一旦提问，就绝不放弃。", "t": [78712, 83324]}]}, {"id": "ch10p04", "audio": true, "sents": [{"ru": "— Получишь ты свой закат.", "zh": "你将看到你的日落。", "t": [100, 2625]}, {"ru": "Я этого потребую!", "zh": "我这就要求！", "t": [2625, 5025]}, {"ru": "Однако надо подождать.", "zh": "然而，得稍等片刻。", "t": [5025, 7500]}, {"ru": "В науке управления важно выбрать подходящий момент.", "zh": "管理之道，时机至关重要。", "t": [7500, 11438]}, {"ru": "— А когда он настанет?", "zh": "他何时到来？", "t": [11438, 13900]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [13900, 16525]}, {"ru": "— Так, так, — ответил король, взглянув сначала на большой календарь.", "zh": "陛下，先看看大皇历。", "t": [16525, 21562]}, {"ru": "— Так, так…", "zh": "如此，如此…", "t": [21562, 23488]}, {"ru": "Это произойдет…", "zh": "这将会发生…", "t": [23488, 25612]}, {"ru": "Это случится…", "zh": "这将会发生…", "t": [25612, 27712]}, {"ru": "Этим вечером около семи часов двадцати минут!", "zh": "今夜七点二十分左右", "t": [27712, 31400]}, {"ru": "И ты увидишь, как всё мне повинуется!", "zh": "你将看到，一切皆遵我命。", "t": [31400, 34912]}, {"ru": "Маленький принц зевнул.", "zh": "小王子打了个哈欠。", "t": [34912, 37450]}, {"ru": "Он уже пожалел о пропущенных закатах на своей собственной планете.", "zh": "他已为错过自己星球上的日落而感到惋惜。", "t": [37450, 42025]}, {"ru": "К тому же ему становилось скучно.", "zh": "他也开始觉得无聊了。", "t": [42025, 45000]}, {"ru": "— Пожалуй, мне тут больше делать нечего, — сказал он королю.", "zh": "他向国王说：“或许，我在这里已经无事可做了。”", "t": [45000, 49312]}, {"ru": "— Я лучше пойду.", "zh": "我最好还是走了。", "t": [49312, 51462]}, {"ru": "— Останься,— ответил король, которому было так лестно иметь подданного.", "zh": "陛下，留下吧，国王答道，拥有一个臣民让他感到如此荣幸。", "t": [51462, 56562]}, {"ru": "— Не уходи!", "zh": "别走！", "t": [56562, 58338]}, {"ru": "Я сделаю тебя министром…", "zh": "我封你为部长。", "t": [58338, 60300]}, {"ru": "— Министром чего?", "zh": "司法部长。", "t": [60300, 62050]}, {"ru": "— Ну… правосудия.", "zh": "司法部", "t": [62050, 64825]}, {"ru": "— Но тут некого судить!", "zh": "无人可审！", "t": [64825, 67400]}, {"ru": "— Как знать, — ответил ему король.", "zh": "谁知道呢，国王回答道。", "t": [67400, 70500]}, {"ru": "— Я еще не объехал все свое королевство.", "zh": "我尚未巡视完我的王国。", "t": [70500, 73862]}, {"ru": "Я очень стар, места для кареты у меня нет, а ходить пешком очень утомительно.", "zh": "我年事已高，此处无马车停放之地，步行又极为劳顿。", "t": [73862, 79362]}, {"ru": "— Да?", "zh": "嗯？", "t": [79362, 80738]}, {"ru": "Но я уже все видел, — сказал маленький принц и наклонился, чтобы еще раз бросить взгляд на другую сторону планеты.", "zh": "但我已看尽一切，小王子说着，又俯身朝星球的另一端瞥了一眼。", "t": [80738, 87900]}, {"ru": "— Тут никого нет.", "zh": "这里无人。", "t": [87900, 89938]}, {"ru": "— Тогда ты будешь судить себя самого, — ответил король.", "zh": "那么，你就审判你自己吧，国王回答道。", "t": [89938, 93925]}, {"ru": "— А это труднее всего.", "zh": "这最难了。", "t": [93925, 96288]}, {"ru": "Это значительно сложнее, чем судить других.", "zh": "这比审判他人要复杂得多。", "t": [96288, 100075]}, {"ru": "Если ты сможешь правильно судить о себе, значит, ты поистине мудр.", "zh": "若能明辨己身，方是真智者。", "t": [100075, 104200]}]}, {"id": "ch10p05", "audio": true, "sents": [{"ru": "— Но я, — возразил маленький принц, — могу судить о себе самом где угодно.", "zh": "但我，小王子反驳道，我可以在任何地方审判自己。", "t": [100, 5362]}, {"ru": "Для этого не нужно здесь жить.", "zh": "为此无需在此居住。", "t": [5362, 8112]}, {"ru": "— Так, так…", "zh": "嗯，嗯…", "t": [8112, 9212]}, {"ru": "— сказал король.", "zh": "国王说道。", "t": [9212, 11050]}, {"ru": "— Однако я точно знаю, что на моей планете где-то живет старая крыса.", "zh": "然而，我确切地知道，在我的星球上，某处住着一只老耗子。", "t": [11050, 15875]}, {"ru": "Я слышу ее по ночам.", "zh": "我夜间能听到它。", "t": [15875, 18450]}, {"ru": "Ты можешь судить ее и время от времени приговаривать к смерти.", "zh": "你可以审判它，并时不时地宣判它死刑。", "t": [18450, 22638]}, {"ru": "Тогда ее жизнь будет зависеть от твоего судейского решения.", "zh": "她的生命将取决于你作为法官的决定。", "t": [22638, 27038]}, {"ru": "Но каждый раз из милости и экономии ты будешь ее миловать.", "zh": "但每次出于仁慈和节约，你都将宽恕它。", "t": [27038, 31400]}, {"ru": "Ведь она тут одна…", "zh": "她在这儿独自一人…", "t": [31400, 32762]}, {"ru": "— Но я, — возразил маленький принц, — не люблю приговаривать к смерти, поэтому я, пожалуй, пойду.", "zh": "但我，小王子反驳道，我不喜欢判人死刑，所以我还是走吧。", "t": [32762, 39462]}, {"ru": "— Нет, не пойдешь!", "zh": "你不能走！", "t": [39462, 41888]}, {"ru": "— сказал король.", "zh": "国王说道。", "t": [41888, 43900]}, {"ru": "Однако уже собравшемуся в путь маленькому принцу не хотелось огорчать старого монарха.", "zh": "然而，即将踏上旅程的小王子不愿让这位老君主感到悲伤。", "t": [43900, 49450]}, {"ru": "— Если вы, Ваше Величество, желаете беспрекословного подчинения, отдайте мне разумный приказ.", "zh": "若陛下您希望得到绝对的服从，就请下达一个合理的命令。", "t": [49450, 56025]}, {"ru": "Вы могли бы, к примеру, мне повелеть не мешкая отправиться в дорогу.", "zh": "您可以立即下令，让我启程上路。", "t": [56025, 60862]}, {"ru": "Мне кажется, что момент для этого самый подходящий.", "zh": "这似乎正是做这件事的最佳时机。", "t": [60862, 65125]}, {"ru": "И поскольку король на это ничего не ответил, маленький принц после минутного колебания со вздохом отправился в путь.", "zh": "国王未作回应，小王子犹豫片刻，叹了口气，便踏上了旅程。", "t": [65125, 72075]}, {"ru": "— Я назначаю тебя своим послом!", "zh": "我封你为大使！", "t": [72075, 75062]}, {"ru": "— успел крикнуть ему вдогонку король.", "zh": "国王追喊而去。", "t": [75062, 78100]}, {"ru": "Вид у него при этом был очень властный.", "zh": "他显得威严十足。", "t": [78100, 81325]}, {"ru": "«Взрослые такие странные», — подумал маленький принц, продолжая свой полет.", "zh": "大人们真是奇怪，小王子边飞边想。", "t": [81325, 86013]}]}]}, {"id": "ch11", "title_ru": "Глава 11", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"ru": "На второй планете жил честолюбец.", "zh": "第二颗星球上住着一个自命不凡的人。", "t": [100, 3125]}, {"ru": "— Ага!", "zh": "啊哈！", "t": [3125, 4600]}, {"ru": "— закричал он, еще издалека заметив маленького принца.", "zh": "他大声呼喊，远远地就发现了小王子。", "t": [4600, 8950]}, {"ru": "— Вот и почитатель явился!", "zh": "一位崇拜者来了！", "t": [8950, 11538]}, {"ru": "Ведь для честолюбцев все прочие люди являются лишь почитателями и поклонниками.", "zh": "虚荣者眼中，世人皆成崇拜者与追随者。", "t": [11538, 17075]}, {"ru": "— Добрый день, — сказал маленький принц.", "zh": "您好，小王子说。", "t": [17075, 20475]}, {"ru": "— У вас очень забавная шляпа.", "zh": "您这顶帽子真有趣。", "t": [20475, 23250]}, {"ru": "— Она чтобы раскланиваться, — ответил честолюбец.", "zh": "她这是要行礼，虚荣者答道。", "t": [23250, 27138]}, {"ru": "— Я снимаю ее, когда мне аплодируют, но, к несчастью, здесь никого не бывает.", "zh": "我摘下它，当有人为我鼓掌时，但不幸的是，这里从没人来。", "t": [27138, 33075]}, {"ru": "— В самом деле?", "zh": "果真如此？", "t": [33075, 35038]}, {"ru": "— ответил маленький принц, который мало что понял.", "zh": "小王子回答，他不太明白。", "t": [35038, 38950]}, {"ru": "— Похлопай одной ладонью по другой, — посоветовал ему честолюбец.", "zh": "请用手掌拍击另一手掌——虚荣者建议道。", "t": [38950, 43762]}, {"ru": "Маленький принц похлопал руками, и тогда честолюбец изящно его приветствовал, приподняв над головой свою шляпу.", "zh": "小王子拍手，那自命不凡的人便优雅地向他致意，举帽过头。", "t": [43762, 51262]}, {"ru": "«Тут веселее, чем на планете у короля», — подумал при этом маленький принц.", "zh": "这里比国王的星球上有趣多了。", "t": [51262, 56325]}, {"ru": "И он снова начал хлопать в ладоши, а честолюбец продолжал приподнимать свою шляпу.", "zh": "他再次拍起手来，那自命不凡的人便不停地举起他的帽子。", "t": [56325, 62188]}, {"ru": "Минут через пять эта однообразная игра маленькому принцу надоела.", "zh": "五分钟后，这单调的游戏让小王子感到厌烦。", "t": [62188, 66900]}, {"ru": "— А что надо сделать, чтобы шляпа упала?", "zh": "那得怎么做才能让这顶帽子掉下来呢？", "t": [66900, 70388]}, {"ru": "— спросил он честолюбца.", "zh": "他问那自命不凡的人。", "t": [70388, 73188]}, {"ru": "Однако тот его не услышал.", "zh": "然而，他并未听见。", "t": [73188, 75900]}, {"ru": "Ведь честолюбцы не слышат ничего, кроме восхвалений.", "zh": "虚荣者只听见赞美之词。", "t": [75900, 79150]}]}, {"id": "ch11p01", "audio": true, "sents": [{"ru": "— Ты ведь действительно мной ужасно восхищаешься?", "zh": "你难道不真的非常崇拜我吗？", "t": [100, 3662]}, {"ru": "— спросил честолюбец маленького принца.", "zh": "虚荣者问小王子。", "t": [3662, 7038]}, {"ru": "— А что значит «восхищаться»?", "zh": "“‘崇拜’是什么意思？”", "t": [7038, 10038]}, {"ru": "— Восхищаться?", "zh": "“您是真心崇拜吗？”", "t": [10038, 12075]}, {"ru": "Это значит признавать, что я самый лучший, самый нарядный, самый богатый и самый умный на этой планете.", "zh": "这便意味着承认我是这颗星球上最出色、最讲究、最富有、最聪明的人。", "t": [12075, 19375]}, {"ru": "— Но ты же тут один!", "zh": "然而，你在这里却孤身一人！", "t": [19375, 21550]}, {"ru": "— Ну, пожалуйста, сделай одолжение, повосхищайся мной еще немного!", "zh": "请再夸赞我几句吧！", "t": [21550, 26762]}, {"ru": "— Хорошо, — сказал маленький принц, пожав плечами.", "zh": "好吧，小王子耸了耸肩。", "t": [26762, 30988]}, {"ru": "— Я тобой восхищаюсь.", "zh": "我对你十分钦佩。", "t": [30988, 33425]}, {"ru": "Но какой тебе от этого прок?", "zh": "这对你又有什么好处呢？", "t": [33425, 36225]}, {"ru": "И маленький принц помчался дальше.", "zh": "小王子飞奔而去。", "t": [36225, 39325]}, {"ru": "«Нет, определенно взрослые весьма странные создания», — думал он про себя во время полета.", "zh": "大人们确实很奇怪，他想。", "t": [39325, 44400]}]}]}, {"id": "ch12", "title_ru": "Глава 12", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"ru": "На следующей планете жил пьяница.", "zh": "那颗星球上住着一个酒鬼。", "t": [100, 3312]}, {"ru": "Визит к нему был коротким, и он весьма огорчил маленького принца.", "zh": "他的访问虽短，却让小王子深感不悦。", "t": [3312, 7213]}]}, {"id": "ch12p01", "audio": true, "sents": [{"ru": "— Что ты тут делаешь?", "zh": "你在忙些什么呢？", "t": [100, 2288]}, {"ru": "— спросил он пьяницу, который сидел перед целой коллекцией пустых и полных бутылок.", "zh": "他问那酒鬼，只见他坐在一排空瓶子和满瓶子的面前。", "t": [2288, 8200]}, {"ru": "— Я пью, — мрачно ответил пьяница.", "zh": "“我喝着呢，”酒鬼闷闷不乐地回答。", "t": [8200, 11600]}, {"ru": "— И зачем ты пьешь?", "zh": "你为何饮酒？", "t": [11600, 13738]}, {"ru": "— поинтересовался маленький принц.", "zh": "小王子好奇地问。", "t": [13738, 16675]}, {"ru": "— Чтобы забыть, — ответил пьяница.", "zh": "为了忘记，酒鬼答道。", "t": [16675, 20075]}, {"ru": "— Забыть что?", "zh": "为了忘却何事？", "t": [20075, 21912]}, {"ru": "— с сочувствием осведомился маленький принц.", "zh": "小王子带着同情询问。", "t": [21912, 25388]}, {"ru": "— Что мне стыдно, — признался пьяница, опустив голову.", "zh": "我为羞愧而饮酒，酒鬼垂头丧气地坦白。", "t": [25388, 28863]}]}, {"id": "ch12p02", "audio": true, "sents": [{"ru": "— Стыдно что?", "zh": "羞愧什么呢？", "t": [100, 1888]}, {"ru": "— спросил маленький принц, которому захотелось ему помочь.", "zh": "小王子想帮他，便问道。", "t": [1888, 6362]}, {"ru": "— Стыдно, что я пью, — буркнул пьяница и надолго замолк.", "zh": "羞愧我饮酒，酒鬼嘟囔着，久久不再言语。", "t": [6362, 10800]}, {"ru": "И маленький принц покинул эту планету в полной растерянности.", "zh": "小王子对这个星球彻底困惑，离开了。", "t": [10800, 15062]}, {"ru": "«Взрослые определенно очень, очень странные», — снова подумал он про себя во время полета.", "zh": "大人们确实非常、非常古怪，他想。", "t": [15062, 20288]}]}]}, {"id": "ch13", "title_ru": "Глава 13", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"ru": "На четвертой планете обитал бизнесмен.", "zh": "第四颗星球上住着一位商人。", "t": [100, 3475]}, {"ru": "Этот человек был так занят, что даже не поднял голову при появлении маленького принца.", "zh": "那人忙得连头都未抬，小王子到来时。", "t": [3475, 9225]}, {"ru": "— Добрый день, — поздоровался маленький принц.", "zh": "你好，小王子问候道。", "t": [9225, 12800]}, {"ru": "— Смотрите, ваша сигарета погасла.", "zh": "您的香烟熄灭了。", "t": [12800, 16000]}, {"ru": "— Три да два — пять.", "zh": "三加二等于五。", "t": [16000, 18462]}, {"ru": "Семь и пять — двенадцать.", "zh": "七加五等于十二。", "t": [18462, 21162]}, {"ru": "Двенадцать и три — пятнадцать.", "zh": "十二加三等于十五。", "t": [21162, 24138]}, {"ru": "Привет.", "zh": "你好。", "t": [24138, 25788]}, {"ru": "Пятнадцать и семь — двадцать два.", "zh": "十五加七等于二十二。", "t": [25788, 28538]}, {"ru": "Двадцать два и шесть — двадцать восемь.", "zh": "二十二加六等于二十八。", "t": [28538, 31675]}, {"ru": "У меня нет времени ее снова зажечь.", "zh": "我无暇再为她点燃。", "t": [31675, 34750]}, {"ru": "Двадцать шесть и пять — тридцать один.", "zh": "二十六加五等于三十一。", "t": [34750, 38025]}, {"ru": "Уф!", "zh": "哎呀！", "t": [38025, 39400]}, {"ru": "Итого получается пятьсот один миллион шестьсот двадцать две тысячи семьсот тридцать один.", "zh": "五亿零一百六十二万二千七百三十一。", "t": [39400, 44700]}, {"ru": "— Пятьсот миллионов чего?", "zh": "五亿零一百六十二万二千七百三十一个什么？", "t": [44700, 47062]}, {"ru": "— Что?", "zh": "什么？", "t": [47062, 48525]}, {"ru": "Ты еще тут?", "zh": "你还在这儿？", "t": [48525, 50412]}, {"ru": "Пятьсот один миллион…", "zh": "五亿零一百万…", "t": [50412, 52700]}, {"ru": "Чего?..", "zh": "什么？", "t": [52700, 54288]}, {"ru": "Я уже не помню.", "zh": "我已经不记得了。", "t": [54288, 56412]}, {"ru": "У меня столько дел!", "zh": "如此多的事务在身。", "t": [56412, 58500]}, {"ru": "Я человек серьезный.", "zh": "我是个严肃的人。", "t": [58500, 61012]}, {"ru": "Меня не занимает всякий вздор.", "zh": "这等琐事，我并不放在心上。", "t": [61012, 63862]}, {"ru": "Два и пять — семь.", "zh": "二加五等于七。", "t": [63862, 66400]}, {"ru": "— Пятьсот миллионов чего?", "zh": "五亿零一百六十二万二千七百三十一个什么？", "t": [66400, 68775]}, {"ru": "— спросил маленький принц, который никогда не отступал, если задавал вопрос.", "zh": "小王子追问，从不放弃。", "t": [68775, 74175]}, {"ru": "Бизнесмен поднял голову: — За те пятьдесят четыре года, что я живу на этой планете, мне мешали всего три раза.", "zh": "商人抬起头：“在这颗星球上住了五十四年，总共只被打扰过三次。”", "t": [74175, 81000]}, {"ru": "Первый раз это случилось двадцать два года тому назад.", "zh": "第一次发生是在二十二年之前。", "t": [81000, 84738]}, {"ru": "Бог знает откуда сюда прилетел майский жук.", "zh": "不知这甲虫从何而来。", "t": [84738, 88350]}, {"ru": "Он ужасно жужжал, и я сделал четыре ошибки в сложении.", "zh": "他嗡嗡作响得厉害，我加减法里出了四个错。", "t": [88350, 92775]}, {"ru": "Второй случай был одиннадцать лет назад.", "zh": "第二次干扰发生在十一年前。", "t": [92775, 96112]}, {"ru": "Меня скрутил ревматизм.", "zh": "关节炎发作了。", "t": [96112, 98812]}]}, {"id": "ch13p01", "audio": true, "sents": [{"ru": "Мне не хватает движения, но у меня нет времени на прогулки.", "zh": "我缺乏运动，却无暇散步。", "t": [100, 1450]}, {"ru": "Ведь я человек серьезный.", "zh": "我是个严肃的人。", "t": [1450, 4162]}, {"ru": "А в третий раз сюда явился ты!", "zh": "你第三次来到这里了！", "t": [4162, 7012]}, {"ru": "Итак, я говорил — пятьсот один миллион…", "zh": "如此，我曾说——五亿零一百…", "t": [7012, 9838]}, {"ru": "— Миллионов чего?", "zh": "五亿零一百……是什么？", "t": [9838, 11612]}, {"ru": "Бизнесмен понял, что от него не отстанут.", "zh": "商人意识到他无法摆脱。", "t": [11612, 15112]}, {"ru": "— Миллионов этих маленьких штуковин, которые иногда видны на небе.", "zh": "数百万这些小玩意儿，有时在天上可见。", "t": [15112, 20100]}, {"ru": "— Мошек?", "zh": "苍蝇吗？", "t": [20100, 21750]}, {"ru": "— Да нет же!", "zh": "哎呀，别胡说了！", "t": [21750, 23500]}, {"ru": "Таких маленьких штучек, которые сияют.", "zh": "如此微小的光点，熠熠生辉。", "t": [23500, 27250]}, {"ru": "— Пчел?", "zh": "蜜蜂吗？", "t": [27250, 28675]}, {"ru": "— Да нет же!", "zh": "哎呀，别胡说了！", "t": [28675, 30412]}, {"ru": "Тех золотистых маленьких штучек, которые заставляют мечтать.", "zh": "那金色的小东西，能让人梦想飞扬。", "t": [30412, 35238]}, {"ru": "Но я-то человек серьезный.", "zh": "但我是个严肃的人。", "t": [35238, 38012]}, {"ru": "У меня нет времени предаваться пустым мечтам.", "zh": "我无暇沉溺于空想。", "t": [38012, 40600]}]}, {"id": "ch13p02", "audio": true, "sents": [{"ru": "— А!", "zh": "哎呀！", "t": [100, 1362]}, {"ru": "Звезд!", "zh": "星星", "t": [1362, 3038]}, {"ru": "— Вот именно — звезд.", "zh": "正是如此——星星。", "t": [3038, 5712]}, {"ru": "— И что ты делаешь с этими миллионами звезд?", "zh": "你用这些星星做什么？", "t": [5712, 9138]}, {"ru": "— С пятьсот одним миллионом шестьюстами двадцатью двумя тысячами семьсот тридцать одной звездой, если быть точным.", "zh": "五亿零一百六十二万二千七百三十一颗星星，如果精确地说。", "t": [9138, 15825]}, {"ru": "— Так что ты делаешь с этими звездами?", "zh": "你用这些星星做什么？", "t": [15825, 18925]}, {"ru": "— Что я с ними делаю?", "zh": "我拿它们有何用？", "t": [18925, 21212]}, {"ru": "— Ну, да…", "zh": "嗯，是啊…", "t": [21212, 22500]}, {"ru": "— Ничего.", "zh": "没什么。", "t": [22500, 24012]}, {"ru": "Я ими владею.", "zh": "我拥有它们。", "t": [24012, 26200]}, {"ru": "— Ты владеешь звездами?", "zh": "你拥有星星吗？", "t": [26200, 28675]}, {"ru": "— Да.", "zh": "是的。", "t": [28675, 30050]}, {"ru": "— Однако я уже видел короля, который…", "zh": "然而，我已经见过一个国王了。", "t": [30050, 32512]}, {"ru": "— Короли не владеют.", "zh": "国王并非拥有者。", "t": [32512, 34475]}, {"ru": "Они правят.", "zh": "他们统治着。", "t": [34475, 36362]}, {"ru": "Это совсем другое дело.", "zh": "这完全是另一码事。", "t": [36362, 38900]}, {"ru": "— А зачем тебе владеть звездами?", "zh": "你为何要拥有星星？", "t": [38900, 41838]}, {"ru": "— Зачем владеть?", "zh": "为何拥有？", "t": [41838, 43950]}, {"ru": "Чтобы быть богатым.", "zh": "为了富有。", "t": [43950, 46200]}, {"ru": "— А зачем тебе богатство?", "zh": "这财富对你有何用？", "t": [46200, 48638]}, {"ru": "— Чтобы приобретать новые звезды, когда их ктонибудь откроет.", "zh": "为了购买新发现的星星。", "t": [48638, 53325]}, {"ru": "«Этот взрослый, — подумал про себя маленький принц, — рассуждает почти как тот пьяница».", "zh": "这位大人，小王子心想，他的想法几乎和那个酒鬼一样。", "t": [53325, 59550]}, {"ru": "Тем не менее он спросил еще кое о чем: — Как можно владеть звездами?", "zh": "他仍好奇地问道：如何才能拥有星星？", "t": [59550, 64712]}, {"ru": "— А чьи они?", "zh": "这是谁的？", "t": [64712, 66662]}, {"ru": "— проворчал в ответ бизнесмен.", "zh": "商人咕哝着回答。", "t": [66662, 69312]}, {"ru": "— Я не знаю.", "zh": "我不知道。", "t": [69312, 71225]}, {"ru": "Наверно, ничьи.", "zh": "或许，无人所有。", "t": [71225, 73812]}, {"ru": "— Тогда они будут моими, раз я первый догадался ими владеть.", "zh": "那么，既然我是第一个想到要拥有它们的，它们就属于我了。", "t": [73812, 78212]}, {"ru": "— И этого достаточно?", "zh": "这还不够吗？", "t": [78212, 79637]}]}, {"id": "ch13p03", "audio": true, "sents": [{"ru": "— Вполне!", "zh": "完全如此！", "t": [100, 1750]}, {"ru": "Ведь если ты найдешь алмаз, который никому не принадлежит, он станет твоим.", "zh": "若你发现一颗无人所有的钻石，它便属于你。", "t": [1750, 7150]}, {"ru": "И если ты откроешь ничейный остров, он тоже станет твоим.", "zh": "若你发现一座无主的岛屿，它也将成为你的。", "t": [7150, 11812]}, {"ru": "А если тебе первому в голову приходит какая-то идея, ты ее патентуешь, и тогда она твоя.", "zh": "若你第一个想到某个主意，便可申请专利，那时它便属于你。", "t": [11812, 18138]}, {"ru": "Я владею звездами просто потому, что раньше еще никому не приходило в голову ими завладеть.", "zh": "我拥有星星，只因此前无人想过占有。", "t": [18138, 24188]}, {"ru": "— Это правда, — сказал маленький принц.", "zh": "这倒是真的，小王子说。", "t": [24188, 27462]}, {"ru": "— И что ты с ними делаешь?", "zh": "你拿它们有何用？", "t": [27462, 29950]}, {"ru": "— Я ими распоряжаюсь.", "zh": "我管理着它们。", "t": [29950, 32438]}, {"ru": "Считаю их и пересчитываю, — ответил бизнесмен.", "zh": "我数它们，又重新数一遍，商人答道。", "t": [32438, 36488]}, {"ru": "— Это трудно, но я человек серьезный.", "zh": "这虽难，但我是个认真的人。", "t": [36488, 39700]}, {"ru": "Однако маленькому принцу было все-таки кое-что не ясно.", "zh": "然而，小王子还是有些地方不明白。", "t": [39700, 43738]}, {"ru": "— Если я владею шейным платком, я могу им распорядиться — повязать на шею и уйти с ним.", "zh": "若我拥有一条围巾，便可随意佩戴，带走它。", "t": [43738, 49750]}, {"ru": "Если мне принадлежит цветок, я могу его сорвать и унести.", "zh": "若我拥有这朵花，便可摘下带走。", "t": [49750, 54338]}, {"ru": "Но ты ведь не можешь собрать звезды!", "zh": "你怎能收集星星呢？", "t": [54338, 57300]}, {"ru": "— Не могу.", "zh": "我做不到。", "t": [57300, 58962]}, {"ru": "Зато я могу поместить их в банк.", "zh": "我可以把它们存入银行。", "t": [58962, 62112]}, {"ru": "— Как это?", "zh": "这怎么行？", "t": [62112, 63750]}, {"ru": "Что это значит?", "zh": "这究竟是什么意思？", "t": [63750, 65900]}, {"ru": "— Это значит, что я записываю на бумажке количество моих звезд, помещаю эту бумажку в ящик и запираю его на ключ.", "zh": "这便意味着，我把我的星星数目记在纸上，把纸条放进抽屉，再锁上锁。", "t": [65900, 73400]}, {"ru": "— И все?", "zh": "就这样？", "t": [73400, 75038]}, {"ru": "— Этого достаточно.", "zh": "这便足够了。", "t": [75038, 77288]}, {"ru": "«Это забавно, — подумал маленький принц.", "zh": "这倒有趣，小王子心想。", "t": [77288, 80600]}, {"ru": "— Звучит красиво, но не слишком серьезно».", "zh": "这听起来挺美，但不太严肃。", "t": [80600, 84262]}, {"ru": "В отличие от взрослых маленький принц имел совсем другие представления о серьезных вещах.", "zh": "小王子对“严肃”的理解与大人截然不同。", "t": [84262, 89413]}]}, {"id": "ch13p04", "audio": true, "sents": [{"ru": "— Вот я, — заметил он снова, — владею цветком, который поливаю каждый день.", "zh": "这就是我，他又说，我有一朵花，每天都给它浇水。", "t": [100, 5462]}, {"ru": "У меня есть три вулкана, которые я прочищаю каждую неделю.", "zh": "我有三座火山，每周都要清理。", "t": [5462, 10238]}, {"ru": "Я чищу также и потухший вулкан.", "zh": "我也清理那熄灭的火山。", "t": [10238, 13450]}, {"ru": "Просто так — на всякий случай.", "zh": "只是以防万一。", "t": [13450, 16600]}, {"ru": "Моим вулканам и моему цветку идет на пользу, что я ими владею.", "zh": "我的火山和我的花朵因我拥有它们而受益。", "t": [16600, 21588]}, {"ru": "Но какая польза от тебя звездам?", "zh": "对你星星有何益处？", "t": [21588, 24625]}, {"ru": "Бизнесмен открыл рот, но так ничего и не ответил.", "zh": "商人张口结舌，无言以对。", "t": [24625, 28750]}, {"ru": "А маленький принц отправился дальше.", "zh": "小王子继续前行。", "t": [28750, 31912]}, {"ru": "«Определенно, взрослые совершенно необыкновенные создания», — повторял он мысленно по дороге.", "zh": "大人们真是奇怪得不可思议。", "t": [31912, 37400]}]}]}, {"id": "ch14", "title_ru": "Глава 14", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"ru": "Пятая планета оказалась самой забавной.", "zh": "第五颗星球竟是最有趣的。", "t": [100, 3500]}, {"ru": "Она была самой маленькой из им увиденных.", "zh": "她是他所见过的最小的一颗。", "t": [3500, 6912]}, {"ru": "Места на ней хватало только для фонаря и фонарщика.", "zh": "这颗星球仅能容纳一盏路灯和一个点灯人。", "t": [6912, 10962]}, {"ru": "Маленький принц не мог понять, зачем где-то в небе, на планете без домов и жителей, нужны фонарь и фонарщик.", "zh": "小王子无法理解，为何在无屋无人的星球上，天空中却需要一盏路灯和一位点灯人。", "t": [10962, 18425]}, {"ru": "Тем не менее он подумал — может, этот человек и странный, однако он не менее странен, чем король, бизнесмен и пьяница.", "zh": "然而他想：或许这个人虽古怪，却也不亚于那位国王、那位商人或那位酒鬼。", "t": [18425, 26475]}, {"ru": "По крайней мере, его работа имеет какой-то смысл.", "zh": "至少，他的工作尚有意义。", "t": [26475, 30388]}, {"ru": "Когда он зажигает свой фонарь, кажется, что загорается еще одна звезда или распускается новый цветок.", "zh": "当他点亮他的灯笼，仿佛又升起了一颗星星，或绽放了一朵新花。", "t": [30388, 37188]}, {"ru": "А когда он гасит фонарь, кажется, что звезда или цветок засыпают.", "zh": "当点灯人熄灭灯笼，仿佛星星或花朵进入了梦乡。", "t": [37188, 42312]}, {"ru": "Это приятная работа.", "zh": "这是一份愉快的工作。", "t": [42312, 44800]}, {"ru": "Она полезна, потому что порождает красоту.", "zh": "它孕育着美。", "t": [44800, 48450]}, {"ru": "Подлетев к этой планете, маленький принц вежливо поприветствовал фонарщика.", "zh": "小王子礼貌地向点灯人致意。", "t": [48450, 53500]}, {"ru": "— Добрый день, — сказал он.", "zh": "你好。", "t": [53500, 56275]}, {"ru": "— Почему ты только что погасил свой фонарь?", "zh": "你刚才为何熄灭了你的灯笼？", "t": [56275, 59450]}, {"ru": "— Таково правило, — ответил фонарщик.", "zh": "这是规定，点灯人答道。", "t": [59450, 62888]}, {"ru": "— Доброе утро.", "zh": "早上好。", "t": [62888, 65012]}, {"ru": "— Какое правило?", "zh": "这是哪条规定？", "t": [65012, 67012]}, {"ru": "— Надо погасить фонарь.", "zh": "熄灭灯笼。", "t": [67012, 69362]}, {"ru": "Добрый вечер!", "zh": "晚安。", "t": [69362, 71312]}, {"ru": "При этих словах он зажег свой фонарь.", "zh": "他点亮了灯笼。", "t": [71312, 74538]}, {"ru": "— А почему ты снова зажег его?", "zh": "你为何又把它点亮了？", "t": [74538, 77262]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [77262, 79888]}, {"ru": "— Таково правило, — ответил фонарщик.", "zh": "这是规定，点灯人答道。", "t": [79888, 83312]}, {"ru": "— Я не понимаю…", "zh": "我不明白…", "t": [83312, 84500]}, {"ru": "— сказал маленький принц.", "zh": "小王子说。", "t": [84500, 85988]}]}, {"id": "ch14p01", "audio": true, "sents": [{"ru": "— Нечего тут понимать, — сказал фонарщик.", "zh": "“这里没什么好理解的，”点灯人说。", "t": [100, 3862]}, {"ru": "— Правила есть правила.", "zh": "规定就是规定。", "t": [3862, 6238]}, {"ru": "Доброе утро!", "zh": "早上好！", "t": [6238, 8312]}, {"ru": "И он снова погасил свой фонарь.", "zh": "他又熄灭了灯笼。", "t": [8312, 10338]}]}, {"id": "ch14p02", "audio": true, "sents": [{"ru": "Потом он вытер свой лоб красным клетчатым платком.", "zh": "他用手帕擦拭额头。", "t": [100, 3900]}, {"ru": "— Эта ужасная работа изматывает.", "zh": "这份可怕的工作累得我筋疲力尽。", "t": [3900, 7100]}, {"ru": "Раньше было легче.", "zh": "往日更为简单。", "t": [7100, 9425]}, {"ru": "Я гасил фонарь по утрам и зажигал его вечером.", "zh": "我清晨熄灯，傍晚点亮。", "t": [9425, 13225]}, {"ru": "Днем я мог отдохнуть, а ночью выспаться.", "zh": "白天我得以休憩，夜晚我得以安眠。", "t": [13225, 16962]}, {"ru": "— С той поры изменились правила?", "zh": "自那以后，规则变了？", "t": [16962, 19912]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [19912, 22550]}, {"ru": "— Правила не изменились, — вздохнул фонарщик.", "zh": "规定并未更改，点灯人叹了口气。", "t": [22550, 26425]}, {"ru": "— В этом-то и беда.", "zh": "这便是祸根所在。", "t": [26425, 28788]}, {"ru": "С каждым годом эта планета вращается все быстрее, а правила остались прежними.", "zh": "这颗星球每年转速都在加快，而规则依旧如故。", "t": [28788, 34488]}, {"ru": "— И что теперь?", "zh": "现在怎么办呢？", "t": [34488, 36450]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [36450, 39062]}, {"ru": "— Теперь она делает оборот каждую минуту, и у меня нет ни секунды для отдыха.", "zh": "现在它每分钟转一圈，我连一秒钟的休息时间都没有。", "t": [39062, 44350]}, {"ru": "Раз в минуту я зажигаю и гашу этот фонарь.", "zh": "我每分钟点亮又熄灭这盏灯。", "t": [44350, 48075]}, {"ru": "— Это забавно!", "zh": "这真是有趣。", "t": [48075, 49975]}, {"ru": "Значит, сутки у тебя длятся всего минуту?", "zh": "那么，你的日子只持续一分钟？", "t": [49975, 53738]}, {"ru": "— Это совсем не забавно!", "zh": "这实在无趣至极。", "t": [53738, 56162]}, {"ru": "— ответил фонарщик.", "zh": "点灯人答道。", "t": [56162, 58525]}, {"ru": "— Мы с тобой разговариваем уже целый месяц!", "zh": "我们已交谈整整一个月了。", "t": [58525, 62062]}, {"ru": "— Месяц?", "zh": "一个月？", "t": [62062, 63712]}, {"ru": "— Ну, да.", "zh": "嗯，是啊。", "t": [63712, 65775]}, {"ru": "Тридцать дней.", "zh": "三十天", "t": [65775, 67712]}, {"ru": "Добрый вечер!", "zh": "晚安。", "t": [67712, 69675]}, {"ru": "И фонарщик опять зажег свой фонарь.", "zh": "点灯人又点亮了他的灯笼。", "t": [69675, 72762]}, {"ru": "Маленький принц задумчиво посмотрел на фонарщика.", "zh": "小王子若有所思地望着点灯人。", "t": [72762, 76675]}, {"ru": "Ему нравился этот человек, который не отступал от своих правил.", "zh": "他喜欢这个坚守规则的人。", "t": [76675, 81575]}, {"ru": "Он вспомнил, как и сам раньше не раз передвигал свой стул, наблюдая за закатами на своей планете.", "zh": "他想起自己也曾多次移动椅子，在星球上观赏日落。", "t": [81575, 87925]}, {"ru": "И маленькому принцу захотелось помочь своему новому знакомому.", "zh": "小王子想帮助这位新相识。", "t": [87925, 92438]}, {"ru": "— Послушай, — сказал он, — кажется, я знаю, как ты сможешь отдыхать, когда захочешь.", "zh": "你听着，我似乎知道你何时想休息。", "t": [92438, 97737]}]}, {"id": "ch14p03", "audio": true, "sents": [{"ru": "— Мне все время этого хочется.", "zh": "我总是想这么做。", "t": [100, 3100]}, {"ru": "Ведь можно же быть одновременно верным слову и немного лениться.", "zh": "既是忠于诺言，又不妨偷点懒。", "t": [3100, 7600]}, {"ru": "— Смотри, — продолжил маленький принц.", "zh": "——看哪，小王子继续说。", "t": [7600, 10962]}, {"ru": "— Твоя планета такая маленькая, что ты можешь обойти ее за три шага.", "zh": "你的星球如此之小，只需三步便可绕行一周。", "t": [10962, 15850]}, {"ru": "И если ты пойдешь достаточно медленно, ты все время будешь оставаться на солнце.", "zh": "若你走得足够慢，你将始终停留在阳光下。", "t": [15850, 21012]}, {"ru": "Захочешь отдохнуть от своей работы — просто пойди вперед, и твой день будет длиться, сколько пожелаешь.", "zh": "想休息一下你的工作——只需向前走，你的白天可以持续你想要的时长。", "t": [21012, 27450]}, {"ru": "— От этого будет мало проку, — вздохнул фонарщик.", "zh": "—— 点灯人叹了口气，说道：“这没什么用。”", "t": [27450, 31462]}, {"ru": "— Мне бы выспаться как следует.", "zh": "我正想好好睡一觉。", "t": [31462, 34275]}, {"ru": "Вот чего я хочу!", "zh": "这正是我所希望的！", "t": [34275, 36600]}, {"ru": "— Да, плохо твое дело, — посочувствовал маленький принц.", "zh": "小王子同情地说：“是啊，你的工作真糟糕。”", "t": [36600, 40962]}, {"ru": "— Да, не повезло, — ответил фонарщик.", "zh": "是啊，真不幸。", "t": [40962, 44538]}, {"ru": "— Доброе утро!", "zh": "早上好！", "t": [44538, 46612]}, {"ru": "И он опять погасил свой фонарь.", "zh": "他又熄灭了灯笼。", "t": [46612, 49488]}, {"ru": "«Наверняка этого взрослого, — подумал маленький принц, продолжив свое путешествие, — невзлюбили бы остальные: король, честолюбец, пьяница и бизнесмен.", "zh": "这位大人，小王子在继续他的旅行时想，其他人——国王、虚荣的人、酒鬼和商人——肯定不会喜欢他。", "t": [49488, 59500]}, {"ru": "Тем не менее он не кажется мне нелепым.", "zh": "然而，他并不显得荒谬。", "t": [59500, 62812]}, {"ru": "Возможно потому, что он занят своим делом, а не самим собой».", "zh": "或许是因为他专注于自己的工作，而非自身。", "t": [62812, 67488]}, {"ru": "При этом маленький принц вздохнул и добавил про себя: «Это единственный взрослый, который мог бы стать мне другом.", "zh": "小王子叹了口气，心中暗想：这是唯一一个可能成为我朋友的大人。", "t": [67488, 74462]}, {"ru": "Но его планета так мала, что двоим места на ней просто не хватит…»", "zh": "但这颗星球太小，容不下我们两个…", "t": [74462, 79500]}, {"ru": "Маленький принц не мог себе откровенно признаться, что он сожалеет об этой прекрасной планете просто потому, что он мог бы увидеть на ней тысячу четыреста сорок закатов за двадцать четыре часа!", "zh": "小王子无法坦白承认，他之所以对这颗美丽的星球感到惋惜，仅仅是因为他可以在二十四小时内看到一千四百四十次日落。", "t": [79500, 89326]}]}]}, {"id": "ch15", "title_ru": "Глава 15", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"ru": "Шестая планета была в десять раз больше.", "zh": "第六颗星球比那颗大十倍。", "t": [100, 3438]}, {"ru": "На ней жил старый господин, который писал толстенные книги.", "zh": "那颗星球上住着一位老先生，正撰写着厚重的书籍。", "t": [3438, 7250]}]}, {"id": "ch15p01", "audio": true, "sents": [{"ru": "— Ага!", "zh": "啊哈！", "t": [100, 1562]}, {"ru": "— воскликнул он, заметив маленького принца.", "zh": "他看见小王子，便大声喊道。", "t": [1562, 5288]}, {"ru": "— Вот и путешественник!", "zh": "这就是旅行者！", "t": [5288, 7875]}, {"ru": "Маленький принц присел за стол, чтобы немного отдышаться.", "zh": "小王子坐到桌边，稍作喘息。", "t": [7875, 12388]}, {"ru": "Ведь он уже проделал такой длинный путь.", "zh": "他已走过漫长的路途。", "t": [12388, 15650]}, {"ru": "— Ты откуда?", "zh": "你从哪里来？", "t": [15650, 17462]}, {"ru": "— спросил его старый господин.", "zh": "老先生问他。", "t": [17462, 20238]}, {"ru": "— А что это за толстая книга?", "zh": "这厚厚的书是关于什么的？", "t": [20238, 22938]}, {"ru": "— спросил его в ответ маленький принц.", "zh": "小王子问。", "t": [22938, 26100]}, {"ru": "— И что вы тут делаете?", "zh": "您在此有何贵干？", "t": [26100, 28462]}, {"ru": "— Я географ, — ответил старик.", "zh": "“我是地理学家。”老先生答道。", "t": [28462, 31700]}, {"ru": "— А кто такой географ?", "zh": "这位地理学家是做什么的？", "t": [31700, 34025]}, {"ru": "— Это ученый, который знает, где находятся моря, где расположены реки, города, горы и пустыни.", "zh": "这是位知晓海洋、江河、城市、山脉和沙漠所在地的学者。", "t": [34025, 41212]}, {"ru": "— Здорово!", "zh": "你好！", "t": [41212, 42925]}, {"ru": "— воскликнул маленький принц.", "zh": "小王子惊呼。", "t": [42925, 45662]}, {"ru": "— Это отличная профессия.", "zh": "这是一份崇高的职业。", "t": [45662, 47738]}]}, {"id": "ch15p02", "audio": true, "sents": [{"ru": "При этом он окинул восхищенным взором планету географа.", "zh": "他带着钦佩的目光扫视了地理学家的星球。", "t": [100, 4162]}, {"ru": "Он еще ни разу не видел таких величественных планет.", "zh": "他从未见过如此宏伟的星球。", "t": [4162, 8025]}, {"ru": "— Какая она красивая, ваша планета!", "zh": "您的星球真美。", "t": [8025, 11412]}, {"ru": "У нее есть океаны?", "zh": "这里有大洋吗？", "t": [11412, 13850]}, {"ru": "— Мне это неизвестно, — ответил географ.", "zh": "这我不知道。", "t": [13850, 17362]}, {"ru": "— Вот как…", "zh": "原来如此…", "t": [17362, 18425]}, {"ru": "— маленький принц был слегка разочарован.", "zh": "小王子略显失望。", "t": [18425, 21462]}, {"ru": "— А горы?", "zh": "有山脉吗？", "t": [21462, 23088]}, {"ru": "— И это мне неизвестно, — отвечал географ.", "zh": "这我也不清楚。", "t": [23088, 26588]}, {"ru": "— А города, реки и пустыни?", "zh": "有城市、河流和沙漠吗？", "t": [26588, 29825]}, {"ru": "— Это мне тоже неизвестно, — ответил географ.", "zh": "这我也不清楚。", "t": [29825, 33462]}, {"ru": "— Но вы же географ!", "zh": "但你可是地理学家啊！", "t": [33462, 35700]}, {"ru": "— Это верно, но я не путешественник.", "zh": "这倒是真的，但我并非旅行者。", "t": [35700, 38788]}, {"ru": "Мне их так не хватает.", "zh": "我多么需要它们。", "t": [38788, 41375]}, {"ru": "Ведь не географы изучают города, реки, горы, моря, океаны и пустыни.", "zh": "地理学家并非研究城市、江河、山脉、海洋、大洋和沙漠。", "t": [41375, 47725]}, {"ru": "Географ — слишком важная персона, чтобы слоняться там или сям.", "zh": "地理学家——如此重要的人物，岂能随意闲逛。", "t": [47725, 52938]}, {"ru": "Он не покидает стен своего кабинета.", "zh": "他从未离开过自己办公室的墙壁。", "t": [52938, 56162]}, {"ru": "Зато он принимает у себя путешественников.", "zh": "他接待旅行者。", "t": [56162, 59700]}, {"ru": "Он расспрашивает их и записывает их рассказы.", "zh": "他询问他们，记录下他们的讲述。", "t": [59700, 63325]}, {"ru": "И если какой-нибудь рассказ покажется ему интересным, географ поручает навести справки, можно ли этому рассказчику верить.", "zh": "若他觉得某个故事有趣，地理学家便会委托核实讲述者是否可信。", "t": [63325, 70838]}, {"ru": "— Это зачем?", "zh": "这又是为了什么？", "t": [70838, 72575]}, {"ru": "— Потому что если путешественник подвирает, это приведет к полнейшей путанице в учебниках по географии.", "zh": "因为如果旅行者撒谎，这会导致地理学教科书的完全混乱。", "t": [72575, 79088]}, {"ru": "К тому же вдруг он окажется пьяницей?", "zh": "他也许会是个酒鬼呢？", "t": [79088, 82188]}, {"ru": "— И что тогда?", "zh": "那时又如何呢？", "t": [82188, 84100]}, {"ru": "— поинтересовался маленький принц.", "zh": "小王子好奇地问。", "t": [84100, 87038]}, {"ru": "— У пьяниц все двоится в глазах.", "zh": "酒鬼眼中一切皆成双影。", "t": [87038, 89912]}, {"ru": "В результате географ опишет две горы там, где всего одна.", "zh": "地理学家会在那里描述两座山，而实际上只有一座。", "t": [89912, 93537]}]}, {"id": "ch15p03", "audio": true, "sents": [{"ru": "— Я был знаком с одним пьяницей, — заметил маленький принц.", "zh": "我曾认识一个酒鬼，小王子说道。", "t": [100, 4588]}, {"ru": "— Из него и впрямь вышел бы плохой путешественник.", "zh": "他确实会成为糟糕的旅行者。", "t": [4588, 8162]}, {"ru": "— Наверняка.", "zh": "当然。", "t": [8162, 10062]}, {"ru": "Но если путешественнику можно верить, надо навести справки о его открытии.", "zh": "但若可信赖旅行者的发现，便需核实其所述。", "t": [10062, 15562]}, {"ru": "— Надо пойти и посмотреть, что он открыл?", "zh": "那就去瞧瞧他都发现了什么？", "t": [15562, 19100]}, {"ru": "— Нет.", "zh": "没有。", "t": [19100, 20612]}, {"ru": "Это слишком хлопотно.", "zh": "这太过繁琐了。", "t": [20612, 23112]}, {"ru": "От путешественника требуют доказательств.", "zh": "旅行者需提供证据。", "t": [23112, 26525]}, {"ru": "Например, если речь идет о большой горе, надо, чтобы он оттуда принес большие камни.", "zh": "若是一座大山，就得让他从那里带来大石头。", "t": [26525, 32538]}, {"ru": "При этих словах географ неожиданно разволновался.", "zh": "地理学家闻言，突然激动起来。", "t": [32538, 36338]}, {"ru": "— А ты же прибыл издалека?", "zh": "你远道而来。", "t": [36338, 38988]}, {"ru": "Ты же путешественник!", "zh": "你是个旅行者！", "t": [38988, 41312]}, {"ru": "Ты мне расскажешь о своей планете!", "zh": "请告诉我你的星球吧！", "t": [41312, 44288]}, {"ru": "При этих словах географ открыл свой толстенный каталог и подточил карандаш.", "zh": "地理学家打开他那厚重的目录，削尖了铅笔。", "t": [44288, 49625]}, {"ru": "Ведь рассказы путешественников сперва записывают карандашом.", "zh": "旅行者的故事起初用铅笔记录。", "t": [49625, 54000]}, {"ru": "Чтобы записать их чернилами, надо дождаться представленных доказательств.", "zh": "待证据呈上，方可用墨水记录。", "t": [54000, 59162]}, {"ru": "— Ну?", "zh": "嗯？", "t": [59162, 60525]}, {"ru": "— поторопил географ.", "zh": "地理学家急切地。", "t": [60525, 62800]}, {"ru": "— У меня на планете, — сказал маленький принц, — не так уж много интересного.", "zh": "我的星球上，小王子说，并无太多趣味。", "t": [62800, 67975]}, {"ru": "Там все очень маленькое.", "zh": "那里一切都太小了。", "t": [67975, 70900]}, {"ru": "Есть три вулкана — два работают, а один потухший.", "zh": "有三座火山——两座活跃，一座熄灭。", "t": [70900, 75088]}, {"ru": "Но ведь никогда не знаешь, что может случиться.", "zh": "然而，你永远不知道会发生什么。", "t": [75088, 79038]}, {"ru": "— Это верно, — заметил географ.", "zh": "这倒是真的，地理学家说道。", "t": [79038, 82088]}, {"ru": "— У меня также есть цветок.", "zh": "我也有朵花。", "t": [82088, 84888]}, {"ru": "— Нас не интересуют цветы, — сказал географ.", "zh": "我们不对花感兴趣。", "t": [84888, 88712]}, {"ru": "— Но почему?", "zh": "但为何如此？", "t": [88712, 90550]}, {"ru": "Они же такие красивые!", "zh": "它们如此美丽！", "t": [90550, 93038]}, {"ru": "— Потому, что цветы эфемерны.", "zh": "因为花朵是短暂的。", "t": [93038, 96212]}, {"ru": "— Что значит «эфемерны»?", "zh": "“‘昙花一现’是什么意思？”", "t": [96212, 97900]}]}, {"id": "ch15p04", "audio": true, "sents": [{"ru": "— Книги по географии, — сказал географ, — самые ценные на свете.", "zh": "地理书籍，地理学家说，乃世间最珍贵的宝物。", "t": [100, 5150]}, {"ru": "Они никогда не устаревают.", "zh": "它们永远不会过时。", "t": [5150, 7825]}, {"ru": "Ведь редко так бывает, чтобы гора сдвинулась с места.", "zh": "山难得移动位置。", "t": [7825, 12088]}, {"ru": "Да и океаны пересыхают очень редко.", "zh": "海洋干涸极为罕见。", "t": [12088, 15438]}, {"ru": "Мы пишем о вещах вечных.", "zh": "我们书写永恒之物。", "t": [15438, 18250]}, {"ru": "— Но ведь потухший вулкан может проснуться, — перебил маленький принц.", "zh": "但熄灭的火山也可能苏醒，小王子打断了他的话。", "t": [18250, 22975]}, {"ru": "— Что же такое «эфемерный»?", "zh": "“什么叫做‘转瞬即逝’？”", "t": [22975, 26075]}, {"ru": "— Для нас, географов, потухший вулкан или действующий — все едино, — пояснил географ.", "zh": "对于地理学家来说，熄灭的火山或活跃的火山，都是一回事。", "t": [26075, 32688]}, {"ru": "Для нас важна сама гора.", "zh": "对我们而言，重要的是山本身。", "t": [32688, 35388]}, {"ru": "Он не меняется.", "zh": "它始终如一。", "t": [35388, 37588]}, {"ru": "— И все-таки что значит «эфемерный»?", "zh": "“‘转瞬即逝’究竟是什么意思？”", "t": [37588, 40888]}, {"ru": "— снова повторил маленький принц.", "zh": "小王子又重复了一遍。", "t": [40888, 43825]}, {"ru": "Ведь стоило ему задать вопрос, и он уже не отступал.", "zh": "一提出问题，他便决不退缩。", "t": [43825, 47788]}, {"ru": "— Такой, чему грозит скорое исчезновение.", "zh": "那朵花面临迅速消逝的威胁。", "t": [47788, 51575]}, {"ru": "— Значит, моему цветку грозит исчезновение?", "zh": "那么，我的花儿面临消失的威胁？", "t": [51575, 55588]}, {"ru": "— Разумеется.", "zh": "当然。", "t": [55588, 57562]}, {"ru": "«Мой цветок эфемерен!", "zh": "我的花儿是转瞬即逝的。", "t": [57562, 60025]}, {"ru": "— подумал при этом маленький принц.", "zh": "小王子心想。", "t": [60025, 62900]}, {"ru": "— И у него всего четыре шипа, чтобы защищаться от целого мира!", "zh": "她只有四根刺来抵御整个世界。", "t": [62900, 67550]}, {"ru": "А я его оставил дома совершенно одного!»", "zh": "我竟把他孤零零地留在了家里！", "t": [67550, 71150]}, {"ru": "В этот момент он впервые пожалел, что покинул свою планету.", "zh": "此刻，他首次为离开自己的星球感到悔恨。", "t": [71150, 75650]}, {"ru": "Но он сумел взять себя в руки.", "zh": "他终于控制住了自己。", "t": [75650, 78600]}, {"ru": "— Какие места вы мне посоветуете посетить?", "zh": "您觉得我该去哪些地方看看？", "t": [78600, 81962]}, {"ru": "— спросил он географа.", "zh": "他问地理学家。", "t": [81962, 84600]}, {"ru": "— Планету Земля, — ответил тот.", "zh": "那回答道：“地球。”", "t": [84600, 87662]}, {"ru": "— У нее неплохая репутация…", "zh": "她享有不错的声誉…", "t": [87662, 90675]}, {"ru": "И маленький принц снова пустился в путь, думая о своем покинутом цветке.", "zh": "小王子再次踏上旅程，心中想着他留下的花朵。", "t": [90675, 95000]}]}]}, {"id": "ch16", "title_ru": "Глава 16", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"ru": "Так, по совету географа, седьмой планетой, которую посетил маленький принц, стала Земля.", "zh": "于是，在地理学家的建议下，小王子访问的第七颗星球成了地球。", "t": [100, 6550]}, {"ru": "Эта планета совсем особенная.", "zh": "这颗星球颇为特别。", "t": [6550, 9712]}, {"ru": "На ней живут сто одиннадцать королей, не считая королей африканских, семь тысяч географов, девятьсот тысяч бизнесменов, семь с половиной миллионов пьяниц, триста одиннадцать миллионов честолюбцев и около двух миллиардов взрослых.", "zh": "这颗星球上居住着百一十一位国王（不包括非洲的国王）、七千位地理学家、九十万位商人、七百五十万位酒鬼、三亿一千一百万位爱慕虚荣的人，也就是说，大约有二十亿个大人。", "t": [9712, 23375]}, {"ru": "Чтобы вы смогли представить, как велика Земля, я скажу, что до изобретения электричества на шести континентах там работала настоящая армия фонарщиков — четыреста шестьдесят две тысячи пятьсот одиннадцать человек!", "zh": "为了让你想象地球的广阔，我得告诉你，在电发明之前，六大洲曾有一支由四十六万二千五百一十一个点灯人组成的庞大军队！", "t": [23375, 35750]}, {"ru": "Со стороны их действия смотрелись великолепно.", "zh": "他们的动作远看颇为壮观。", "t": [35750, 39438]}, {"ru": "Согласованное движение армии фонарщиков напоминало балет.", "zh": "点灯人队伍的步伐协调一致，宛如芭蕾舞者的舞步。", "t": [39438, 43938]}, {"ru": "Сначала свое дело начинали фонарщики Новой Зеландии и Австралии.", "zh": "新西兰和澳大利亚的点灯人率先开始他们的工作。", "t": [43938, 48812]}, {"ru": "Засветив свои фонари, они уходили спать.", "zh": "点亮了他们的灯笼，便去安睡。", "t": [48812, 52588]}, {"ru": "Потом приступали к работе фонарщики Китая и Сибири.", "zh": "接着，中国和西伯利亚的点灯人开始工作。", "t": [52588, 56600]}, {"ru": "Затем они также скрывались за кулисами.", "zh": "随后，他们也隐于幕后。", "t": [56600, 60075]}, {"ru": "Тогда наступала очередь фонарщиков России и Индии, затем — Африки и Европы.", "zh": "接着是俄罗斯和印度的点灯人，然后是非洲和欧洲的。", "t": [60075, 66412]}, {"ru": "Им на смену появлялись фонарщики Южной и Северной Америки.", "zh": "南美洲和北美洲的点灯人接替了他们。", "t": [66412, 71038]}, {"ru": "Порядок этого величественного парада никогда не нарушался.", "zh": "这场盛大的阅兵从未混乱。", "t": [71038, 75112]}, {"ru": "Это было грандиозное зрелище!", "zh": "这是一场壮观的景象！", "t": [75112, 77912]}, {"ru": "Лишь фонарщик на Северном полюсе и его собрат на Южном вели неспешную, праздную жизнь.", "zh": "北极点灯人和他的南极兄弟过着悠闲而欢快的日子。", "t": [77912, 83925]}, {"ru": "Каждый зажигал и гасил свой единственный фонарь только один раз в год.", "zh": "他们每年只点亮熄灭那唯一的灯笼一次。", "t": [83925, 87962]}]}]}, {"id": "ch17", "title_ru": "Глава 17", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"ru": "Когда хочешь сострить, приходится порой и приврать.", "zh": "有时想卖弄风头，不免要撒个小谎。", "t": [100, 4175]}, {"ru": "Рассказывая о фонарщиках Земли, я не был до конца честен.", "zh": "讲述地球上的点灯人时，我并未完全坦诚。", "t": [4175, 8888]}, {"ru": "И у того, кто не видел эту планету, может создаться о ней неправильное представление.", "zh": "对那个未曾见过这颗星球的人来说，可能会形成对其的错误印象。", "t": [8888, 14738]}, {"ru": "На самом деле люди на ней занимают очень мало места.", "zh": "地球上的人类所占的空间实在微不足道。", "t": [14738, 17912]}]}, {"id": "ch17p01", "audio": true, "sents": [{"ru": "Если бы два миллиарда жителей Земли собрались вместе как на митинг, они легко разместились бы на площади длиной и шириной в двадцать миль.", "zh": "若地球上的二十亿居民齐聚一堂，便能轻易地安置于二十英里长、二十英里宽的广场之上。", "t": [100, 8200]}, {"ru": "Все население мира легко поместилось бы на каком-нибудь островке Тихого океана.", "zh": "整个世界的人口都能轻易地安置在太平洋的一个小岛上。", "t": [8200, 13538]}, {"ru": "Взрослые, конечно, в это не поверят.", "zh": "当然，大人们是不会相信的。", "t": [13538, 17188]}, {"ru": "Они воображают, что занимают очень много места.", "zh": "他们自以为占据了极大的空间。", "t": [17188, 21388]}, {"ru": "Они кажутся себе большими и важными, как баобабы.", "zh": "他们自以为像猴面包树那样高大而重要。", "t": [21388, 25612]}, {"ru": "Поэтому посоветуйте сделать им эти прикидки.", "zh": "因此，请你们劝他们做这些估算。", "t": [25612, 29138]}, {"ru": "Они обожают цифры, им это понравится.", "zh": "他们喜欢数字，这会让他们高兴的。", "t": [29138, 32725]}, {"ru": "Но сами вы лучше не тратьте время на эту занудную и бесполезную работу.", "zh": "但你们自己可别浪费在这枯燥无益的劳作上。", "t": [32725, 37612]}, {"ru": "Вы же мне доверяете?", "zh": "您难道不相信我吗？", "t": [37612, 39912]}, {"ru": "Оказавшись на Земле, маленький принц был весьма удивлен.", "zh": "小王子抵达地球，颇感惊奇。", "t": [39912, 44300]}, {"ru": "Он никого не увидел и уже побоялся, что ошибся планетой.", "zh": "他没见到任何人，已害怕自己误闯了别的星球。", "t": [44300, 48800]}, {"ru": "И тут на песке шевельнулось кольцо бледно-лунного цвета.", "zh": "月白色圆环在沙地上微微颤动。", "t": [48800, 52962]}, {"ru": "— Добрый вечер, — сказал на всякий случай маленький принц.", "zh": "“晚上好，”小王子随口说道。", "t": [52962, 57238]}, {"ru": "— Добрый вечер, — сказала змея.", "zh": "“晚上好，”蛇说。", "t": [57238, 60275]}, {"ru": "— На какую планету я попал?", "zh": "我来到了哪个星球？", "t": [60275, 62888]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [62888, 65512]}, {"ru": "— На Землю.", "zh": "来到了地球", "t": [65512, 67300]}, {"ru": "Ты в Африке, — ответила змея.", "zh": "你来到了非洲，蛇回答说。", "t": [67300, 70238]}, {"ru": "— А!", "zh": "哦！", "t": [70238, 71500]}, {"ru": "Так на Земле никто не живет?", "zh": "地球上无人居住吗？", "t": [71500, 74162]}, {"ru": "— Ты в пустыне.", "zh": "你在沙漠中。", "t": [74162, 76062]}, {"ru": "В пустынях никто не живет.", "zh": "沙漠中无人居住。", "t": [76062, 78800]}, {"ru": "Земля большая, — ответила змея.", "zh": "地球辽阔无垠，蛇回答说。", "t": [78800, 81962]}, {"ru": "Маленький принц присел на камень и поднял глаза к небу.", "zh": "小王子坐在一块石头上，仰望天空。", "t": [81962, 86075]}, {"ru": "— Интересно, — сказал он, — звезды светятся, чтобы каждый мог когда-нибудь найти свою?", "zh": "星星为何闪烁，是为了让每个人都能找到属于自己的那颗星吗？", "t": [86075, 91962]}, {"ru": "Посмотри на", "zh": "仰望", "t": [91962, 92838]}]}, {"id": "ch17p02", "audio": true, "sents": [{"ru": "мою планету.", "zh": "我的星球", "t": [100, 2150]}, {"ru": "Она сейчас точно над нами.", "zh": "它此刻正悬于我们头顶。", "t": [2150, 4938]}, {"ru": "Но она так далеко!", "zh": "它如此遥远！", "t": [4938, 7200]}, {"ru": "— Она красивая, — сказала змея.", "zh": "她真美。", "t": [7200, 10150]}, {"ru": "— Зачем ты прилетел сюда?", "zh": "你为何飞至此地？", "t": [10150, 12712]}, {"ru": "— У меня проблемы с одним цветком, — ответил маленький принц.", "zh": "我有一朵花让我头疼。", "t": [12712, 17038]}, {"ru": "— Понятно, — сказала змея.", "zh": "“明白了，”蛇说。", "t": [17038, 19800]}, {"ru": "— А где все люди?", "zh": "地球上的人都去哪儿了？", "t": [19800, 21838]}, {"ru": "— продолжил разговор маленький принц после минутного молчания.", "zh": "小王子沉默片刻后，继续谈话。", "t": [21838, 26362]}, {"ru": "— Здесь, в пустыне, довольно одиноко.", "zh": "在这沙漠中，颇为孤寂。", "t": [26362, 30088]}, {"ru": "— Среди людей тоже бывает одиноко, — ответила змея.", "zh": "沙漠中，蛇答道，人也会感到孤独。", "t": [30088, 34125]}, {"ru": "Маленький принц внимательно на нее посмотрел.", "zh": "小王子凝视着她。", "t": [34125, 37662]}, {"ru": "— Ты забавная, — сказал он наконец.", "zh": "你真有趣，他终于说道。", "t": [37662, 40812]}, {"ru": "— Такая тонкая…", "zh": "如此纤弱…", "t": [40812, 43062]}, {"ru": "Как палец.", "zh": "像一根指头。", "t": [43062, 44900]}, {"ru": "— Я могу быть более могущественной, чем перст короля, — заметила змея.", "zh": "蛇说：“我可以比国王的指头更有力量。”", "t": [44900, 49900]}, {"ru": "Маленький принц улыбнулся: — Ты не могущественная.", "zh": "小王子微笑着说：“你并不强大。”", "t": [49900, 53925]}, {"ru": "У тебя ведь даже нет лап, и ты не можешь путешествовать.", "zh": "你连脚都没有，也无法旅行。", "t": [53925, 58150]}, {"ru": "— Однако я могу унести тебя дальше любого корабля, — сказала змея.", "zh": "然而，我能带你走得更远，蛇说。", "t": [58150, 62862]}, {"ru": "И она обвилась вокруг ноги маленького принца, словно золотой браслет.", "zh": "它绕着小王子的脚踝盘旋，宛如一条金镯。", "t": [62862, 67912]}, {"ru": "— Тот, кого я касаюсь, возвращается в землю, откуда и вышел, — добавила она.", "zh": "我所触及之人，便会回归其来处。", "t": [67912, 73812]}, {"ru": "— Но ты чист, ведь ты прибыл со звезды.", "zh": "但你纯洁，你是从星星上来的。", "t": [73812, 77050]}, {"ru": "На это маленький принц ничего не ответил.", "zh": "小王子并未作答。", "t": [77050, 79488]}]}, {"id": "ch17p03", "audio": true, "sents": [{"ru": "— Мне тебя жаль, — продолжила змея.", "zh": "我同情你，蛇继续说道。", "t": [100, 3188]}, {"ru": "Ты ведь так слаб на этой каменной Земле.", "zh": "在这坚硬的地球上，你如此脆弱。", "t": [3188, 6388]}, {"ru": "Возможно, однажды я смогу тебе помочь, если ты пожалеешь, что покинул свою планету.", "zh": "或许，有朝一日我能助你一臂之力，若你为离开自己的星球而感到惋惜。", "t": [6388, 12775]}, {"ru": "Я могла бы…", "zh": "我本可以…", "t": [12775, 13912]}, {"ru": "— Я понял тебя, — ответил маленький принц.", "zh": "我明白了，小王子答道。", "t": [13912, 17150]}, {"ru": "— Но почему ты все время говоришь загадками?", "zh": "你为何总是说些谜语？", "t": [17150, 20662]}, {"ru": "— Я все их решаю, — ответила змея, и оба замолкли.", "zh": "——我全都能解决，蛇回答道，两人都沉默了。", "t": [20662, 24275]}]}]}, {"id": "ch18", "title_ru": "Глава 18", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"ru": "Маленький принц пересек пустыню и по дороге встретил лишь один цветок.", "zh": "小王子穿越沙漠，途中只邂逅了一朵花。", "t": [100, 5088]}, {"ru": "У него было всего три лепестка, и он был совершенно невзрачный.", "zh": "那朵花只有三片花瓣，模样十分平常。", "t": [5088, 9588]}, {"ru": "— Привет, — сказал маленький принц.", "zh": "你好，小王子说。", "t": [9588, 12738]}, {"ru": "— Привет, — ответил цветок.", "zh": "你好，花儿答道。", "t": [12738, 15638]}, {"ru": "— А где все люди?", "zh": "人们都在哪里？", "t": [15638, 17675]}, {"ru": "— деликатно поинтересовался маленький принц.", "zh": "小王子礼貌地询问。", "t": [17675, 21138]}, {"ru": "Цветок однажды видел, как мимо проходил караван.", "zh": "花儿曾目睹一队商队路过。", "t": [21138, 25138]}, {"ru": "— Люди?", "zh": "人们？", "t": [25138, 26700]}, {"ru": "Думаю, их шесть или семь.", "zh": "我想，他们大概有六七个。", "t": [26700, 29775]}, {"ru": "Я видел их много лет назад.", "zh": "多年前我曾见过他们。", "t": [29775, 32612]}, {"ru": "Никогда не знаешь, где их искать.", "zh": "你永远不知道该在哪里寻找他们。", "t": [32612, 35862]}, {"ru": "Их носит ветер.", "zh": "风把他们吹散了。", "t": [35862, 37975]}, {"ru": "У них ведь нет корней, и это мешает…", "zh": "他们没有根，这让他们备受困扰。", "t": [37975, 40525]}, {"ru": "— Прощай, — сказал маленький принц.", "zh": "再见，小王子说。", "t": [40525, 43412]}, {"ru": "— Прощай, — ответил цветок.", "zh": "再见，花儿答道。", "t": [43412, 45326]}]}]}, {"id": "ch19", "title_ru": "Глава 19", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"ru": "Маленький принц поднялся на высокую гору.", "zh": "小王子攀登上一座高峰。", "t": [100, 3562]}, {"ru": "Единственными горами, которые он видел раньше, были три вулкана на его планете.", "zh": "他此前只见过自己星球上的三座火山。", "t": [3562, 9112]}, {"ru": "Они были совсем невысокими — едва доходили ему до колена, и он использовал потухший вулкан как табуретку.", "zh": "它们极矮，仅到他膝盖，他便把一座死火山当成了凳子。", "t": [9112, 15838]}, {"ru": "Поэтому", "zh": "因此", "t": [15838, 16626]}]}, {"id": "ch19p01", "audio": true, "sents": [{"ru": "маленький принц подумал, что с такой высокой горы, как эта, он сможет окинуть взором сразу всю планету и всех живущих на ней людей.", "zh": "小王子心想，从这么高的山峰，他便能一眼望尽整个星球及上面所有居住的人。", "t": [100, 8675]}, {"ru": "Однако он не увидел ничего, кроме остро заточенных скал.", "zh": "然而，他只见到了锋利如锥的峭壁。", "t": [8675, 13150]}, {"ru": "— Привет, — сказал он на всякий случай.", "zh": "“你好，随便说说。”", "t": [13150, 16600]}, {"ru": "— Привет, привет, привет, — ответило эхо.", "zh": "你好，你好，你好——回声答道。", "t": [16600, 20662]}, {"ru": "— Кто вы?", "zh": "你是谁？", "t": [20662, 22262]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [22262, 24875]}, {"ru": "— Кто вы, кто вы, кто вы?", "zh": "你是谁，你是谁，你是谁？", "t": [24875, 27825]}, {"ru": "— спросило эхо.", "zh": "回声询问。", "t": [27825, 30125]}, {"ru": "— Будь моим другом, — предложил маленький принц, — я одинок.", "zh": "“成为我的朋友吧，我很孤独……”小王子提议。", "t": [30125, 34812]}, {"ru": "— Я одинок, я одинок, я одинок, — повторило эхо.", "zh": "我孤独，我孤独，我孤独，回声应和。", "t": [34812, 39688]}, {"ru": "«Какая это чудная планета, — подумал маленький принц, — такая сухая, заостренная и просоленная.", "zh": "多么奇特的星球啊——小王子心想，又干又尖，还带着咸味。", "t": [39688, 46712]}, {"ru": "А людям не хватает воображения.", "zh": "人们缺乏想象力。", "t": [46712, 49912]}, {"ru": "Они просто повторяют, что им говорят.", "zh": "他们只是重复别人告诉他们的。", "t": [49912, 53275]}, {"ru": "А у меня на планете был цветок, моя красавица, и она всегда заговаривала со мной первой».", "zh": "在我星球上，有一朵花，我的美人儿，她总是先同我搭话。", "t": [53275, 58474]}]}]}, {"id": "ch20", "title_ru": "Глава 20", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"ru": "Так случилось, что маленький принц, пройдя через пески, миновав скалы и снега, набрел, наконец, на дорогу.", "zh": "小王子穿越沙漠、绕过山岩和雪地，终于踏上了道路。", "t": [100, 8162]}, {"ru": "А все дороги ведут к людям.", "zh": "每一条路都通往人间。", "t": [8162, 10862]}, {"ru": "— Здравствуйте, — сказал маленький принц.", "zh": "您好，小王子说。", "t": [10862, 14338]}, {"ru": "Ведь перед ним был сад с цветущими розами.", "zh": "原来前方是一片盛开的玫瑰园。", "t": [14338, 17000]}]}, {"id": "ch20p01", "audio": true, "sents": [{"ru": "— Здравствуйте, — сказали розы.", "zh": "“你好，玫瑰们说。”", "t": [100, 3088]}, {"ru": "Маленький принц посмотрел на них, и они ему показались очень похожими на его цветок.", "zh": "小王子瞧了瞧她们，觉得她们都像他自己的那朵花。", "t": [3088, 8888]}, {"ru": "— Кто вы?", "zh": "你们是何人？", "t": [8888, 10475]}, {"ru": "— спросил он, пораженный этим зрелищем.", "zh": "他惊异地问道。", "t": [10475, 14212]}, {"ru": "— Мы розы, — ответили розы.", "zh": "我们是玫瑰。", "t": [14212, 17025]}, {"ru": "— Вот как?", "zh": "这倒是！", "t": [17025, 18788]}, {"ru": "— сказал маленький принц…", "zh": "小王子说…", "t": [18788, 21312]}, {"ru": "Он почувствовал себя несчастным.", "zh": "他感到无比悲伤。", "t": [21312, 24162]}, {"ru": "Ведь его цветок говорил ему, что он единственный в своем роде на целом свете.", "zh": "他的花曾告诉他，他是世间独一无二的存在。", "t": [24162, 29350]}, {"ru": "А тут, всего в одном саду, их было не меньше пяти тысяч!", "zh": "在这座花园里，竟有不下五千朵！", "t": [29350, 33075]}]}, {"id": "ch20p02", "audio": true, "sents": [{"ru": "«Если бы моя красавица это увидела, — подумал маленький принц, — ее бы это очень расстроило.", "zh": "如果我的美人儿看到了这些，她会非常伤心的。", "t": [100, 6312]}, {"ru": "И чтобы не показаться смешной, она наверняка бы долго кашляла и прикинулась умирающей.", "zh": "她定会装作咳嗽不止，佯装垂死，以免显得可笑。", "t": [6312, 12262]}, {"ru": "А я бы делал вид, что ухаживаю за ней.", "zh": "我装作在呵护她。", "t": [12262, 15862]}, {"ru": "Иначе, чтобы мне досадить, она могла бы решиться умереть на самом деле».", "zh": "她或许真的会寻死，以示对我的羞辱。", "t": [15862, 21338]}, {"ru": "Потом он добавил про себя: «Я чувствовал себя богачом, обладавшим уникальным цветком, а на самом деле у меня обычная роза.", "zh": "我原以为自己是拥有独花之宝的富翁，实则不过拥有一朵凡花。", "t": [21338, 29050]}, {"ru": "Она да три вулкана, из которых к тому же один потух, и возможно навсегда, — это маловато для настоящего принца».", "zh": "她加上三座火山，其中一座已经熄灭，或许永远不会再喷发——这对一个真正的王子来说未免太少了吧。", "t": [29050, 36475]}, {"ru": "И, бросившись на траву, он заплакал.", "zh": "他扑倒在草地上，失声痛哭。", "t": [36475, 39213]}]}]}, {"id": "ch21", "title_ru": "Глава 21", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"ru": "В это время появился лис.", "zh": "这时，出现了一只狐狸。", "t": [100, 2700]}, {"ru": "— Привет, — сказал он.", "zh": "你好，他说。", "t": [2700, 5212]}, {"ru": "— Привет, — вежливо ответил маленький принц.", "zh": "你好，小王子礼貌地回答。", "t": [5212, 8900]}, {"ru": "Однако, обернувшись, он никого не заметил.", "zh": "然而，他转身时并未察觉到任何人。", "t": [8900, 12700]}, {"ru": "— Я здесь, — раздался голос, — под яблоней.", "zh": "“我在苹果树下，”那声音响起。", "t": [12700, 16700]}, {"ru": "— Ты кто?", "zh": "你是谁？", "t": [16700, 18300]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [18300, 20938]}, {"ru": "— Ты красивый…", "zh": "你真美……", "t": [20938, 22088]}, {"ru": "— Я лис, — ответил лис.", "zh": "“我是狐狸，”狐狸回答。", "t": [22088, 24625]}, {"ru": "— Ты не хочешь поиграть со мной?", "zh": "你不想和我一起玩吗？", "t": [24625, 27325]}, {"ru": "— предложил маленький принц.", "zh": "小王子提议。", "t": [27325, 29950]}, {"ru": "— Мне так грустно…", "zh": "我如此忧伤……", "t": [29950, 31438]}, {"ru": "— Я не могу играть с тобой, — ответил лис.", "zh": "我不能和你一起玩，狐狸回答。", "t": [31438, 34475]}, {"ru": "— Я не приручен.", "zh": "我尚未被驯养。", "t": [34475, 36538]}, {"ru": "— А…", "zh": "可是……", "t": [36538, 37788]}, {"ru": "Ну, извини, — сказал маленький принц.", "zh": "哦，对不起，小王子说。", "t": [37788, 41375]}, {"ru": "Однако, подумав, он добавил: — А что значит «приручать»?", "zh": "然而，他沉思片刻，又问：“驯养究竟是什么意思？”", "t": [41375, 45262]}]}, {"id": "ch21p01", "audio": true, "sents": [{"ru": "— Я вижу, ты не отсюда, — ответил лис.", "zh": "我看出，你不是本地人。", "t": [100, 3512]}, {"ru": "— Что ты тут ищешь?", "zh": "你在寻找什么？", "t": [3512, 5750]}, {"ru": "— Я ищу людей, — сказал маленький принц.", "zh": "小王子说：“我在寻找人类。”", "t": [5750, 9238]}, {"ru": "— Так что значит «приручать»?", "zh": "驯养究竟是什么意思？", "t": [9238, 12300]}, {"ru": "— Люди, — ответил лис, — у них есть ружья, и они охотятся.", "zh": "人们啊，狐狸回答，他们有枪，他们打猎。", "t": [12300, 17288]}, {"ru": "Это очень неудобно.", "zh": "这很不方便。", "t": [17288, 19800]}, {"ru": "А еще они разводят кур.", "zh": "人们还养鸡。", "t": [19800, 22338]}, {"ru": "Это все, что их волнует.", "zh": "这，就是他们所关心的。", "t": [22338, 25212]}, {"ru": "Ты ищешь кур?", "zh": "你在寻找鸡吗？", "t": [25212, 27188]}, {"ru": "— Нет, — ответил маленький принц.", "zh": "“不，”小王子回答。", "t": [27188, 30300]}, {"ru": "— Я ищу друзей.", "zh": "我在寻找朋友。", "t": [30300, 32525]}, {"ru": "Так что значит «приручать»?", "zh": "驯养究竟是什么意思？", "t": [32525, 35612]}, {"ru": "— Это давно позабытое дело, — ответил лис.", "zh": "这是件久被遗忘的事情。", "t": [35612, 39162]}, {"ru": "— Это значит создавать привязанности.", "zh": "这便是建立联系。", "t": [39162, 42250]}, {"ru": "— Создавать привязанности?", "zh": "建立联系？", "t": [42250, 44762]}, {"ru": "— Именно, — сказал лис.", "zh": "“没错，”狐狸说。", "t": [44762, 47450]}, {"ru": "— Ты для меня пока всего лишь маленький мальчик, похожий на сто тысяч других маленьких мальчиков.", "zh": "你对我来说，目前不过是一个和成千上万其他小男孩无异的男孩。", "t": [47450, 53625]}, {"ru": "И ты во мне не нуждаешься.", "zh": "你对我并无需求。", "t": [53625, 56162]}, {"ru": "Для тебя я — лис, похожий на сто тысяч других лисов.", "zh": "对你而言，我只是一只狐狸，和其他成千上万的狐狸并无两样。", "t": [56162, 60662]}, {"ru": "Но если ты меня приручишь, мы будем нужны друг другу.", "zh": "但若你驯养了我，我们便互相需要。", "t": [60662, 64712]}, {"ru": "Ты станешь для меня единственным в мире, а я буду единственным для тебя.", "zh": "你将成为我唯一的，而我将成为你唯一的。", "t": [64712, 69712]}, {"ru": "— Кажется, я начинаю понимать, — сказал маленький принц.", "zh": "我有点明白了，小王子说。", "t": [69712, 74075]}, {"ru": "— У меня есть цветок, моя красавица…", "zh": "我有一朵花，我的美人儿……", "t": [74075, 77612]}, {"ru": "Мне кажется, она меня приручила.", "zh": "我觉得，她驯养了我。", "t": [77612, 80850]}, {"ru": "— Это возможно, — ответил лис.", "zh": "这是可能的，狐狸回答。", "t": [80850, 83725]}, {"ru": "— На Земле всякое случается…", "zh": "地球上什么都会发生…", "t": [83725, 85750]}, {"ru": "— Это случилось не на Земле, — сказал маленький принц.", "zh": "这并非发生在地球上，小王子说。", "t": [85750, 89375]}, {"ru": "Лис был чрезвычайно удивлен: — На другой планете?", "zh": "狐狸大吃一惊：“在另一个星球上？”", "t": [89375, 93312]}, {"ru": "— Да.", "zh": "是的。", "t": [93312, 93750]}]}, {"id": "ch21p02", "audio": true, "sents": [{"ru": "— А там есть охотники?", "zh": "那里有猎人吗？", "t": [100, 2562]}, {"ru": "— Нет.", "zh": "没有。", "t": [2562, 4075]}, {"ru": "— А куры?", "zh": "鸡吗？", "t": [4075, 5738]}, {"ru": "— Нет.", "zh": "没有。", "t": [5738, 7262]}, {"ru": "— Нет в мире совершенства, — вздохнул лис.", "zh": "世间无完美，狐狸叹了口气。", "t": [7262, 10912]}, {"ru": "Однако он вернулся к прежней теме: — Видишь ли, моя жизнь довольно однообразна.", "zh": "然而，他又扯回原先的话题：“你看，我的生活相当单调。”", "t": [10912, 16300]}, {"ru": "Я охочусь за курами, а охотники охотятся за мной.", "zh": "我追逐鸡，猎人追逐我。", "t": [16300, 20488]}, {"ru": "Все куры одинаковы, и все люди похожи друг на друга.", "zh": "鸡皆相似，人亦如此。", "t": [20488, 24800]}, {"ru": "Поэтому мне немного скучно.", "zh": "因此，我有些无聊。", "t": [24800, 27512]}, {"ru": "Однако, если ты меня приручишь, мою жизнь словно озарит солнечный свет.", "zh": "然而，若你驯养了我，我的生命便如阳光般熠熠生辉。", "t": [27512, 33025]}, {"ru": "Я буду узнавать звук твоих шагов, они для меня будут отличаться от всех прочих.", "zh": "我将学会分辨你的脚步声，它们对我来说将与众不同。", "t": [33025, 38838]}, {"ru": "От прочих шагов я ныряю под землю, а твои будут меня выманивать из моего логова.", "zh": "你的脚步声将把我从洞穴中引诱出来。", "t": [38838, 44350]}, {"ru": "Они будут звучать для меня, как музыка.", "zh": "它们对我来说，就像音乐一样。", "t": [44350, 47688]}, {"ru": "И потом, взгляни!", "zh": "然后，你看！", "t": [47688, 50062]}, {"ru": "Видишь там поля пшеницы?", "zh": "你看见那片麦田了吗？", "t": [50062, 52738]}, {"ru": "Я не ем хлеб.", "zh": "我不吃面包。", "t": [52738, 54925]}, {"ru": "Пшеница мне ни к чему.", "zh": "麦子对我毫无意义。", "t": [54925, 57450]}, {"ru": "И поля пшеницы", "zh": "麦田", "t": [57450, 58762]}]}, {"id": "ch21p03", "audio": true, "sents": [{"ru": "ничего мне не напоминают, что довольно грустно.", "zh": "这让我感到有些凄凉。", "t": [100, 3938]}, {"ru": "Но у тебя золотистые волосы.", "zh": "你的头发是金色的。", "t": [3938, 6838]}, {"ru": "Представляешь, как будет славно, когда ты меня приручишь?", "zh": "想象一下，当你驯养了我，那该有多么美好。", "t": [6838, 11125]}, {"ru": "Золотистая пшеница станет мне напоминать о тебе.", "zh": "金色的麦子将使我联想到你。", "t": [11125, 14875]}, {"ru": "И я полюблю, как она шелестит на ветру…", "zh": "我将会爱上她随风摇曳的声音……", "t": [14875, 18312]}, {"ru": "Лис замолчал и посмотрел на маленького принца долгим взглядом: — Ну, пожалуйста, приручи меня!", "zh": "狐狸沉默了，久久地凝视着小王子，然后说：“求你了，驯养我吧！”", "t": [18312, 24625]}, {"ru": "— Я бы и рад, — ответил маленький принц.", "zh": "小王子答道：“我也愿意。”", "t": [24625, 28138]}, {"ru": "— Но у меня мало времени.", "zh": "时间不多。", "t": [28138, 30675]}, {"ru": "Мне нужно найти друзей и так много еще узнать.", "zh": "我要寻找朋友，还有许多事要了解。", "t": [30675, 34425]}, {"ru": "— По-настоящему узнаешь только те вещи, которые приручаешь, — ответил лис.", "zh": "真正了解的，唯有你驯养的事物。", "t": [34425, 39738]}, {"ru": "— У людей больше нет времени ничего узнавать как следует.", "zh": "人们再没时间真正了解什么了。", "t": [39738, 43788]}, {"ru": "Торговцы продают им готовые вещи.", "zh": "商人向他们出售现成之物。", "t": [43788, 46875]}, {"ru": "Однако нет торговцев, предлагающих друзей.", "zh": "然而，没有商人出售朋友。", "t": [46875, 50725]}, {"ru": "Поэтому у людей их нет.", "zh": "因此，人们没有。", "t": [50725, 53512]}, {"ru": "Если ты хочешь завести друга, приручи меня!", "zh": "若你愿与我结为朋友，就驯养我吧！", "t": [53512, 57012]}, {"ru": "— А что для этого надо делать?", "zh": "你需要做些什么呢？", "t": [57012, 59612]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [59612, 62225]}, {"ru": "— Надо быть очень терпеливым, — ответил лис.", "zh": "需要极大的耐心，狐狸回答。", "t": [62225, 65812]}, {"ru": "— Сначала ты сядешь вот так в траву немного поодаль от меня.", "zh": "你先这样坐在草地上，离我远一点。", "t": [65812, 70038]}, {"ru": "Я буду смотреть на тебя искоса, а ты будешь молчать.", "zh": "我斜眼窥视着你，你则缄默不语。", "t": [70038, 74250]}, {"ru": "Ведь язык — источник всех недоразумений.", "zh": "语言是误会的根源。", "t": [74250, 78062]}, {"ru": "Однако с каждым днем ты сможешь садиться немного ближе…", "zh": "然而，你每天可以坐得稍近一点……", "t": [78062, 82200]}, {"ru": "На следующий день маленький принц пришел на встречу с лисом снова.", "zh": "小王子第二天再次来到狐狸面前。", "t": [82200, 86675]}, {"ru": "— Будет лучше, — сказал тот, — если ты станешь возвращаться в одно и то же время.", "zh": "你最好每天按时来。", "t": [86675, 92188]}]}, {"id": "ch21p04", "audio": true, "sents": [{"ru": "Если ты, к примеру, будешь появляться в четыре часа дня, начиная с трех я уже буду счастлив.", "zh": "如果你是下午四点钟来，从三点钟开始，我就开始感到幸福了。", "t": [100, 5162]}, {"ru": "И чем ближе будет время встречи, тем счастливее я буду становиться.", "zh": "随着相聚时间的临近，我愈发感到幸福。", "t": [5162, 10012]}, {"ru": "А ровно в четыре я начну волноваться и тревожиться.", "zh": "四点钟，我便开始焦虑不安。", "t": [10012, 13975]}, {"ru": "Так я открою для себя цену счастья!", "zh": "于是，我才领悟到幸福的真谛。", "t": [13975, 17238]}, {"ru": "Но если ты станешь появляться в разное время, я не буду знать, когда мне готовиться к радости встречи…", "zh": "但若你出现的时间不定，我便不知何时预备迎接这份喜悦。", "t": [17238, 23500]}, {"ru": "Нужны обряды…", "zh": "需要仪式…", "t": [23500, 24850]}, {"ru": "— Что такое «обряд»?", "zh": "仪式是什么？", "t": [24850, 27612]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [27612, 30250]}, {"ru": "— Это давно позабытая вещь, — ответил лис.", "zh": "这是件久被遗忘的事情。", "t": [30250, 33925]}, {"ru": "— Это то, что отличает один день от другого или делает какой-нибудь час особенным.", "zh": "这，就是区分一日与另一日的，或是赋予某个时刻特殊意义的东西。", "t": [33925, 39488]}, {"ru": "Например, у моих охотников есть один обряд.", "zh": "例如，我的猎人有一个仪式。", "t": [39488, 43312]}, {"ru": "По четвергам они танцуют с девушками из деревни.", "zh": "每逢星期四，他们与村里的姑娘们跳舞。", "t": [43312, 47012]}, {"ru": "И поэтому четверг для них — день чудесный.", "zh": "对他们来说，星期四是个奇妙的日子。", "t": [47012, 50775]}, {"ru": "А я могу в это время прогуляться до самых виноградников.", "zh": "我可以在此时漫步至葡萄园。", "t": [50775, 54712]}, {"ru": "Если бы охотники танцевали, когда им вздумается, все дни были бы одинаковыми, и я не смог бы устраивать себе маленький праздник.", "zh": "如果猎人想跳舞就跳舞，那么每一天都会变得相同，我就无法为自己安排一个小小的节日了。", "t": [54712, 62788]}, {"ru": "В конце концов, маленькому принцу удалось приручить лиса, но когда настал час их прощания, лис вздохнул: — Без тебя я буду плакать.", "zh": "终于，小王子驯服了狐狸，但分别时刻到来时，狐狸叹了口气说：“没有你，我会哭泣。”", "t": [62788, 71288]}, {"ru": "— Сам виноват, — заметил маленький принц.", "zh": "小王子自责地说：“都是我自己的错。”", "t": [71288, 74912]}, {"ru": "— Я не хотел причинить тебе боль.", "zh": "我不想让你受伤。", "t": [74912, 77700]}, {"ru": "Ты же сам захотел, чтобы я тебя приручил.", "zh": "你自愿让我驯养你。", "t": [77700, 81112]}, {"ru": "— Это верно, — сказал лис.", "zh": "“没错，”狐狸说。", "t": [81112, 83850]}, {"ru": "— Но ты будешь плакать!", "zh": "你将会哭泣！", "t": [83850, 86300]}, {"ru": "— Конечно, — вздохнул лис.", "zh": "狐狸叹了口气。", "t": [86300, 89188]}, {"ru": "— Так что же ты получил в результате?", "zh": "你得到了什么结果？", "t": [89188, 91163]}]}, {"id": "ch21p05", "audio": true, "sents": [{"ru": "—Теперь мне о многом говорит цвет пшеницы…", "zh": "小麦的颜色让我对许多事情有了新的认识。", "t": [100, 3662]}, {"ru": "Потом лис добавил: — Пойди, взгляни еще раз на розы, и теперь ты поймешь, что твоя роза — единственная в мире.", "zh": "然后狐狸补充道：“去再看一眼你的玫瑰，那时你就会明白，你的玫瑰是世界上独一无二的。”", "t": [3662, 11025]}, {"ru": "А когда ты придешь попрощаться со мной, я открою тебе один секрет.", "zh": "当你来与我告别时，我会向你揭示一个秘密。", "t": [11025, 15925]}, {"ru": "И маленький принц пошел взглянуть на розы.", "zh": "小王子走去看看玫瑰。", "t": [15925, 19312]}, {"ru": "— Вы совсем не похожи на мою розу, — сказал он им.", "zh": "您一点也不像我的玫瑰，他说。", "t": [19312, 22062]}, {"ru": "— Вы совершенно не она.", "zh": "她根本不是那样的人。", "t": [22062, 24275]}, {"ru": "Вас еще никто не приручил, и вы никого не приручили.", "zh": "你们都尚未被驯养，也未驯养过任何人。", "t": [24275, 28350]}, {"ru": "Вы такие, каким был мой лис.", "zh": "你们就像我的狐狸曾经是的那样。", "t": [28350, 31338]}, {"ru": "Он был похож на сто тысяч других лисов. Но", "zh": "他像成千上万的狐狸一样。", "t": [31338, 35300]}]}, {"id": "ch21p06", "audio": true, "sents": [{"ru": "он стал моим другом, и теперь он для меня единственный в мире.", "zh": "他成了我的朋友，现在他是世界上独一无二的。", "t": [100, 4412]}, {"ru": "Казалось, розы были смущены его словами.", "zh": "玫瑰似乎被他这话弄得很不自在。", "t": [4412, 8112]}, {"ru": "— Вы красивы, — добавил маленький принц, — но пусты.", "zh": "你很美，但很空虚。", "t": [8112, 12288]}, {"ru": "Ради вас не захочется умирать.", "zh": "为了你，连死都不愿意。", "t": [12288, 15238]}, {"ru": "Конечно, моя роза…", "zh": "当然，我的玫瑰…", "t": [15238, 17650]}, {"ru": "Случайный прохожий сказал бы, что она похожа на вас.", "zh": "路人或许会说，她与您颇为相似。", "t": [17650, 21688]}, {"ru": "Но для меня она важнее вас всех.", "zh": "她对我来说比你们所有人都重要。", "t": [21688, 24712]}, {"ru": "Ведь я поливал ее и помещал под стеклянный колпак.", "zh": "我给她浇水，还为她罩上玻璃罩。", "t": [24712, 28812]}, {"ru": "Именно ее я прикрывал ширмой и именно с нее я сгонял гусениц, за исключением двух или трех — чтобы они превратились в бабочек.", "zh": "我给她罩上花罩，还为她赶走毛虫，除了两三条，好让它们变成蝴蝶。", "t": [28812, 37175]}, {"ru": "Я слушал ее жалобы и бахвальство.", "zh": "我倾听她的抱怨与自夸。", "t": [37175, 40412]}, {"ru": "Я даже слушал, как она молчит.", "zh": "我甚至倾听她的沉默。", "t": [40412, 43575]}, {"ru": "Ведь это моя роза!", "zh": "这毕竟是我的玫瑰。", "t": [43575, 45800]}, {"ru": "Потом он вернулся к лису.", "zh": "然后他回到狐狸身边。", "t": [45800, 48325]}, {"ru": "— Прощай, — сказал он ему.", "zh": "再见，他说。", "t": [48325, 51175]}, {"ru": "— Прощай, — ответил лис.", "zh": "再见，狐狸回答。", "t": [51175, 53712]}, {"ru": "— Вот мой секрет.", "zh": "这就是我的秘密。", "t": [53712, 55938]}, {"ru": "Он очень прост.", "zh": "他非常简单。", "t": [55938, 58100]}, {"ru": "Проницательно только сердце.", "zh": "心灵方能洞察。", "t": [58100, 60838]}, {"ru": "Самое главное скрыто от глаз.", "zh": "最本质的隐藏在肉眼之外。", "t": [60838, 63912]}, {"ru": "— Главное скрыто от глаз, — повторил маленький принц, чтобы лучше запомнить.", "zh": "最重要的隐藏在肉眼之外，小王子重复道，以便更好地记住。", "t": [63912, 69325]}, {"ru": "— Именно время, которое ты потратил на твою розу, делает ее для тебя такой значительной.", "zh": "你为你的玫瑰所花费的时间，让她在你眼中变得如此重要。", "t": [69325, 74975]}, {"ru": "— Время, которое я потратил на свою розу…— повторил маленький принц, чтобы лучше запомнить.", "zh": "小王子重复道，为了更好地记住：我为我的玫瑰所花费的时间……", "t": [74975, 81288]}, {"ru": "— Люди забыли эту истину, — сказал лис.", "zh": "人们忘记了这条真理，狐狸说。", "t": [81288, 84975]}, {"ru": "— Но ты не должен ее забывать.", "zh": "但你不可忘记她。", "t": [84975, 87738]}, {"ru": "Ты навсегда в ответе за всех, кого приручил.", "zh": "你将永远对你所驯养的一切负责。", "t": [87738, 91400]}, {"ru": "И ты в ответе за твою розу.", "zh": "你将对你那朵玫瑰负责。", "t": [91400, 94012]}, {"ru": "— Я в ответе за свою розу, — повторил маленький принц, чтобы лучше запомнить.", "zh": "我将对我的玫瑰负责，小王子重复道，以便更好地记住。", "t": [94012, 98474]}]}]}, {"id": "ch22", "title_ru": "Глава 22", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"ru": "— Здравствуй, — сказал маленький принц.", "zh": "你好，小王子说。", "t": [100, 3250]}, {"ru": "— Здравствуй, — ответил стрелочник.", "zh": "你好，扳道工答道。", "t": [3250, 6425]}, {"ru": "— Что ты здесь делаешь?", "zh": "你在做什么？", "t": [6425, 8688]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [8688, 11312]}, {"ru": "— Я сортирую пассажиров, целыми тысячами, — ответил стрелочник.", "zh": "我给乘客们分批次，整千整千地，扳道工答道。", "t": [11312, 16375]}, {"ru": "— Я отправляю поезда, которые их увозят — то направо, то налево.", "zh": "我调度列车，它们时而向右，时而向左驶去。", "t": [16375, 21388]}, {"ru": "В это время мимо задрожавшей будки стрелочника прогромыхал скорый поезд с ярко освещенными окнами.", "zh": "这时，一列灯火通明的快车轰隆隆地驶过颤抖的扳道工小屋。", "t": [21388, 28025]}, {"ru": "— Они очень спешат, — сказал маленький принц.", "zh": "他们匆匆忙忙，小王子说。", "t": [28025, 31825]}, {"ru": "— Что они ищут?", "zh": "他们在寻找什么？", "t": [31825, 34050]}, {"ru": "— Этого не знает даже машинист локомотива, — ответил стрелочник.", "zh": "连火车头上的司机也不知道他们要寻找什么。", "t": [34050, 38825]}, {"ru": "В это время освещенный скорый поезд прогрохотал в обратном направлении.", "zh": "这时，一列灯火通明的快车逆向轰鸣而过。", "t": [38825, 43650]}, {"ru": "— Они уже возвращаются?", "zh": "他们已经回来了？", "t": [43650, 46162]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [46162, 48800]}, {"ru": "— Нет, это другие, — ответил стрелочник.", "zh": "——不，那是另外一些人，扳道工答道。", "t": [48800, 52438]}, {"ru": "— Встречный поезд.", "zh": "对开的火车", "t": [52438, 54712]}, {"ru": "— Им не понравилось там, где они были?", "zh": "他们不满足于他们所在的地方。", "t": [54712, 58000]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [58000, 60625]}, {"ru": "— Они всегда всем недовольны, — ответил стрелочник.", "zh": "他们总是对什么都不满意。", "t": [60625, 64612]}, {"ru": "Мимо прогремел третий освещенный скоростной состав.", "zh": "又一辆灯火通明的快车呼啸而过。", "t": [64612, 68575]}, {"ru": "— А эти хотят догнать первых пассажиров?", "zh": "他们想追上第一批乘客吗？", "t": [68575, 71850]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [71850, 73638]}]}, {"id": "ch22p01", "audio": true, "sents": [{"ru": "— Они их не преследуют, — ответил стрелочник.", "zh": "他们并不追赶他们，扳道工答道。", "t": [100, 3912]}, {"ru": "— Внутри они спят или зевают.", "zh": "他们在车厢里昏昏欲睡或哈欠连连。", "t": [3912, 6962]}, {"ru": "Только дети прижимают носы к стеклам.", "zh": "孩子们将鼻尖贴在玻璃上。", "t": [6962, 10112]}, {"ru": "— Только дети знают, чего они ищут, — заметил маленький принц.", "zh": "只有孩子懂得他们在寻找什么，小王子说道。", "t": [10112, 15012]}, {"ru": "— Они тратят свое время на тряпичную куклу, и она становится очень важной для них.", "zh": "他们把时间花在布娃娃身上，对她来说变得无比重要。", "t": [15012, 20712]}, {"ru": "Если ее у них отнимут, они плачут.", "zh": "若有人夺走她，他们会哭泣。", "t": [20712, 24188]}, {"ru": "— Хорошо им, — ответил стрелочник.", "zh": "——他们好着呢，扳道工答道。", "t": [24188, 26562]}]}]}, {"id": "ch23", "title_ru": "Глава 23", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"ru": "— Здравствуй, — сказал маленький принц.", "zh": "你好，小王子说。", "t": [100, 3275]}, {"ru": "— Здравствуй, — ответил торговец.", "zh": "你好，商人答道。", "t": [3275, 6188]}, {"ru": "Это был торговец усовершенствованными пилюлями, которые утоляли жажду.", "zh": "这是贩卖改良药丸的商人，那种药丸能解渴。", "t": [6188, 11500]}, {"ru": "Проглотишь такую пилюлю, и целую неделю можно не пить.", "zh": "吞下一颗这样的药丸，整整一周都不用喝水。", "t": [11500, 15875]}, {"ru": "— Зачем ты их продаешь?", "zh": "你为何售卖它们？", "t": [15875, 18325]}, {"ru": "— спросил маленький принц.", "zh": "小王子问道。", "t": [18325, 20962]}, {"ru": "— От них большая экономия времени, — ответил торговец.", "zh": "——这些能节省大量时间，商人答道。", "t": [20962, 25262]}, {"ru": "— Специалисты подсчитали — пятьдесят три минуты в неделю.", "zh": "专家们算过——每周能节省五十三分钟。", "t": [25262, 29362]}, {"ru": "— И что с этими пятьюдесятью тремя минутами делают?", "zh": "这些节省下来的五十三分钟，他们怎么使用呢？", "t": [29362, 33262]}, {"ru": "— Делают, что хотят.", "zh": "他们做他们愿意做的事。", "t": [33262, 35850]}, {"ru": "«Если бы у меня было лишних пятьдесят три минуты, — подумал про себя маленький принц, — я бы неспешно прогулялся к роднику…»", "zh": "若我有那多余的五十三分钟，小王子心想，我会悠然漫步至那泉边……", "t": [35850, 42275]}]}]}, {"id": "ch24", "title_ru": "Глава 24", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"ru": "С момента моей аварии в пустыне прошло уже восемь дней.", "zh": "自我的飞机在沙漠失事以来，已有八日。", "t": [100, 4288]}, {"ru": "Слушая историю про торговца, я допил последние капли моего запаса воды.", "zh": "倾听商人的故事，我饮尽了最后一滴储备之水。", "t": [4288, 9325]}, {"ru": "— Твои истории очень забавны, — сказал я маленькому принцу, — но я все еще не починил свой самолет, вода у меня закончилась, и я тоже был бы счастлив, если бы мог неспешно прогуляться к роднику.", "zh": "你的故事很有趣，——我对小王子说，——但我仍没修好我的飞机，水也喝完了，若能悠然漫步至泉边，我也会感到幸福。", "t": [9325, 20425]}, {"ru": "— Мой друг лис как-то сказал мне…", "zh": "我的朋友狐狸曾对我说…", "t": [20425, 22475]}, {"ru": "— Дружок мой, речь теперь не о лисе!", "zh": "我的朋友，现在不是谈论狐狸的时候！", "t": [22475, 25300]}, {"ru": "— Почему?", "zh": "为什么？", "t": [25300, 26912]}, {"ru": "— Потому что мне придется умереть от жажды.", "zh": "因为我会因渴死而亡。", "t": [26912, 30162]}, {"ru": "Кажется, он меня не понял, потому что ответил: — Хорошо иметь друга, даже если умрешь.", "zh": "他似乎没听懂，因为他回答道：“有朋友真好，哪怕死的时候。”", "t": [30162, 35925]}, {"ru": "Например, я очень рад, что у меня был друг лис.", "zh": "我很高兴，我曾有过一位狐狸朋友。", "t": [35925, 40025]}, {"ru": "«Он не может по-настоящему оценить опасность, — подумал я.", "zh": "他无法真正估量危险的严重。", "t": [40025, 43788]}, {"ru": "— Ведь он никогда не испытывал ни голода, ни жажды.", "zh": "他从未尝过饥饿与干渴的滋味。", "t": [43788, 47200]}, {"ru": "Ему довольно лишь солнечных лучей…»", "zh": "他只需一点阳光便心满意足。", "t": [47200, 50525]}, {"ru": "Однако маленький принц, взглянув на меня, кажется, понял мои мысли.", "zh": "然而，小王子望着我，似乎看穿了我的心思。", "t": [50525, 55875]}, {"ru": "— Я тоже хочу пить…", "zh": "我也想喝水…", "t": [55875, 58162]}, {"ru": "Давай поищем колодец.", "zh": "让我们去找一口井。", "t": [58162, 60762]}, {"ru": "Я безнадежно махнул рукой — бессмысленно искать колодец наугад в безбрежной пустыне.", "zh": "我在茫茫沙漠中盲目地挥了挥手——漫无目的地寻找井口，徒劳无功。", "t": [60762, 66650]}, {"ru": "Тем не менее мы пустились в путь.", "zh": "然而，我们还是出发了。", "t": [66650, 69475]}, {"ru": "Мы прошли молча несколько часов.", "zh": "我们默默行走了几个小时。", "t": [69475, 72562]}, {"ru": "Настала ночь, и в небе начали загораться звезды.", "zh": "夜幕降临，星星在天际闪烁。", "t": [72562, 76462]}, {"ru": "Я смотрел на них, как во сне.", "zh": "我仿佛在梦中凝视着它们。", "t": [76462, 79425]}, {"ru": "От жажды меня немного лихорадило.", "zh": "因渴而微烧。", "t": [79425, 82338]}, {"ru": "Слова маленького принца плясали у меня в голове.", "zh": "小王子的话在我脑海中跳跃。", "t": [82338, 85076]}]}, {"id": "ch24p01", "audio": true, "sents": [{"ru": "— Ты хочешь сказать, что тоже испытываешь жажду?", "zh": "你也想喝水吗？", "t": [100, 3888]}, {"ru": "— спросил я его.", "zh": "他问我。", "t": [3888, 6100]}, {"ru": "Он не ответил впрямую на мой вопрос, а лишь заметил: — Вода хороша и для сердца.", "zh": "水对心灵亦有益。", "t": [6100, 11638]}, {"ru": "Я не понял, что он хотел сказать, но промолчал.", "zh": "我不解其意，却缄默不语。", "t": [11638, 15650]}, {"ru": "Я хорошо знал, что не стоит его расспрашивать.", "zh": "我深知不该问他。", "t": [15650, 19338]}, {"ru": "Он казался уставшим.", "zh": "他显得疲惫不堪。", "t": [19338, 21812]}, {"ru": "Маленький принц присел на песок, и я сел рядом с ним.", "zh": "小王子坐在沙地上，我与他并肩而坐。", "t": [21812, 26225]}, {"ru": "Помолчав, он сказал: — Звезды великолепны; ведь где-то там есть цветок, хотя отсюда его и не видно.", "zh": "沉默片刻，他轻声说道：“星星如此璀璨，因为在那遥远之处，有一朵花虽不可见。”", "t": [26225, 33050]}, {"ru": "— Конечно, — ответил я и замолчал, глядя на гребни песка в лунном свете.", "zh": "当然，我回答，沉默着，凝视着月光下的沙丘起伏。", "t": [33050, 38275]}, {"ru": "— Пустыня так прекрасна, — добавил он.", "zh": "沙漠如此美丽，他补充道。", "t": [38275, 41525]}, {"ru": "Это было верно.", "zh": "这倒是真的。", "t": [41525, 43550]}, {"ru": "Мне всегда нравилась пустыня.", "zh": "沙漠，我总爱它。", "t": [43550, 46488]}, {"ru": "Садишься на песчаную дюну.", "zh": "坐在沙丘上。", "t": [46488, 49162]}, {"ru": "Тишина.", "zh": "寂静。", "t": [49162, 50775]}, {"ru": "Никакого движения.", "zh": "寂静无声。", "t": [50775, 53312]}, {"ru": "И что-то мерцает в этой тишине…", "zh": "在这寂静中，有什么东西在闪烁……", "t": [53312, 55362]}, {"ru": "— Пустыня хороша и потому, — сказал маленький принц, — что она где-то скрывает колодец.", "zh": "沙漠之所以美丽，是因为它某处隐藏着一口井。", "t": [55362, 61000]}, {"ru": "Я был удивлен, внезапно поняв про это таинственное мерцание песка.", "zh": "我猛然惊觉，原来那沙漠中的神秘闪烁竟是沙粒。", "t": [61000, 66025]}, {"ru": "Маленьким мальчиком я жил в старинном доме.", "zh": "我曾是古宅中的孩童。", "t": [66025, 69562]}, {"ru": "Легенда рассказывала, что где-то в нем было зарыто сокровище.", "zh": "传说中，那里面埋藏着宝藏。", "t": [69562, 73850]}, {"ru": "Конечно, никто его так и не нашел.", "zh": "当然，无人能找到它。", "t": [73850, 77025]}, {"ru": "А может, его никто и не искал.", "zh": "或许，根本无人去寻找。", "t": [77025, 80188]}, {"ru": "Но оно придавало дому колдовское очарование.", "zh": "它给这栋房子增添了魔法的魅力。", "t": [80188, 84000]}, {"ru": "Дом словно прятал тайну в глубине своего сердца…", "zh": "房子仿佛将秘密深藏于心底…", "t": [84000, 86988]}, {"ru": "— Да, — сказал я маленькому принцу, — когда речь идет о доме, о звездах или о пустыне.", "zh": "是的，我对小王子说，说到房子、星星或沙漠时。", "t": [86988, 92800]}, {"ru": "То, что делает их прекрасными, скрыто от глаз.", "zh": "那使他们变得美好的，肉眼难以窥见。", "t": [92800, 96050]}]}, {"id": "ch24p02", "audio": true, "sents": [{"ru": "— Я рад, — ответил он, — что ты согласен с моим лисом.", "zh": "我很高兴，你赞同我的狐狸。", "t": [100, 4388]}, {"ru": "Маленький принц задремал.", "zh": "小王子渐入梦乡。", "t": [4388, 7100]}, {"ru": "Я взял его на руки и снова отправился в путь.", "zh": "我把他抱在怀里，再次踏上了旅程。", "t": [7100, 10888]}, {"ru": "Я был взволнован.", "zh": "心中涌起波澜。", "t": [10888, 13188]}, {"ru": "Мне казалось, что я несу в руках хрупкое сокровище.", "zh": "我怀中抱着的，是一份易碎的珍宝。", "t": [13188, 17588]}, {"ru": "И мне казалось также, что на всей Земле нет ничего более хрупкого.", "zh": "在这片广袤的土地上，似乎再无任何事物比这更为脆弱。", "t": [17588, 22262]}, {"ru": "Я смотрел при свете луны на его бледный лоб, на его закрытые глаза, на колеблющиеся от ветра пряди волос и говорил себе, что вижу лишь внешность.", "zh": "我凝视着他在月光下苍白的额头、紧闭的双眼和随风飘动的发丝，心中想：“我所看到的，不过是他的外表。”", "t": [22262, 31338]}, {"ru": "Ведь самое важное скрыто от глаз…", "zh": "最宝贵的东西隐藏在肉眼之外…", "t": [31338, 34612]}, {"ru": "Его полуоткрытые губы тронула едва заметная улыбка, и я подумал: «Этот уснувший принц кажется мне таким трогательным, потому что он верен своему цветку.", "zh": "他的嘴唇微微张开，露出一抹不易察觉的微笑，我想：“这个沉睡的小王子如此打动我，因为他对自己那朵花忠贞不渝。”", "t": [34612, 43850]}, {"ru": "Образ его розы светится в нем наподобие пламени свечи, даже когда он спит».", "zh": "他的玫瑰如同烛火般在他心中闪烁，即便在他沉睡之时。", "t": [43850, 49538]}, {"ru": "И я еще раз почувствовал, насколько он хрупок.", "zh": "我再次感受到他是多么脆弱。", "t": [49538, 53350]}, {"ru": "Такое пламя нужно хорошо охранять, ведь его может задуть любой порыв ветра.", "zh": "这束火焰需精心守护，任何微风都可能将其吹灭。", "t": [53350, 58725]}, {"ru": "Я шел так и шел, а на рассвете увидел колодец.", "zh": "我一路前行，直至黎明时分，终于发现了井。", "t": [58725, 61900]}]}]}, {"id": "ch25", "title_ru": "Глава 25", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"ru": "— Люди, — сказал маленький принц, — они забираются в скорые поезда, но они не знают, к чему они стремятся.", "zh": "人们啊，小王子说，他们挤进快车，却不知自己追求何方。", "t": [100, 7150]}, {"ru": "Поэтому они попусту суетятся и бегают по кругу.", "zh": "因此，他们徒然忙碌，团团转。", "t": [7150, 11125]}, {"ru": "Потом он добавил: — В этом нет смысла…", "zh": "这又何苦呢……", "t": [11125, 14388]}, {"ru": "Колодец, до которого мы добрались, не был обычным.", "zh": "这井非同寻常。", "t": [14388, 18650]}, {"ru": "Ведь колодцы Сахары — простые ямы, вырытые в песке.", "zh": "撒哈拉的井不过是沙中挖出的普通坑洞。", "t": [18650, 22925]}, {"ru": "Этот же напоминал деревенский колодец, хотя никакой деревни поблизости не было.", "zh": "这口井仿佛是村中的井，尽管四周并无村落。", "t": [22925, 28362]}, {"ru": "Мне казалось, что я грежу.", "zh": "我觉得我在受苦。", "t": [28362, 31375]}, {"ru": "— Это странно, — сказал я маленькому принцу, — тут все наготове: ворот, ведро и веревка…", "zh": "这真奇怪，我对小王子说，这里一切俱备：辘轳、水桶和绳子……", "t": [31375, 37675]}, {"ru": "В ответ он засмеялся, потянул веревку, и ворот закрутился.", "zh": "他笑了，拉起绳子，辘轳便转动起来。", "t": [37675, 42488]}, {"ru": "При этом ворот застонал, как стонет старый флюгер по давно заснувшему ветру.", "zh": "辘轳呻吟着，宛如沉睡风中的老风信鸡在叹息。", "t": [42488, 47738]}, {"ru": "— Ты слышишь, — сказал маленький принц, — мы пробудили этот колодец, и он запел.", "zh": "我们唤醒了这口井，它唱起了歌。", "t": [47738, 53550]}, {"ru": "Я не хотел, чтобы он утруждал себя.", "zh": "我不愿他如此劳苦。", "t": [53550, 56800]}, {"ru": "— Пусти-ка, — сказал я ему, — тебе эта работа не по силам.", "zh": "让我来帮你吧，这活儿对你来说太重了。", "t": [56800, 61062]}, {"ru": "Я медленно поднял ведро и тяжело опустил его на край колодца.", "zh": "我缓缓提起水桶，沉重地放下井沿。", "t": [61062, 65762]}, {"ru": "В моих ушах все еще раздавалось пение ворота, а на дрожащей поверхности воды играли блики солнца.", "zh": "耳畔回荡着辘轳的歌声，阳光在水波中闪烁。", "t": [65762, 72575]}, {"ru": "— Дай мне испить этой воды, — сказал маленький принц, — дай мне ее.", "zh": "让我喝这水吧，小王子说。", "t": [72575, 76525]}]}, {"id": "ch25p01", "audio": true, "sents": [{"ru": "И я понял, что он искал.", "zh": "我明白了，他是在寻找这个。", "t": [100, 2750]}, {"ru": "Я приподнял ведро до его губ.", "zh": "我举起了水桶至他的唇边。", "t": [2750, 5550]}, {"ru": "Он пил с закрытыми глазами.", "zh": "他闭着眼睛喝水。", "t": [5550, 8275]}, {"ru": "Эта вода была для него праздником.", "zh": "这水对他而言，如同节日。", "t": [8275, 11188]}, {"ru": "Она была совсем другой, не предназначенной для обычного питья.", "zh": "这水并非寻常解渴之用。", "t": [11188, 15762]}, {"ru": "Эта вода родилась под звездами, под пение колодезного ворота, благодаря усилиям моих рук.", "zh": "这水诞生于星光之下，在井辘轳的歌声中，倾注了我双手的汗水。", "t": [15762, 21975]}, {"ru": "Она была приятна для сердца, как подарок.", "zh": "它宛如一份礼物，温暖人心。", "t": [21975, 25525]}, {"ru": "Когда я был маленьким мальчиком, свет рождественской елки, церковная музыка вечерней службы и нежность царящих вокруг улыбок тоже составляли для меня сияющий подарок праздника, который я получал.", "zh": "我年幼时，圣诞树上的灯光、子夜弥撒的乐音，以及周围洋溢的温柔微笑，都成了我节日里熠熠生辉的礼物。", "t": [25525, 37162]}, {"ru": "— Люди здесь у тебя, — сказал маленький принц, — выращивают пять тысяч роз в одном саду и при этом не находят, что ищут…", "zh": "人们啊，小王子说，你们在这园中培育五千朵玫瑰，却不知所寻为何。", "t": [37162, 43962]}, {"ru": "— Не находят, — подтвердил я…", "zh": "他们确实找不到。", "t": [43962, 45912]}, {"ru": "— А ведь все, что они ищут, можно найти в одной розе и в нескольких глотках воды.", "zh": "他们所寻，尽在一朵玫瑰与几口水中。", "t": [45912, 51138]}, {"ru": "— Конечно, — согласился я.", "zh": "当然，我同意。", "t": [51138, 52650]}, {"ru": "А маленький принц добавил: — Их глаза слепы.", "zh": "小王子补充道：“他们的眼睛是盲的。”", "t": [52650, 56162]}, {"ru": "Надо искать сердцем.", "zh": "用心去寻找。", "t": [56162, 58575]}, {"ru": "Я вдоволь напился.", "zh": "畅饮一饱。", "t": [58575, 60938]}, {"ru": "На рассвете дышалось легко.", "zh": "拂晓呼吸轻快。", "t": [60938, 63600]}, {"ru": "Песок был медового цвета.", "zh": "沙子泛着蜜色。", "t": [63600, 66325]}, {"ru": "Его оттенки радовали меня.", "zh": "他的色彩令我愉悦。", "t": [66325, 69062]}, {"ru": "Мне не о чем было больше тревожиться и грустить.", "zh": "我无需再忧虑和忧伤。", "t": [69062, 72750]}, {"ru": "— Ты ведь сдержишь свое обещание?", "zh": "你难道不守诺言吗？", "t": [72750, 75925]}, {"ru": "— спросил маленький принц, сев рядом со мной.", "zh": "小王子坐在我身边，问道。", "t": [75925, 79762]}, {"ru": "— Какое обещание?", "zh": "你难道不守诺言吗？", "t": [79762, 82262]}, {"ru": "— Ты знаешь… намордник для моего барашка.", "zh": "你知道……给我那只小羊画个口罩。", "t": [82262, 85825]}, {"ru": "Я ведь в ответе за мой цветок.", "zh": "我必须对我的玫瑰花负责。", "t": [85825, 87825]}]}, {"id": "ch25p02", "audio": true, "sents": [{"ru": "Я вынул из кармана мои наброски.", "zh": "我从口袋里掏出草图。", "t": [100, 3112]}, {"ru": "Взглянув на них, маленький принц рассмеялся.", "zh": "小王子看着他们，笑了。", "t": [3112, 7112]}, {"ru": "— Твои баобабы похожи на цветную капусту…", "zh": "你的猴面包树像彩色的卷心菜。", "t": [7112, 9862]}, {"ru": "— Вот как?", "zh": "这倒是！", "t": [9862, 10574]}]}, {"id": "ch25p03", "audio": true, "sents": [{"ru": "А я был так горд своими баобабами…", "zh": "我为我的猴面包树感到自豪。", "t": [100, 2400]}, {"ru": "— Твой лис… его уши… они немного похожи на оленьи рога — слишком длинные.", "zh": "你的狐狸……它的耳朵……有点像鹿角——太长了。", "t": [2400, 8112]}, {"ru": "И он снова рассмеялся.", "zh": "他又笑了。", "t": [8112, 10638]}, {"ru": "— Ты несправедлив ко мне, дружок.", "zh": "你对我太不公平了，朋友。", "t": [10638, 13575]}, {"ru": "Я ведь вообще ничего не умел рисовать, кроме удавов — снаружи и изнутри.", "zh": "我只懂得画蛇——外面和里面。", "t": [13575, 19050]}, {"ru": "— А…", "zh": "很不错的嘛，孩子们看得懂的。", "t": [19050, 20300]}, {"ru": "Тогда сгодится.", "zh": "那时正好。", "t": [20300, 22525]}, {"ru": "Дети поймут, — ответил маленький принц.", "zh": "孩子们会理解的——小王子回答道。", "t": [22525, 26038]}, {"ru": "Я взял карандаш и нарисовал намордник.", "zh": "我拿起铅笔，为他们画了一个口罩。", "t": [26038, 29462]}, {"ru": "Но когда я протянул ему рисунок, мое сердце дрогнуло: — Что ты собираешься делать?", "zh": "当我递给他草图，我的心颤抖了：你打算做什么？", "t": [29462, 34962]}, {"ru": "Ты мне не говорил…", "zh": "你从未对我说过…", "t": [34962, 36950]}, {"ru": "На это маленький принц ничего не ответил.", "zh": "小王子并未作答。", "t": [36950, 40250]}, {"ru": "Он лишь сказал: — Ты знаешь… завтра ровно год, как я упал на Землю….", "zh": "他只是说：“你知道……我降落在这地球上的日子，明天刚好满一年了。”", "t": [40250, 45525]}, {"ru": "Он замолк, а потом добавил: — Это случилось неподалеку отсюда.", "zh": "这发生在此地附近。", "t": [45525, 50075]}, {"ru": "При этом он покраснел.", "zh": "他的脸又红了。", "t": [50075, 52375]}, {"ru": "У меня защемило сердце, хотя я и не понимал почему.", "zh": "心口一阵剧痛，尽管我并不明白缘由。", "t": [52375, 56625]}, {"ru": "В голове у меня возник единственный вопрос: — Так значит утром, восемь дней назад, когда я увидел тебя впервые, ты оказался здесь не случайно?", "zh": "那么，八天前，当我第一次见到你的时候，你到这里来并非偶然？", "t": [56625, 65275]}, {"ru": "Совсем один, за тысячу миль от человеческого жилья!", "zh": "孤身一人，远离人烟千余里！", "t": [65275, 69362]}, {"ru": "Ты возвращался к месту своего падения?", "zh": "你回到坠机地点了吗？", "t": [69362, 72800]}, {"ru": "Маленький принц снова покраснел.", "zh": "小王子又红了脸。", "t": [72800, 75762]}, {"ru": "А я добавил нерешительно: — В связи с этой годовщиной?", "zh": "我犹豫着补充道：“关于这个周年纪念？”", "t": [75762, 78800]}]}, {"id": "ch25p04", "audio": true, "sents": [{"ru": "Маленький принц покраснел снова.", "zh": "小王子再次脸红。", "t": [100, 3125]}, {"ru": "Он никогда не отвечал на вопросы, но, ведь когда краснеешь, это означает «да», не так ли?", "zh": "他从不回答问题，但，毕竟，脸红就意味着“是”，不是吗？", "t": [3125, 9538]}, {"ru": "— Вот как?", "zh": "这倒是！", "t": [9538, 11300]}, {"ru": "— сказал я ему.", "zh": "我对他说。", "t": [11300, 13525]}, {"ru": "— Боюсь, что…", "zh": "我担心…", "t": [13525, 15825]}, {"ru": "Но он меня перебил: — Ты должен работать.", "zh": "但他打断了我：你该工作了。", "t": [15825, 19125]}, {"ru": "Отправляйся к своей машине.", "zh": "启程前往你的机器。", "t": [19125, 21875]}, {"ru": "Я подожду тебя здесь.", "zh": "我在此地等你。", "t": [21875, 24288]}, {"ru": "Возвращайся завтра вечером…", "zh": "明天晚上再来……", "t": [24288, 26962]}, {"ru": "От этих слов мне не стало спокойнее.", "zh": "这些话并未让我感到安宁。", "t": [26962, 30312]}, {"ru": "Я вспомнил о лисе.", "zh": "我忆起了那狐狸。", "t": [30312, 32775]}, {"ru": "Рискуешь расплакаться, если дал себя приручить…", "zh": "你若让自己被驯养，难免会掉眼泪……", "t": [32775, 35687]}]}]}, {"id": "ch26", "title_ru": "Глава 26", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"ru": "Рядом с колодцем находились руины старой каменной стены.", "zh": "井边伫立着古老石墙的残垣断壁。", "t": [100, 4350]}, {"ru": "Когда следующим вечером я возвратился после своей работы, еще издали увидел, что маленький принц сидит на ней, свесив ноги вниз.", "zh": "当晚我下班归来，远远望见小王子坐在断壁上，双腿悬空。", "t": [4350, 12750]}, {"ru": "И я услышал, как он сказал кому-то: — Разве ты об этом забыла?", "zh": "他听见他对某人说道：“难道你把这事儿给忘了？”", "t": [12750, 17200]}, {"ru": "Это было не здесь…", "zh": "这不是这里…", "t": [17200, 19300]}, {"ru": "Без сомнения, кто-то ему ответил, потому что он возразил: — Да, нет же!", "zh": "无疑，有人回应了他，因为他反驳道：“不，不是这样！”", "t": [19300, 24525]}, {"ru": "Ровно год назад, но не тут.", "zh": "一年前，但不是这里。", "t": [24525, 27525]}, {"ru": "Я подходил к стене, но по-прежнему никого не видел и не слышал.", "zh": "我走向墙壁，却依旧未见一人，亦未闻其声。", "t": [27525, 32050]}, {"ru": "Однако маленький принц снова ответил: — Ну конечно.", "zh": "当然，小王子又回答道。", "t": [32050, 35938]}, {"ru": "Ты заметишь мои следы на песке.", "zh": "你会在沙地上看到我的脚印。", "t": [35938, 38750]}, {"ru": "Тебе надо будет только меня подождать.", "zh": "你只需等待我。", "t": [38750, 41788]}, {"ru": "Я приду этой ночью…", "zh": "今夜我会来…", "t": [41788, 44350]}, {"ru": "Я был уже в двадцати метрах от стены, но по-прежнему никого не видел.", "zh": "我已离墙二十米，却依旧未见人影。", "t": [44350, 49000]}, {"ru": "А маленький принц, помолчав, спросил: — У тебя хороший яд?", "zh": "小王子沉默片刻后问道：“你有毒药吗？”", "t": [49000, 53850]}, {"ru": "Уверена, что я не буду долго мучиться?", "zh": "我确信自己不会受太多折磨？", "t": [53850, 57238]}, {"ru": "Я остановился, сердце мое сжалось, но я все еще не понимал всего до конца.", "zh": "我心头一紧，但依旧未能完全领会。", "t": [57238, 62638]}, {"ru": "— А теперь уходи, — сказал маленький принц, — я хочу спуститься.", "zh": "小王子说：“现在你走吧，我要跳下去了。”", "t": [62638, 67388]}, {"ru": "Я опустил глаза к основанию стены и отпрянул в сторону.", "zh": "我低头看向墙根，不由得向一旁闪避。", "t": [67388, 71688]}, {"ru": "Внизу к маленькому принцу тянулась желтая змейка.", "zh": "一条黄蛇蜿蜒爬向小王子。", "t": [71688, 75588]}, {"ru": "Такая может убить за полминуты.", "zh": "这种蛇半分钟内就能致命。", "t": [75588, 78525]}]}, {"id": "ch26p01", "audio": true, "sents": [{"ru": "Нашаривая в кармане револьвер, я подался вперед, но, заслышав шум, змейка мягко скользнула по песку и с тихим металлическим звуком исчезла среди камней, словно струйка высыхающей воды.", "zh": "我伸手到口袋里掏手枪，但一听到声响，那条小蛇便轻盈地滑过沙地，带着轻微的金属声消失在石缝间，宛如干涸的水柱。", "t": [100, 11212]}, {"ru": "Я подбежал к стене как раз вовремя, чтобы подхватить на руки моего малыша принца.", "zh": "我及时赶到墙边，抱起了我的小王子。", "t": [11212, 16888]}, {"ru": "Он был бледен, как снег.", "zh": "他的脸色苍白如雪。", "t": [16888, 19650]}, {"ru": "— Что это ты задумал?!", "zh": "你这是想干什么？！", "t": [19650, 21975]}, {"ru": "Зачем ты беседуешь со змеями?", "zh": "你为何与蛇交谈？", "t": [21975, 24938]}, {"ru": "Я развязал его неизменный золотистый шарф.", "zh": "我解下他始终佩戴的金色围巾。", "t": [24938, 28512]}, {"ru": "Я смочил ему виски и дал попить.", "zh": "我给他擦了擦酒，让他喝了一口。", "t": [28512, 31762]}, {"ru": "Я не решался ничего у него спрашивать.", "zh": "我不敢向他问什么。", "t": [31762, 34900]}, {"ru": "Он серьезно посмотрел на меня и обвил мою шею руками.", "zh": "他严肃地望着我，双手环抱住我的脖子。", "t": [34900, 39238]}, {"ru": "Я чувствовал, что его сердце бьется,", "zh": "我感觉到他的心在狂跳。", "t": [39238, 41800]}]}, {"id": "ch26p02", "audio": true, "sents": [{"ru": "как сердце подстреленной из ружья и умирающей птицы.", "zh": "如同中弹濒死的小鸟之心。", "t": [100, 4212]}, {"ru": "И он сказал мне: — Я рад, что ты разобрался со своей машиной.", "zh": "他告诉我：“我很高兴你解决了你的飞机问题。”", "t": [4212, 8750]}, {"ru": "Теперь ты сможешь вернуться домой.", "zh": "现在你能够回家了。", "t": [8750, 11650]}, {"ru": "— Как ты узнал?", "zh": "你如何得知的？", "t": [11650, 13500]}, {"ru": "Я как раз собирался рассказать ему, что вопреки всему я успешно закончил свою работу.", "zh": "我正要告诉他，尽管一切困难，我最终还是完成了我的工作。", "t": [13500, 19362]}, {"ru": "Он ничего не ответил на мой вопрос и лишь сказал: — Сегодня я тоже возвращаюсь к себе домой…", "zh": "他未对我的问题作答，只是说：“今天，我也要回到自己的家了……”", "t": [19362, 25062]}, {"ru": "А потом добавил грустно: — Но это гораздо дальше и гораздо труднее…", "zh": "然而，这却远得多，也难得多……", "t": [25062, 29962]}, {"ru": "Я почувствовал, что происходит что-то необычное.", "zh": "我感觉到，发生了非比寻常的事情。", "t": [29962, 33925]}, {"ru": "Я сжимал его в своих объятиях, как маленького ребенка, и тем не менее мне казалось, что он скользит в какую-то пропасть, а я не в силах его удержать.", "zh": "我紧紧将他抱在怀里，犹如抱起一个孩子，然而却感觉他正滑向一个深渊，而我却无力将他留住。", "t": [33925, 43050]}, {"ru": "Взгляд у него был серьезный, но какой-то потерянный.", "zh": "他的目光严肃，却带着一丝迷茫。", "t": [43050, 47088]}, {"ru": "— У меня есть твой барашек.", "zh": "我有一只你的绵羊。", "t": [47088, 49788]}, {"ru": "И у меня есть твой ящик для него.", "zh": "我有一只为你准备的箱子。", "t": [49788, 52775]}, {"ru": "И у меня есть намордник…", "zh": "我还有口罩……", "t": [52775, 55425]}, {"ru": "При этих словах он печально улыбнулся.", "zh": "他凄凉地笑笑。", "t": [55425, 58762]}, {"ru": "Я долго ждал, чувствуя, как он понемногу приходит в себя.", "zh": "我耐心等待，感觉到他渐渐恢复过来。", "t": [58762, 63338]}, {"ru": "— Малыш, ты боишься…", "zh": "小家伙，你害怕了……", "t": [63338, 65862]}, {"ru": "Конечно, ему было страшно.", "zh": "当然，他害怕了。", "t": [65862, 68688]}, {"ru": "— Сегодня вечером мне будет гораздо страшнее…", "zh": "今晚我会更加害怕…", "t": [68688, 72312]}, {"ru": "Меня снова словно обдало холодом от ощущения надвигающейся непоправимой беды.", "zh": "一股寒意再次袭来，我预感到即将降临的无法挽回的灾难。", "t": [72312, 77738]}, {"ru": "И я понял — мне невыносимо думать, что я больше никогда не услышу его смех.", "zh": "我明白——想到再也听不到他的笑声，我无法忍受。", "t": [77738, 82988]}, {"ru": "Ведь он был для меня словно родник в пустыне.", "zh": "犹如沙漠中的一眼清泉。", "t": [82988, 86475]}, {"ru": "— Малыш, я хочу и дальше слышать твой смех…", "zh": "小家伙，我还想继续听到你的笑声……", "t": [86475, 89326]}]}, {"id": "ch26p03", "audio": true, "sents": [{"ru": "А он мне ответил: — Этой ночью моя звезда будет точно над тем местом, куда я упал ровно год назад…", "zh": "他回答我说：“今夜，我的星星将正好在我一年前坠落的地方上方……”", "t": [100, 5762]}, {"ru": "— Малыш, пожалуйста, скажи мне, ведь вся эта история со змеей и свидание со звездой не более, чем просто дурной сон?", "zh": "这关于蛇和星星的故事，难道不过是一场噩梦吗？", "t": [5762, 12838]}, {"ru": "Он не ответил на мой вопрос и лишь сказал: — То, что важно, скрыто от глаз…", "zh": "那重要的，肉眼难见……", "t": [12838, 17212]}, {"ru": "— Ну, конечно…", "zh": "当然，那又何妨…", "t": [17212, 18412]}, {"ru": "— Это как с цветком.", "zh": "这就像那朵花。", "t": [18412, 20338]}, {"ru": "Если ты любишь цветок, который находится на далекой звезде, ночью приятно смотреть на небо.", "zh": "若你爱上了那颗遥远星辰上的花朵，夜晚仰望星空便格外温馨。", "t": [20338, 26450]}, {"ru": "Все звезды расцветают…", "zh": "所有的星星都绽放了…", "t": [26450, 28150]}, {"ru": "— Ну, конечно…", "zh": "当然，那又何妨…", "t": [28150, 29400]}, {"ru": "— И это как с водой.", "zh": "这就像水一样。", "t": [29400, 31425]}, {"ru": "Та, которую дал мне ты, была как музыка…", "zh": "那，你赠予我的，宛如音乐……", "t": [31425, 35025]}, {"ru": "Ворот и веревка…", "zh": "门闩与绳索…", "t": [35025, 37325]}, {"ru": "Ты помнишь?..", "zh": "你记得吗？", "t": [37325, 39225]}, {"ru": "Она была прекрасна.", "zh": "她美得无与伦比。", "t": [39225, 40613]}]}, {"id": "ch26p04", "audio": true, "sents": [{"ru": "— Конечно…", "zh": "当然…", "t": [100, 1050]}, {"ru": "— Ночью ты будешь смотреть на звезды.", "zh": "今夜，你将仰望星空。", "t": [1050, 3800]}, {"ru": "Мой дом слишком мал, чтобы я тебе показал, где находится моя звезда.", "zh": "我的家太小，无法向你展示我的星星所在之处。", "t": [3800, 8788]}, {"ru": "Но так даже лучше.", "zh": "如此反而更妙。", "t": [8788, 11175]}, {"ru": "Моя будет для тебя лишь одной из них, и ты будешь любоваться всеми.", "zh": "你的，将是我所珍视的一颗，而你将沉醉于所有星辰之中。", "t": [11175, 16012]}, {"ru": "Они все будут твоими друзьями.", "zh": "它们都将成为你的朋友。", "t": [16012, 18912]}, {"ru": "И потом, я сделаю тебе подарок…", "zh": "然后，我将送你一份礼物……", "t": [18912, 22088]}, {"ru": "И маленький принц снова рассмеялся.", "zh": "小王子再次笑了。", "t": [22088, 25250]}, {"ru": "— Ах, малыш, малыш!", "zh": "啊，小家伙，小家伙！", "t": [25250, 28225]}, {"ru": "Мне нравится слушать твой смех.", "zh": "我喜欢听你的笑声。", "t": [28225, 31175]}, {"ru": "— Это и будет моим подарком… как с водой…", "zh": "这便是我赠予你的礼物……如同水一般…", "t": [31175, 34038]}, {"ru": "— Что ты хочешь этим сказать?", "zh": "你想说什么？", "t": [34038, 36425]}, {"ru": "— У каждого человека свои звезды.", "zh": "每个人都有自己的星星。", "t": [36425, 39362]}, {"ru": "Для тех, кто путешествует, они путеводные.", "zh": "对旅行者而言，它们是向导。", "t": [39362, 43400]}, {"ru": "Для прочих они лишь маленькие огоньки.", "zh": "对别人来说，它们只是小小的火光。", "t": [43400, 46900]}, {"ru": "Для других, ученых, они являются загадками.", "zh": "对学者而言，它们是谜团。", "t": [46900, 51200]}, {"ru": "Для моего бизнесмена они были из золота.", "zh": "对那位商人来说，它们是金子。", "t": [51200, 54775]}, {"ru": "Но все звезды молчат.", "zh": "但星星都沉默着。", "t": [54775, 57312]}, {"ru": "У тебя же будут звезды, которых нет ни у кого больше.", "zh": "你的星星，无人能及。", "t": [57312, 61388]}, {"ru": "— Что ты хочешь этим сказать?", "zh": "你想表达什么意思？", "t": [61388, 64088]}, {"ru": "— Ночью ты будешь смотреть на небо, и, поскольку я буду жить на одной из звезд и буду смеяться на одной из них, тебе будет казаться, что все они смеются для тебя.", "zh": "夜里，你仰望星空，因为我会住在其中一颗星星上，并在那里笑，你会觉得所有的星星都在为你而笑。", "t": [64088, 73562]}, {"ru": "У тебя будут звезды, которые умеют смеяться!", "zh": "你将拥有会笑的星星。", "t": [73562, 77362]}, {"ru": "И он снова залился смехом.", "zh": "他又笑了起来。", "t": [77362, 80112]}, {"ru": "— А когда ты утешишься, — ведь всегда утешаются, — ты будешь рад, что знал меня.", "zh": "当你的心得到慰藉，毕竟人总是自我安慰，你会为曾认识我而感到高兴。", "t": [80112, 85725]}, {"ru": "Ты всегда будешь оставаться моим другом.", "zh": "你将永远是我的朋友。", "t": [85725, 88962]}, {"ru": "Ты будешь смеяться вместе со мной.", "zh": "你将与我一同欢笑。", "t": [88962, 91975]}, {"ru": "И твои друзья будут удивляться, отчего ты смеешься, глядя в небо.", "zh": "你的朋友们会惊讶，为何你仰望星空而笑。", "t": [91975, 96875]}]}, {"id": "ch26p05", "audio": true, "sents": [{"ru": "А ты им ответишь, что звезды всегда заставляют тебя смеяться.", "zh": "你将告诉他们，星星总是让你笑。", "t": [100, 3075]}, {"ru": "И они подумают, что ты слегка тронулся.", "zh": "他们或许会以为你有些失常。", "t": [3075, 6550]}, {"ru": "Да, я сыграю с тобой забавную шутку…", "zh": "是的，我要和你开个玩笑……", "t": [6550, 9912]}, {"ru": "И маленький принц опять рассмеялся.", "zh": "小王子又笑了。", "t": [9912, 13212]}, {"ru": "— Похоже на то, как если бы я дал тебе вместо звезд целую кучу бубенчиков, которые умеют смеяться.", "zh": "仿佛我给了你一整堆会笑的小铃铛。", "t": [13212, 19975]}, {"ru": "Он расхохотался, а потом снова стал серьезным.", "zh": "他大笑，随即又变得严肃。", "t": [19975, 23938]}, {"ru": "— Этой ночью… знаешь… ты лучше не приходи.", "zh": "今夜……你知道……你最好不要来。", "t": [23938, 28050]}, {"ru": "— Я тебя не оставлю.", "zh": "我不会离开你。", "t": [28050, 30338]}, {"ru": "— Тебе будет казаться, что мне очень плохо.", "zh": "你似乎觉得我非常不好。", "t": [30338, 33712]}, {"ru": "У меня будет такой вид, словно я умираю.", "zh": "我看起来就像是要死去一般。", "t": [33712, 37488]}, {"ru": "Так уж бывает…Тебе не надо это видеть, не стоит…", "zh": "如此而已……你不必看，不必在意……", "t": [37488, 40862]}, {"ru": "— Я тебя не оставлю.", "zh": "我不会离开你。", "t": [40862, 42862]}, {"ru": "Маленький принц казался всерьез обеспокоенным.", "zh": "小王子似乎非常担忧。", "t": [42862, 46712]}, {"ru": "— Я тебе это говорю… из-за змеи…", "zh": "我之所以这样说，是因为那条蛇……", "t": [46712, 50038]}, {"ru": "Вдруг она укусит и тебя.", "zh": "它若咬你，也未可知。", "t": [50038, 52875]}, {"ru": "Змеи… они злые.", "zh": "蛇……它们是恶毒的。", "t": [52875, 55612]}, {"ru": "Могут укусить ведь и просто так… без причины…", "zh": "或许它们也会无缘无故地咬人……", "t": [55612, 58800]}, {"ru": "— Я тебя не оставлю!", "zh": "我不会离开你。", "t": [58800, 60738]}, {"ru": "Однако что-то его успокоило.", "zh": "然而，某种东西让他平静了下来。", "t": [60738, 63525]}, {"ru": "— Впрочем, верно!", "zh": "不过，确实如此！", "t": [63525, 65788]}, {"ru": "У нее просто не хватит яда для второго укуса…", "zh": "她的毒液不足以再次咬人。", "t": [65788, 69488]}, {"ru": "Этой ночью я не видел, как он ушел.", "zh": "今夜我没看见他离去。", "t": [69488, 72588]}, {"ru": "Он исчез незаметно.", "zh": "他悄然离去。", "t": [72588, 75000]}, {"ru": "Когда мне удалось его догнать, он быстро и решительно шел вперед.", "zh": "当他追上我时，他迅速而坚定地向前走去。", "t": [75000, 79738]}, {"ru": "Увидав меня, он лишь сказал: — А… ты здесь…", "zh": "遇见我，他只说：“啊……你在这儿……”", "t": [79738, 83775]}, {"ru": "Все еще полный тревоги, он взял меня за руку.", "zh": "依然充满忧虑，他紧紧握住我的手。", "t": [83775, 87575]}, {"ru": "— Зря это ты…Тебе будет тяжело это видеть.", "zh": "你看到这会很难过。", "t": [87575, 91338]}, {"ru": "Я буду выглядеть мертвым, но это не совсем так…", "zh": "我将看起来像死了一样，但并非全然如此……", "t": [91338, 95175]}, {"ru": "Я молчал.", "zh": "我沉默着。", "t": [95175, 96188]}]}, {"id": "ch26p06", "audio": true, "sents": [{"ru": "— Пойми — мой дом слишком далеко для этого тела.", "zh": "我的家对这副躯壳来说太遥远了。", "t": [100, 3738]}, {"ru": "Оно слишком тяжелое, мне его не унести…", "zh": "这副躯壳太沉重，我无法带走……", "t": [3738, 7188]}, {"ru": "Я молчал.", "zh": "我缄默不语。", "t": [7188, 9100]}, {"ru": "— Это будет похоже на старую сброшенную оболочку.", "zh": "这就像脱落的旧壳。", "t": [9100, 13012]}, {"ru": "Старые оболочки покидать не грустно…", "zh": "脱下旧壳，并不哀伤…", "t": [13012, 16325]}, {"ru": "Я молчал.", "zh": "我缄默不语。", "t": [16325, 18238]}, {"ru": "Он немного пал духом, но все же сделал еще одну попытку.", "zh": "他精神略有颓唐，但仍尝试了一次。", "t": [18238, 22488]}, {"ru": "— Знаешь, это будет славно!", "zh": "这会很美好！", "t": [22488, 25400]}, {"ru": "Я тоже буду смотреть на звезды.", "zh": "我也会仰望星空。", "t": [25400, 28312]}, {"ru": "И все они будут словно колодцы с проржавелыми вóротами.", "zh": "它们都像生锈的井口。", "t": [28312, 32388]}, {"ru": "И все звезды дадут мне напиться.", "zh": "所有的星星都将让我解渴。", "t": [32388, 35450]}, {"ru": "Я молчал.", "zh": "我沉默着。", "t": [35450, 37362]}, {"ru": "— Это будет так забавно!", "zh": "这会很有趣！", "t": [37362, 39838]}, {"ru": "У тебя будет пятьсот миллионов бубенцов, а у меня — пятьсот миллионов источников.", "zh": "你将拥有五亿个小铃铛，而我则有五亿个源泉。", "t": [39838, 45575]}, {"ru": "И он тоже замолчал, потому что заплакал.", "zh": "他沉默了，因为哭泣。", "t": [45575, 48050]}]}, {"id": "ch26p07", "audio": true, "sents": [{"ru": "— Это здесь.", "zh": "这里。", "t": [100, 1888]}, {"ru": "Позволь мне сделать последний шаг одному.", "zh": "让我独自完成这最后一步。", "t": [1888, 5162]}, {"ru": "Он присел на песок.", "zh": "他坐在沙地上。", "t": [5162, 7525]}, {"ru": "Ему было страшно.", "zh": "他害怕了。", "t": [7525, 9875]}, {"ru": "Потом он добавил: — Ты знаешь… мой цветок… моя красавица…", "zh": "然后他又说：“你知道……我的花……我的美人儿……”", "t": [9875, 14825]}, {"ru": "Она такая слабая, такая наивная!", "zh": "她如此柔弱，如此天真。", "t": [14825, 18325]}, {"ru": "У нее всего четыре шипа для защиты от всего мира…", "zh": "她仅有四根刺来抵御整个世界的侵袭…", "t": [18325, 22362]}, {"ru": "Я сел на песок.", "zh": "我坐在沙地上。", "t": [22362, 24700]}, {"ru": "Ноги меня не держали.", "zh": "我的双腿无力支撑。", "t": [24700, 27088]}, {"ru": "— Ну, вот и все…", "zh": "如此，便结束了。", "t": [27088, 29238]}, {"ru": "Он немного помедлил, потом поднялся и сделал шаг вперед.", "zh": "他稍作迟疑，然后站起身，向前迈了一步。", "t": [29238, 33700]}, {"ru": "У меня не было сил шевельнуться.", "zh": "我动弹不得。", "t": [33700, 36612]}, {"ru": "И я заметил маленькую желтую молнию, промелькнувшую у его ноги.", "zh": "我注意到他脚边闪过一道小小的黄色闪电。", "t": [36612, 41688]}, {"ru": "Секунду он стоял неподвижно, а потом беззвучно и медленно, как срубленное дерево, опустился на песок, скрывший звук его падения.", "zh": "他瞬间僵立，随后无声无息、缓慢地，如同被砍伐的树木，跌落在沙地上，掩盖了落地的声音。", "t": [41688, 49663]}]}]}, {"id": "ch27", "title_ru": "Глава 27", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"ru": "С тех пор прошло уже шесть лет.", "zh": "自那以后，已过去了六年。", "t": [100, 3175]}, {"ru": "Я еще никому не рассказывал эту историю.", "zh": "我从未向任何人提起过这个故事。", "t": [3175, 6700]}, {"ru": "Мои знакомые, увидав меня вновь, были рады, что я жив и здоров.", "zh": "我的熟人见到我安然无恙，都为我感到高兴。", "t": [6700, 12100]}, {"ru": "А я грустил, но говорил им, что просто устал.", "zh": "我虽感忧伤，却对他们说只是疲乏所致。", "t": [12100, 15900]}, {"ru": "Теперь я успокоился.", "zh": "如今我已平静下来。", "t": [15900, 18325]}, {"ru": "Ну, конечно, не совсем…", "zh": "当然，并非全然…", "t": [18325, 21200]}, {"ru": "Я уверен, что он вернулся на свою планету.", "zh": "他确信自己已回到自己的星球。", "t": [21200, 24812]}, {"ru": "Ведь в то утро, на рассвете, я не нашел его тела.", "zh": "那日破晓，我没有找到他的遗体。", "t": [24812, 28738]}, {"ru": "Возможно, оно было не таким уж и тяжелым…", "zh": "或许，它并不那么沉重…", "t": [28738, 32312]}, {"ru": "Теперь я люблю по ночам слушать звезды.", "zh": "今夜，我偏爱倾听星星的低语。", "t": [32312, 35488]}, {"ru": "Они звенят для меня, как пятьсот миллионов бубенцов.", "zh": "它们在我耳中，如同五亿个铜铃在鸣响。", "t": [35488, 39738]}, {"ru": "Но вот что удивительно.", "zh": "然而，这却令人称奇。", "t": [39738, 42262]}, {"ru": "Я нарисовал намордник и отдал этот рисунок маленькому принцу.", "zh": "我为小王子画了口罩，并将这幅画送给了他。", "t": [42262, 47100]}, {"ru": "Однако я забыл пририсовать к наморднику кожаный ремешок.", "zh": "然而，我忘了给口罩加上皮带头带。", "t": [47100, 51362]}, {"ru": "Как же он сможет тогда надеть намордник на барашка?", "zh": "他怎么给羊儿戴上口罩呢？", "t": [51362, 55062]}, {"ru": "Поэтому я порой волнуюсь — как он там, на своей планете?", "zh": "因此，我时常担心——他在自己的星球上怎么样了？", "t": [55062, 59488]}, {"ru": "Быть может, барашек все-таки съел цветок?", "zh": "或许，那只绵羊终究是吃了那朵花？", "t": [59488, 63138]}, {"ru": "Но тогда я успокаиваю себя — конечно же, нет!", "zh": "当然，这不会发生！", "t": [63138, 67138]}, {"ru": "Ведь каждую ночь маленький принц накрывает свой цветок стеклянным колпаком и внимательно следит за своим барашком.", "zh": "小王子每晚都会用玻璃罩保护他的花儿，并仔细地照看着他的小羊。", "t": [67138, 74050]}, {"ru": "Тогда я успокаиваюсь, и все звезды тихонько смеются.", "zh": "于是，我安心了，所有的星星都在悄然微笑。", "t": [74050, 78400]}, {"ru": "Однако порой я думаю — стоит один раз зазеваться, и этого будет достаточно!", "zh": "然而，一旦疏忽一次，便已足够。", "t": [78400, 83975]}, {"ru": "А что если однажды вечером он забудет про колпак, или же барашек тихонько уйдет ночью?", "zh": "或许，他有一天晚上会忘了玻璃罩，或者小羊儿会在夜里悄悄溜走？", "t": [83975, 89938]}, {"ru": "В такие ночи все бубенцы плачут…", "zh": "在这类夜晚，所有小铃铛都在哭泣……", "t": [89938, 93112]}, {"ru": "В этом скрыта великая тайна.", "zh": "这隐藏着伟大的奥秘。", "t": [93112, 95950]}, {"ru": "Ведь для вас, как и я, всем сердцем полюбивших маленького принца, ничто", "zh": "你们，如同我，心中满怀对小王子的深爱，一切皆有可能。", "t": [95950, 100525]}]}, {"id": "ch27p01", "audio": true, "sents": [{"ru": "во вселенной не будет уже прежним, если где-то там барашек, которого вы даже не видели, уже съел его розу.", "zh": "宇宙若因某处一只未曾谋面的绵羊吞食了他的玫瑰，便不再是从前那般模样。", "t": [100, 7075]}, {"ru": "Посмотрите на небо и задайте себе вопрос — это уже случилось или еще нет?", "zh": "仰望星空，问自己：这已是发生，抑或尚未？", "t": [7075, 12475]}, {"ru": "И вы увидите, как все меняется кругом от ответа на этот вопрос.", "zh": "你们就会看到，周围的一切因这问题的答案而改变。", "t": [12475, 17062]}, {"ru": "Ни один взрослый не поймет, насколько это важно!", "zh": "没有一个大人能理解这有多么重要！", "t": [17062, 20888]}, {"ru": "На этом рисунке для меня изображен самый прекрасный и в то же время самый грустный пейзаж на свете.", "zh": "这幅画映入眼帘，既是世间最美的风光，亦是最令人哀伤的景致。", "t": [20888, 27012]}, {"ru": "Это тот же самый пейзаж, что и на предыдущей странице.", "zh": "这画面与上一页别无二致。", "t": [27012, 31325]}, {"ru": "Я нарисовал его еще раз, чтобы вы могли его получше рассмотреть.", "zh": "我再次画下它，好让你们更仔细地观察。", "t": [31325, 36100]}, {"ru": "Именно здесь маленький принц появился на Земле, а потом исчез.", "zh": "小王子就是在这里降临地球，又从这里消失。", "t": [36100, 40900]}, {"ru": "Посмотрите на этот вид внимательно.", "zh": "请仔细观赏这景象。", "t": [40900, 43988]}, {"ru": "Просто для того, чтобы наверняка узнать его, если вы окажетесь", "zh": "只是为了确信，如果你们有幸遇见", "t": [43988, 47662]}]}, {"id": "ch27p02", "audio": true, "sents": [{"ru": "однажды в африканской пустыне.", "zh": "在非洲沙漠中。", "t": [100, 3000]}, {"ru": "И если вы окажетесь именно тут, прошу вас, не спешите.", "zh": "若您恰巧在此，请勿急于离去。", "t": [3000, 7712]}, {"ru": "Постойте немного, прямо здесь, под звездой!", "zh": "请在此稍作停留，就在这颗星星下。", "t": [7712, 11412]}, {"ru": "И если к вам подойдет малыш и засмеется, если волосы у него будут золотистые, и он не будет отвечать на ваши вопросы, вы узнаете, кто это.", "zh": "若有个孩子向你走来，他笑得灿烂，金发披肩，却对你的问题缄默不语，你便知道他是谁了。", "t": [11412, 20200]}, {"ru": "Тогда будьте так добры — не заставляйте меня больше грустить и скорее напишите, что он вернулся…", "zh": "请别再让我因思念他而悲伤，快写信告诉我，他回来了……", "t": [20200, 25412]}]}]}]}